import { useState, useMemo } from "react";
import type { ReactNode } from "react";
import {
  Button, Modal, Form, Input, InputNumber, Select,
  DatePicker, Drawer, Switch, Dropdown, Progress, message,
} from "antd";
import {
  PlusOutlined, EditOutlined, DeleteOutlined, MoreOutlined, CloseOutlined,
  TagsOutlined, CheckCircleOutlined, ClockCircleOutlined, RiseOutlined, SearchOutlined,
} from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { Voucher } from "@kawkaw/shared";
import dayjs from "dayjs";
import { DataTable } from "../components/DataTable";
import { AdminShell } from "../layouts/AdminShell";
import { useAdminVouchers, useCreateVoucher, useUpdateVoucher, useDeleteVoucher } from "../api/hooks";

/* ─── Styling maps ───────────────────────────────────────── */
const TYPE_TAG: Record<string, { color: string; bg: string; label: string }> = {
  percentage: { color: "#374151", bg: "#F3F4F6",  label: "PERCENTAGE" },
  fixed:      { color: "#1D4ED8", bg: "#DBEAFE",  label: "FIXED AMOUNT" },
  free_item:  { color: "#166534", bg: "#DCFCE7",  label: "FREE ITEM" },
};

const STATUS_PILL: Record<string, { color: string; bg: string }> = {
  active:    { color: "#166534", bg: "#DCFCE7" },
  scheduled: { color: "#1D4ED8", bg: "#DBEAFE" },
  expired:   { color: "#6B7280", bg: "#F3F4F6" },
  disabled:  { color: "#DC2626", bg: "#FEE2E2" },
};

/* ─── Stat card ──────────────────────────────────────────── */
function StatCard({
  icon, iconColor, badge, badgeColor, badgeBg, label, value,
}: {
  icon: ReactNode; iconColor: string;
  badge: string; badgeColor: string; badgeBg: string;
  label: string; value: number | string;
}) {
  return (
    <div style={{
      flex: 1, background: "#fff", borderRadius: 16,
      padding: "18px 22px",
      boxShadow: "0 1px 4px rgba(0,0,0,0.06)",
      border: "1px solid #F3F4F6",
    }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
        <span style={{ fontSize: 22, color: iconColor, display: "flex" }}>{icon}</span>
        <span style={{
          fontSize: 10, fontWeight: 800, letterSpacing: 0.8,
          padding: "2px 10px", borderRadius: 100,
          background: badgeBg, color: badgeColor,
        }}>
          {badge}
        </span>
      </div>
      <div style={{ fontSize: 12, color: "#9E9E9E", fontWeight: 600, marginBottom: 4 }}>{label}</div>
      <div style={{ fontSize: 30, fontWeight: 900, color: "#212121", lineHeight: 1 }}>
        {typeof value === "number" ? value.toLocaleString() : value}
      </div>
    </div>
  );
}

/* ─── Helper sub-components ─────────────────────────────── */
const DISCOUNT_TABS = [
  { value: "percentage", label: "Percentage" },
  { value: "fixed",      label: "Fixed RM" },
  { value: "free_item",  label: "Free Delivery" },
];

function DiscountTypeTabs({ value, onChange }: { value: string; onChange: (v: string) => void }) {
  return (
    <div style={{ display: "flex", gap: 4, background: "#F3F4F6", borderRadius: 10, padding: 4, marginBottom: 16 }}>
      {DISCOUNT_TABS.map(tab => (
        <button key={tab.value} type="button" onClick={() => onChange(tab.value)} style={{
          flex: 1, padding: "8px 4px", borderRadius: 8, border: "none", cursor: "pointer",
          background: value === tab.value ? "#F97316" : "transparent",
          color: value === tab.value ? "#fff" : "#616161",
          fontSize: 13, fontWeight: 700, transition: "all .15s",
        }}>{tab.label}</button>
      ))}
    </div>
  );
}

const APPLICABLE_TABS = [
  { value: "all",      label: "All",      icon: "≡" },
  { value: "pickup",   label: "Pickup",   icon: "🛒" },
  { value: "delivery", label: "Delivery", icon: "🚚" },
];

function ApplicableTabs({ value, onChange }: { value: string; onChange: (v: string) => void }) {
  return (
    <div style={{ display: "flex", gap: 4, background: "#F3F4F6", borderRadius: 10, padding: 4 }}>
      {APPLICABLE_TABS.map(tab => (
        <button key={tab.value} type="button" onClick={() => onChange(tab.value)} style={{
          flex: 1, padding: "8px 4px", borderRadius: 8, border: "none", cursor: "pointer",
          background: value === tab.value ? "#F97316" : "transparent",
          color: value === tab.value ? "#fff" : "#616161",
          fontSize: 13, fontWeight: 700, transition: "all .15s",
          display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
        }}>
          <span>{tab.icon}</span><span>{tab.label}</span>
        </button>
      ))}
    </div>
  );
}

function SectionLabel({ children }: { children: ReactNode }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16, marginTop: 24 }}>
      <span style={{ width: 8, height: 8, borderRadius: "50%", background: "#F97316", flexShrink: 0, display: "inline-block" }} />
      <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 1, color: "#F97316", textTransform: "uppercase" as const }}>{children}</span>
    </div>
  );
}

const FL = (text: string) => (
  <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.8, color: "#9E9E9E", textTransform: "uppercase" as const }}>{text}</span>
);

const genCode = () => {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  return Array.from({ length: 8 }, () => chars[Math.floor(Math.random() * chars.length)]).join("");
};

/* ─── Screen ─────────────────────────────────────────────── */
export function VouchersScreen() {
  const { t } = useTranslation();
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Voucher | null>(null);
  const [form] = Form.useForm();
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [typeFilter, setTypeFilter] = useState("all");
  const [discountType, setDiscountType] = useState("percentage");
  const [applicableTo, setApplicableTo] = useState("all");
  const [enableImmediately, setEnableImmediately] = useState(true);

  const { data, isLoading } = useAdminVouchers();
  const createVoucher = useCreateVoucher();
  const updateVoucher = useUpdateVoucher();
  const deleteVoucher = useDeleteVoucher();

  const vouchers = (data?.data ?? []) as unknown as Voucher[];

  /* Stats */
  const totalVouchers = vouchers.length;
  const activeCount   = vouchers.filter(v => v.status === "active").length;
  const expiredCount  = vouchers.filter(v => v.status === "expired").length;
  const totalRedeemed = vouchers.reduce((s, v) => s + (v.used_count ?? 0), 0);

  /* Filtered rows */
  const filtered = useMemo(() => {
    let rows = vouchers;
    if (search) {
      const q = search.toLowerCase();
      rows = rows.filter(v =>
        v.code.toLowerCase().includes(q) ||
        (v.name ?? "").toLowerCase().includes(q)
      );
    }
    if (statusFilter !== "all") rows = rows.filter(v => v.status === statusFilter);
    if (typeFilter   !== "all") rows = rows.filter(v => v.type   === typeFilter);
    return rows;
  }, [vouchers, search, statusFilter, typeFilter]);

  /* Handlers */
  const openCreate = () => {
    setEditing(null);
    form.resetFields();
    setDiscountType("percentage");
    setApplicableTo("all");
    setEnableImmediately(true);
    setModalOpen(true);
  };
  const openEdit = (v: Voucher) => {
    setEditing(v);
    setDiscountType(v.type ?? "percentage");
    setApplicableTo("all");
    setEnableImmediately(v.status === "active");
    form.setFieldsValue({
      ...v,
      discount_type:  v.type,
      discount_value: v.value,
      min_spend:      v.min_order,
      usage_limit:    v.total_uses,
      valid_from:  v.valid_from ? dayjs(v.valid_from) : null,
      valid_until: v.valid_to   ? dayjs(v.valid_to)   : null,
    });
    setModalOpen(true);
  };

  const confirmDelete = (row: Voucher) => {
    Modal.confirm({
      title:      t("vouchers.deleteConfirm",    "Disable this voucher?"),
      content:    t("vouchers.deleteConfirmDesc", "It will be marked disabled and unusable."),
      okText:     t("common.yes", "Yes"),
      cancelText: t("common.no",  "No"),
      okButtonProps: { danger: true },
      onOk: async () => {
        try {
          await deleteVoucher.mutateAsync(row.id);
          void message.success(t("vouchers.deleteSuccess", "Voucher disabled"));
        } catch {
          void message.error(t("vouchers.deleteFailed", "Failed to disable voucher"));
        }
      },
    });
  };

  const onSave = async (values: Record<string, unknown>) => {
    const payload = {
      ...values,
      discount_type: discountType,
      applicable_to: applicableTo,
      status: enableImmediately ? "active" : "scheduled",
      valid_from:  (values.valid_from  as dayjs.Dayjs | undefined)?.toISOString() ?? null,
      valid_until: (values.valid_until as dayjs.Dayjs | undefined)?.toISOString() ?? null,
    };
    try {
      if (editing) {
        await updateVoucher.mutateAsync({ id: editing.id, ...payload });
        void message.success(t("vouchers.updateSuccess"));
      } else {
        await createVoucher.mutateAsync(payload);
        void message.success(t("vouchers.createSuccess"));
      }
      setModalOpen(false);
    } catch {
      void message.error(t("vouchers.saveFailed"));
    }
  };

  /* Columns */
  const columns: ColumnsType<Voucher> = [
    {
      title: "CODE", dataIndex: "code", key: "code", width: 130,
      render: (v) => (
        <span style={{ fontFamily: "monospace", fontWeight: 800, color: "#F97316", fontSize: 13 }}>{v}</span>
      ),
    },
    {
      title: "VOUCHER NAME", key: "vname", width: 180,
      render: (_, row) => (
        <div>
          <div style={{ fontWeight: 700, fontSize: 13, color: "#212121" }}>{row.name}</div>
          {row.description && (
            <div style={{ fontSize: 12, color: "#9E9E9E", lineHeight: 1.4, marginTop: 2 }}>{row.description}</div>
          )}
        </div>
      ),
    },
    {
      title: "TYPE", dataIndex: "type", key: "type", width: 140,
      render: (v: string) => {
        const s = TYPE_TAG[v] ?? { color: "#374151", bg: "#F3F4F6", label: v.replace(/_/g, " ").toUpperCase() };
        return (
          <span style={{
            display: "inline-block", padding: "3px 10px", borderRadius: 100,
            background: s.bg, color: s.color, fontSize: 11, fontWeight: 700, letterSpacing: 0.5,
          }}>
            {s.label}
          </span>
        );
      },
    },
    {
      title: "VALUE", key: "value", width: 100, align: "right",
      render: (_, row) => {
        if (row.type === "percentage")
          return <span style={{ fontWeight: 700 }}>{row.value}%</span>;
        if (row.type === "free_item")
          return <span style={{ color: "#9E9E9E" }}>—</span>;
        return (
          <span style={{ fontWeight: 800, color: "#F97316" }}>
            RM {parseFloat(String(row.value)).toFixed(2)}
          </span>
        );
      },
    },
    {
      title: "MIN ORDER", dataIndex: "min_order", key: "min", width: 110, align: "right",
      render: (v) => {
        const num = parseFloat(String(v));
        return num > 0
          ? <span style={{ fontWeight: 600 }}>RM {num.toFixed(2)}</span>
          : <span style={{ color: "#9E9E9E" }}>—</span>;
      },
    },
    {
      title: "USAGE", key: "usage", width: 150,
      render: (_, row) => {
        const used  = row.used_count ?? 0;
        const total = row.total_uses ?? null;
        const pct   = total && total > 0 ? Math.round((used / total) * 100) : 0;
        return (
          <div style={{ minWidth: 110 }}>
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12 }}>
              <span style={{ color: "#212121", fontWeight: 600 }}>{used}/{total ?? "∞"}</span>
              {total !== null && (
                <span style={{ color: "#9E9E9E", fontSize: 11 }}>{pct}%</span>
              )}
            </div>
            {total !== null && (
              <Progress
                percent={pct} size="small" showInfo={false}
                strokeColor="#F97316" trailColor="#E5E7EB"
                style={{ marginTop: 4, marginBottom: 0 }}
              />
            )}
          </div>
        );
      },
    },
    {
      title: "VALID PERIOD", key: "period", width: 140,
      render: (_, row) => {
        const from = row.valid_from ? dayjs(row.valid_from).format("MMM DD") : null;
        const to   = row.valid_to   ? dayjs(row.valid_to).format("MMM DD")   : null;
        if (!from && !to) return <span style={{ color: "#9E9E9E" }}>Ongoing</span>;
        return <span style={{ fontSize: 12 }}>{from ?? "—"} – {to ?? "∞"}</span>;
      },
    },
    {
      title: "STATUS", dataIndex: "status", key: "status", width: 120,
      render: (v: string) => {
        const s = STATUS_PILL[v] ?? { color: "#374151", bg: "#F3F4F6" };
        return (
          <span style={{
            display: "inline-block", padding: "3px 12px", borderRadius: 100,
            background: s.bg, color: s.color, fontSize: 12, fontWeight: 800,
            textTransform: "uppercase",
          }}>
            {v}
          </span>
        );
      },
    },
    {
      title: "ACTIONS", key: "actions", width: 80, fixed: "right",
      render: (_, row) => (
        <Dropdown
          menu={{
            items: [
              { key: "edit",   icon: <EditOutlined />,   label: "EDIT" },
              { key: "delete", icon: <DeleteOutlined />, label: "DELETE", danger: true, disabled: row.status === "disabled" },
            ],
            onClick: ({ key }) => {
              if (key === "edit")   openEdit(row);
              if (key === "delete") confirmDelete(row);
            },
          }}
          trigger={["click"]}
          placement="bottomRight"
        >
          <Button type="text" icon={<MoreOutlined style={{ fontSize: 18 }} />} style={{ color: "#616161" }} />
        </Dropdown>
      ),
    },
  ];

  return (
    <AdminShell>
      {/* ── Page header ── */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
        <h2 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: "#212121" }}>Vouchers</h2>
        <Button
          type="primary" icon={<PlusOutlined />} onClick={openCreate}
          style={{ background: "#F97316", borderColor: "#F97316", height: 42, borderRadius: 10, fontWeight: 700, fontSize: 14, paddingInline: 20 }}
        >
          Create Voucher
        </Button>
      </div>

      {/* ── Stat cards ── */}
      <div style={{ display: "flex", gap: 16, marginBottom: 24 }}>
        <StatCard
          icon={<TagsOutlined />}         iconColor="#F97316"
          badge="OVERALL"  badgeColor="#92400E"  badgeBg="#FEF3C7"
          label="Total Vouchers" value={totalVouchers}
        />
        <StatCard
          icon={<CheckCircleOutlined />}  iconColor="#16A34A"
          badge="ACTIVE"   badgeColor="#166534"  badgeBg="#DCFCE7"
          label="Active" value={activeCount}
        />
        <StatCard
          icon={<ClockCircleOutlined />}  iconColor="#DC2626"
          badge="INACTIVE" badgeColor="#DC2626"  badgeBg="#FEE2E2"
          label="Expired" value={expiredCount}
        />
        <StatCard
          icon={<RiseOutlined />}         iconColor="#F97316"
          badge="GROWTH"   badgeColor="#92400E"  badgeBg="#FEF3C7"
          label="Total Redeemed" value={totalRedeemed}
        />
      </div>

      {/* ── Filter bar ── */}
      <div style={{ display: "flex", gap: 12, marginBottom: 20, alignItems: "center" }}>
        <Input
          prefix={<SearchOutlined style={{ color: "#9E9E9E" }} />}
          placeholder="Search by code or name..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          allowClear
          style={{ flex: 1, height: 40, borderRadius: 10 }}
        />
        <Select
          value={statusFilter}
          onChange={setStatusFilter}
          style={{ width: 140, height: 40 }}
          options={[
            { value: "all",       label: "All Status"  },
            { value: "active",    label: "Active"      },
            { value: "scheduled", label: "Scheduled"   },
            { value: "expired",   label: "Expired"     },
            { value: "disabled",  label: "Disabled"    },
          ]}
        />
        <Select
          value={typeFilter}
          onChange={setTypeFilter}
          style={{ width: 140, height: 40 }}
          options={[
            { value: "all",        label: "All Types"    },
            { value: "percentage", label: "Percentage"   },
            { value: "fixed",      label: "Fixed Amount" },
            { value: "free_item",  label: "Free Item"    },
          ]}
        />
      </div>

      {/* ── Table ── */}
      <DataTable<Voucher>
        columns={columns}
        dataSource={filtered as unknown as Voucher[]}
        loading={isLoading}
      />

      {/* ── Create / Edit Drawer ── */}
      <Drawer
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        width={460}
        closeIcon={null}
        title={
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
            <div>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span style={{ fontSize: 20, fontWeight: 800, color: "#212121", lineHeight: 1.2 }}>
                  {editing ? "Edit Voucher" : "Create Voucher"}
                </span>
                {editing && (() => {
                  const statusKey = editing.status ?? "active";
                  const s = STATUS_PILL[statusKey] ?? { color: "#374151", bg: "#F3F4F6" };
                  return (
                    <span style={{
                      fontSize: 11, fontWeight: 800, letterSpacing: 0.6,
                      padding: "3px 10px", borderRadius: 100,
                      background: s.bg, color: s.color, textTransform: "uppercase",
                    }}>
                      {statusKey}
                    </span>
                  );
                })()}
              </div>
              <div style={{ fontSize: 13, color: "#9E9E9E", marginTop: 4, fontWeight: 400 }}>
                {editing ? editing.code : "Configure your promotion details below"}
              </div>
            </div>
            <Button type="text" icon={<CloseOutlined />} onClick={() => setModalOpen(false)}
              style={{ color: "#616161", marginTop: -4, marginRight: -8 }} />
          </div>
        }
        footer={
          <div style={{ display: "flex", gap: 12, padding: "4px 0" }}>
            <Button
              style={{ flex: 1, height: 48, borderRadius: 10, fontWeight: 700, fontSize: 14 }}
              onClick={() => setModalOpen(false)}
            >
              CANCEL
            </Button>
            <Button
              type="primary"
              style={{ flex: 2, height: 48, borderRadius: 10, fontWeight: 700, fontSize: 14, background: "#F97316", borderColor: "#F97316" }}
              loading={createVoucher.isPending || updateVoucher.isPending}
              onClick={() => void form.submit()}
            >
              {editing ? "SAVE CHANGES" : "SAVE VOUCHER"}
            </Button>
          </div>
        }
        styles={{ footer: { padding: "16px 24px", borderTop: "1px solid #F3F4F6" } }}
        maskClosable={false}
        destroyOnClose
      >
        <Form form={form} layout="vertical" onFinish={onSave} colon={false}>

          {/* ── BASIC INFORMATION ── */}
          <SectionLabel>Basic Information</SectionLabel>

          <Form.Item name="name" label={FL("Voucher Name")} style={{ marginBottom: 14 }}>
            <Input
              placeholder="e.g., Weekend Coffee Deal"
              style={{ height: 44, borderRadius: 10, background: "#F9FAFB" }}
            />
          </Form.Item>

          <Form.Item label={FL("Voucher Code")} required style={{ marginBottom: 14 }}>
            <div style={{ display: "flex", gap: 8 }}>
              <Form.Item name="code" rules={[{ required: true, message: "Code is required" }]} noStyle>
                <Input
                  style={{ flex: 1, height: 44, borderRadius: 10, fontFamily: "monospace", fontWeight: 700, background: "#F9FAFB" }}
                  onChange={e => form.setFieldValue("code", e.target.value.toUpperCase())}
                />
              </Form.Item>
              <Button
                onClick={() => form.setFieldValue("code", genCode())}
                style={{ height: 44, borderRadius: 10, background: "#FFF7ED", border: "1px solid #F97316", color: "#F97316", fontWeight: 700, flexShrink: 0, fontSize: 12 }}
              >
                AUTO-GENERATE
              </Button>
            </div>
          </Form.Item>

          <Form.Item name="description" label={FL("Description")} style={{ marginBottom: 8 }}>
            <Input.TextArea rows={3} style={{ borderRadius: 10, background: "#F9FAFB", resize: "none" }} />
          </Form.Item>

          {/* ── DISCOUNT SETTINGS ── */}
          <SectionLabel>Discount Settings</SectionLabel>

          <DiscountTypeTabs value={discountType} onChange={v => setDiscountType(v)} />

          {/* Percentage: value + max cap side-by-side */}
          {discountType === "percentage" && (
            <div style={{ display: "flex", gap: 12, marginBottom: 14 }}>
              <Form.Item
                name="discount_value"
                label={FL("Value (%)")}
                rules={[{ required: true }]}
                style={{ flex: 1, marginBottom: 0 }}
              >
                <InputNumber min={0} max={100} precision={2} placeholder="15" style={{ width: "100%", height: 44, borderRadius: 10 }} />
              </Form.Item>
              <Form.Item name="max_cap" label={FL("Max Cap (RM)")} style={{ flex: 1, marginBottom: 0 }}>
                <InputNumber min={0} precision={2} placeholder="10.00" style={{ width: "100%", height: 44, borderRadius: 10 }} />
              </Form.Item>
            </div>
          )}

          {/* Fixed RM: single full-width discount amount */}
          {discountType === "fixed" && (
            <Form.Item
              name="discount_value"
              label={FL("Discount Amount (RM)")}
              rules={[{ required: true }]}
              style={{ marginBottom: 14 }}
            >
              <InputNumber min={0} precision={2} placeholder="5.00" style={{ width: "100%", height: 44, borderRadius: 10 }} />
            </Form.Item>
          )}

          {/* Free Delivery: info text only, no amount input */}
          {discountType === "free_item" && (
            <div style={{ fontSize: 13, color: "#616161", marginBottom: 14, padding: "10px 0" }}>
              Delivery fee will be waived entirely
            </div>
          )}

          {/* Min order — all tabs */}
          <Form.Item name="min_spend" label={FL("Minimum Order Value (RM)")} style={{ marginBottom: 8 }}>
            <InputNumber min={0} precision={2} placeholder="25.00" style={{ width: "100%", height: 44, borderRadius: 10 }} />
          </Form.Item>

          {/* ── USAGE LIMITS ── */}
          <SectionLabel>Usage Limits</SectionLabel>

          <div style={{ display: "flex", gap: 12, marginBottom: 8 }}>
            <Form.Item name="usage_limit" label={FL("Total Usage Limit")} style={{ flex: 1, marginBottom: 0 }}>
              <InputNumber min={1} placeholder="100" style={{ width: "100%", height: 44, borderRadius: 10 }} />
            </Form.Item>
            <Form.Item name="per_customer" label={FL("Per Customer")} style={{ flex: 1, marginBottom: 0 }}>
              <InputNumber min={1} placeholder="1" style={{ width: "100%", height: 44, borderRadius: 10 }} />
            </Form.Item>
          </div>

          {/* ── VALIDITY PERIOD ── */}
          <SectionLabel>Validity Period</SectionLabel>

          <div style={{ display: "flex", gap: 12, marginBottom: 16 }}>
            <Form.Item name="valid_from" label={FL("Start Date")} style={{ flex: 1, marginBottom: 0 }}>
              <DatePicker style={{ width: "100%", height: 44, borderRadius: 10 }} />
            </Form.Item>
            <Form.Item name="valid_until" label={FL("End Date")} style={{ flex: 1, marginBottom: 0 }}>
              <DatePicker style={{ width: "100%", height: 44, borderRadius: 10 }} />
            </Form.Item>
          </div>

          <div style={{
            display: "flex", alignItems: "center", justifyContent: "space-between",
            background: "#F9FAFB", border: "1px solid #E5E7EB", borderRadius: 12, padding: "14px 16px",
          }}>
            <div>
              <div style={{ fontSize: 14, fontWeight: 700, color: "#212121" }}>Enable Voucher immediately</div>
              <div style={{ fontSize: 11, color: "#9E9E9E", marginTop: 2, letterSpacing: 0.3 }}>
                STATUS WILL BE 'ACTIVE' UPON SAVING
              </div>
            </div>
            <Switch
              checked={enableImmediately}
              onChange={setEnableImmediately}
              style={{ background: enableImmediately ? "#16A34A" : undefined }}
            />
          </div>

          {/* ── APPLICABLE TO ── */}
          <SectionLabel>Applicable To</SectionLabel>
          <ApplicableTabs value={applicableTo} onChange={setApplicableTo} />

        </Form>
      </Drawer>
    </AdminShell>
  );
}
