// ── Status styles ─────────────────────────────────────────────────────────────
const STATUS_STYLE: Record<string, { bg: string; color: string }> = {
  preparing:        { bg: "#FFF3E0", color: "#F97316" },
  ready:            { bg: "#166534", color: "#fff" },
  out_for_delivery: { bg: "#CCFBF1", color: "#0F766E" },
  in_transit:       { bg: "#F3F4F6", color: "#6B7280" },
  delivered:        { bg: "#14532D", color: "#fff" },
  completed:        { bg: "#14532D", color: "#fff" },
  cancelled:        { bg: "#F3F4F6", color: "#9E9E9E" },
  new:              { bg: "#FFF8E1", color: "#F57F17" },
};

function StatusPill({ status, size = "md" }: { status: string; size?: "sm" | "md" }) {
  const s = STATUS_STYLE[status] ?? { bg: "#F3F4F6", color: "#9E9E9E" };
  return (
    <span style={{
      background: s.bg, color: s.color, borderRadius: 20,
      padding: size === "sm" ? "3px 10px" : "5px 16px",
      fontSize: size === "sm" ? 11 : 12,
      fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.5,
      whiteSpace: "nowrap", display: "inline-block",
    }}>
      {status.replace(/_/g, " ")}
    </span>
  );
}

function TypePill({ type }: { type: string }) {
  const isDelivery = type === "delivery";
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 5,
      background: isDelivery ? "#EFF6FF" : "#F0FDF4",
      color: isDelivery ? "#1D4ED8" : "#15803D",
      border: `1px solid ${isDelivery ? "#BFDBFE" : "#BBF7D0"}`,
      borderRadius: 20, padding: "5px 14px",
      fontSize: 12, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.5,
    }}>
      {isDelivery ? <CarOutlined /> : <ShoppingOutlined />}
      {type}
    </span>
  );
}

// ── Contextual status message ─────────────────────────────────────────────────
function statusMessage(od: OrderDetailData): string {
  switch (od.status) {
    case "new":              return "Waiting for stall to accept this order";
    case "preparing":        return "Stall is preparing the order";
    case "ready":            return od.type === "pickup" ? "Order is ready — waiting for customer pickup" : "Order ready — awaiting rider assignment";
    case "out_for_delivery": return "Rider is on the way to collect";
    case "in_transit":       return "Order is out for delivery";
    case "delivered":        return "Order has been delivered to customer";
    case "completed":        return od.type === "pickup" ? "Order picked up by customer" : "Order completed";
    case "cancelled":        return `Order cancelled${(od as OrderDetailData).cancel_reason ? `: ${(od as OrderDetailData).cancel_reason}` : ""}`;
    default:                 return "";
  }
}

// ── Journey step builder ──────────────────────────────────────────────────────
const STATUS_IDX: Record<string, number> = {
  new: 0, preparing: 1, ready: 2, out_for_delivery: 3, in_transit: 4,
  delivered: 5, completed: 6, cancelled: 99,
};

interface JStep { label: string; time?: string | null; state: "done" | "active" | "pending"; subtext?: string }

function buildJourney(od: OrderDetailData): JStep[] {
  const curIdx = STATUS_IDX[od.status] ?? 0;
  const st = (thresholdIdx: number): "done" | "active" | "pending" =>
    curIdx > thresholdIdx ? "done" : curIdx === thresholdIdx ? "active" : "pending";

  const base: JStep[] = [
    { label: "Order Created", time: od.created_at,  state: "done" },
    { label: "Accepted",      time: od.accepted_at, state: curIdx > 0 ? "done" : "pending" },
    { label: "Preparing",     time: null,            state: st(1) },
    { label: "Ready",         time: od.ready_at,    state: st(2) },
  ];

  if (od.type === "delivery") {
    return [
      ...base.map(s => s.label === "Ready" && s.state === "pending" ? { ...s, subtext: "Waiting for pickup" } : s),
      { label: "Rider Assigned",   time: od.rider?.assigned_at ?? null, state: st(3) },
      { label: "Rider Arrived",    time: null,                           state: curIdx >= 4 ? "done" : "pending" },
      { label: "Out for Delivery", time: od.dispatched_at ?? null,       state: st(4) },
      { label: "Delivered",        time: od.delivered_at ?? null,        state: st(5) },
    ];
  }

  return [
    ...base,
    { label: "Picked Up", time: od.completed_at, state: st(6) },
  ];
}

