import { useState } from "react";
import { Upload, App } from "antd";
import { LoadingOutlined, PlusOutlined } from "@ant-design/icons";
import type { UploadChangeParam, UploadFile } from "antd/es/upload";
import { useCloudinarySign } from "../api/hooks";

interface Props {
  value?: string;
  onChange?: (url: string) => void;
  folder?: string;
}

export function ImageUpload({ value, onChange, folder = "menu" }: Props) {
  const [loading, setLoading] = useState(false);
  const { message } = App.useApp();
  const sign = useCloudinarySign();

  const beforeUpload = (file: File) => {
    const ok = file.type.startsWith("image/");
    if (!ok) { void message.error("Only image files are allowed"); }
    const small = file.size / 1024 / 1024 < 5;
    if (!small) { void message.error("Image must be under 5 MB"); }
    return ok && small;
  };

  const customUpload = async ({ file, onSuccess, onError }: {
    file: File | string | Blob;
    onSuccess?: (body: unknown) => void;
    onError?: (err: Error) => void;
  }) => {
    setLoading(true);
    try {
      const { data } = await sign.mutateAsync(folder);
      const fd = new FormData();
      fd.append("file", file as File);
      fd.append("api_key", data.apiKey);
      fd.append("timestamp", String(data.timestamp));
      fd.append("signature", data.signature);
      fd.append("folder", data.folder);
      const res = await fetch(
        `https://api.cloudinary.com/v1_1/${data.cloudName}/image/upload`,
        { method: "POST", body: fd },
      );
      const json = await res.json() as { secure_url: string };
      onChange?.(json.secure_url);
      onSuccess?.(json);
    } catch (err) {
      onError?.(err as Error);
      void message.error("Upload failed");
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (info: UploadChangeParam<UploadFile>) => {
    if (info.file.status === "uploading") setLoading(true);
    if (info.file.status !== "uploading") setLoading(false);
  };

  return (
    <Upload
      listType="picture-card"
      showUploadList={false}
      beforeUpload={beforeUpload}
      customRequest={customUpload as never}
      onChange={handleChange}
    >
      {value ? (
        <img src={value} alt="preview" style={{ width: "100%", height: "100%", objectFit: "cover", borderRadius: 6 }} />
      ) : (
        <div>
          {loading ? <LoadingOutlined /> : <PlusOutlined />}
          <div style={{ marginTop: 8, fontSize: 12 }}>Upload</div>
        </div>
      )}
    </Upload>
  );
}
