import { useParams, useNavigate } from "react-router-dom";
import { Button, Skeleton, Typography } from "antd";
import {
  ArrowLeftOutlined, UserOutlined, TransactionOutlined,
  FileTextOutlined, DollarOutlined, CheckCircleFilled,
  ClockCircleFilled, InfoCircleFilled,
} from "@ant-design/icons";
import dayjs from "dayjs";
import { AdminShell } from "../layouts/AdminShell";
import { useAdminRefund } from "../api/hooks";

const { Text } = Typography;

// ─── Constants ───────────────────────────────────────────────────────────────

const STATUS_MAP: Record<string, { bg: string; color: string; label: string }> = {
  success:  { bg: "#D1FAE5", color: "#065F46", label: "COMPLETED" },
  pending:  { bg: "#FEF3C7", color: "#92400E", label: "PROCESSING" },
  rejected: { bg: "#FEE2E2", color: "#991B1B", label: "REJECTED" },
  failed:   { bg: "#F3F4F6", color: "#6B7280", label: "FAILED" },
};

const DEFAULT_STATUS = { bg: "#FEF3C7", color: "#92400E", label: "PROCESSING" };

const TYPE_MAP: Record<string, string> = {
  full: "Full Refund",
  partial: "Partial Refund",
};

// ─── Helpers ─────────────────────────────────────────────────────────────────

function Card({ children, style }: { children: React.ReactNode; style?: React.CSSProperties }) {
  return (
    <div style={{
      background: "#fff", borderRadius: 12, border: "1px solid #E5E7EB",
      padding: "20px 24px", ...style,
    }}>
      {children}
    </div>
  );
}

function SectionLabel({ children, icon }: { children: React.ReactNode; icon?: React.ReactNode }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}>
      {icon && <span style={{ color: "#9E9E9E", fontSize: 14 }}>{icon}</span>}
      <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.8, color: "#9E9E9E", textTransform: "uppercase" }}>
        {children}
      </span>
    </div>
  );
}

function InfoRow({ label, value }: { label: string; value: React.ReactNode }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 12, gap: 12 }}>
      <span style={{ fontSize: 13, color: "#616161", flexShrink: 0 }}>{label}</span>
      <span style={{ fontSize: 13, fontWeight: 600, color: "#212121", textAlign: "right" }}>{value}</span>
    </div>
  );
}

// ─── Timeline ────────────────────────────────────────────────────────────────

type TimelineEvent = {
  label: string;
  time: string;
  staff: string;
  dotColor: string;
};

function buildTimeline(
  logs: Array<{ id: string; action: string; created_at: string; meta: Record<string, unknown> | null; staff: { name: string } | null }>,
  refundStatus: string,
  createdAt: string,
): TimelineEvent[] {
  const events: TimelineEvent[] = [];

  // Always include creation event
  const createLog = logs.find((l) => l.action === "refund.created" || l.action === "create");
  events.push({
    label: "Refund Created",
    time: dayjs(createLog?.created_at ?? createdAt).format("MM/DD/YYYY, hh:mm A"),
    staff: createLog?.staff?.name ?? "System",
    dotColor: "#9E9E9E",
  });

  // Processing event (any review/processing action)
  const processLog = logs.find((l) =>
    l.action === "refund.reviewed" || l.action === "review" ||
    l.action === "refund.processing" || l.action === "update"
  );
  if (processLog) {
    events.push({
      label: "Processing",
      time: dayjs(processLog.created_at).format("MM/DD/YYYY, hh:mm A"),
      staff: processLog.staff?.name ?? "Admin",
      dotColor: "#F97316",
    });
  }

  // Completed / Rejected event
  if (refundStatus === "success") {
    const completeLog = logs.find((l) => l.action === "refund.completed" || l.action === "approve");
    events.push({
      label: "Refund Completed",
      time: completeLog ? dayjs(completeLog.created_at).format("MM/DD/YYYY, hh:mm A") : "—",
      staff: completeLog?.staff?.name ?? "Admin",
      dotColor: "#16A34A",
    });
  } else if (refundStatus === "rejected") {
    const rejectLog = logs.find((l) => l.action === "refund.rejected" || l.action === "reject");
    events.push({
      label: "Refund Rejected",
      time: rejectLog ? dayjs(rejectLog.created_at).format("MM/DD/YYYY, hh:mm A") : "—",
      staff: rejectLog?.staff?.name ?? "Admin",
      dotColor: "#DC2626",
    });
  }

  return events.reverse(); // Most recent first
}

// ─── Main screen ─────────────────────────────────────────────────────────────

export function RefundDetailScreen() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { data: refund, isLoading } = useAdminRefund(id);

  if (isLoading) {
    return (
      <AdminShell>
        <div style={{ padding: "28px 32px" }}>
          <Skeleton active paragraph={{ rows: 10 }} />
        </div>
      </AdminShell>
    );
  }

  if (!refund) {
    return (
      <AdminShell>
        <div style={{ padding: "28px 32px", color: "#DC2626" }}>Refund not found.</div>
      </AdminShell>
    );
  }

  const statusInfo = STATUS_MAP[refund.status] ?? DEFAULT_STATUS;
  const typeLabel = TYPE_MAP[refund.type] ?? refund.type;
  const customer = refund.order?.customer ?? refund.customer;
  const meta = refund.activity_logs?.[0]?.meta as Record<string, unknown> | null ?? null;
  const customerExtra = (customer ?? {}) as Record<string, unknown>;
  const customerPhone = typeof customerExtra.phone === "string" ? customerExtra.phone : null;
  const customerEmail = typeof customerExtra.email === "string" ? customerExtra.email : null;

  // Extract transfer details from activity log meta (stored during approve)
  let transferMethod = "";
  let transferTime = "";
  let merchantNote = "";

  for (const log of refund.activity_logs ?? []) {
    if (log.meta?.transfer_method) {
      transferMethod = String(log.meta.transfer_method);
      transferTime = String(log.meta.transfer_time ?? "");
      merchantNote = String(log.meta.note ?? "");
      break;
    }
  }
  // Also check rejection note as merchant note
  if (!merchantNote && refund.rejection_note) merchantNote = refund.rejection_note;

  const rfdId = `RF-${refund.id.slice(-4).toUpperCase()}`;
  const txnRef = refund.transaction?.reference?.toUpperCase()
    ?? `TXN-${refund.transaction?.id?.slice(0, 16).toUpperCase() ?? "—"}`;
  const orderCode = refund.order?.order_code ?? "—";

  const timeline = buildTimeline(refund.activity_logs ?? [], refund.status, refund.created_at);

  // void meta (unused if no transfer details)
  void meta;

  return (
    <AdminShell>
      <div style={{ padding: "28px 32px", background: "#F9FAFB", minHeight: "100vh" }}>

        {/* Header */}
        <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 28 }}>
          <Button
            type="text"
            icon={<ArrowLeftOutlined />}
            onClick={() => navigate("/refunds")}
            style={{ fontWeight: 700, color: "#616161" }}
          >
            Back
          </Button>
          <div style={{ fontSize: 24, fontWeight: 800, color: "#212121" }}>Refund Details</div>
          <span style={{
            background: statusInfo.bg, color: statusInfo.color,
            borderRadius: 20, padding: "4px 14px", fontSize: 12, fontWeight: 800, letterSpacing: 0.5,
          }}>
            {statusInfo.label}
          </span>
        </div>

        {/* Top row: 2 columns */}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: 16 }}>

          {/* Left: Refund info */}
          <Card>
            <div style={{ marginBottom: 20 }}>
              <div style={{ fontSize: 12, color: "#9E9E9E", fontWeight: 700, letterSpacing: 0.5, textTransform: "uppercase", marginBottom: 6 }}>
                REFUND ID
              </div>
              <div style={{ fontSize: 32, fontWeight: 900, color: "#212121" }}>{rfdId}</div>
            </div>
            <div style={{ marginBottom: 20 }}>
              <div style={{ fontSize: 12, color: "#9E9E9E", fontWeight: 700, textTransform: "uppercase", marginBottom: 6 }}>
                AMOUNT RECLAIMED
              </div>
              <div style={{ fontSize: 28, fontWeight: 900, color: "#F97316" }}>
                RM {Number(refund.amount).toFixed(2)}
              </div>
            </div>
            <InfoRow label="Refund Type" value={typeLabel} />
            <InfoRow label="Created Time" value={dayjs(refund.created_at).format("MM/DD/YYYY hh:mm A")} />
            <InfoRow label="Request Source" value="POS Terminal" />
          </Card>

          {/* Right: Customer info */}
          <Card>
            <SectionLabel icon={<UserOutlined />}>Customer Info</SectionLabel>
            {customer ? (
              <>
                <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16 }}>
                  <div style={{
                    width: 44, height: 44, borderRadius: "50%",
                    background: "#FFF7ED", display: "flex", alignItems: "center", justifyContent: "center",
                    fontSize: 18, color: "#F97316", fontWeight: 800,
                  }}>
                    {(customer.name ?? "G").charAt(0).toUpperCase()}
                  </div>
                  <div>
                    <div style={{ fontSize: 15, fontWeight: 700, color: "#212121" }}>
                      {customer.name ?? "Guest"}
                    </div>
                    <div style={{ fontSize: 11, color: "#9E9E9E" }}>CUST-{customer.id.slice(-4)}</div>
                  </div>
                </div>
                {customerPhone && <InfoRow label="Phone" value={customerPhone} />}
                {customerEmail && <InfoRow label="Email" value={customerEmail} />}
              </>
            ) : (
              <Text style={{ color: "#9E9E9E" }}>No customer info</Text>
            )}
          </Card>
        </div>

        {/* Middle row: 2 columns */}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: 16 }}>

          {/* Left: Transaction info */}
          <Card>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 16 }}>
              <SectionLabel icon={<TransactionOutlined />}>Transaction Info</SectionLabel>
              <Button
                type="link"
                size="small"
                style={{ color: "#F97316", fontWeight: 700, padding: 0 }}
                onClick={() => navigate(`/transactions/${refund.transaction?.id}`)}
              >
                View Transaction →
              </Button>
            </div>
            <InfoRow label="Transaction ID" value={
              <span style={{ fontFamily: "monospace", color: "#F97316" }}>{txnRef}</span>
            } />
            <InfoRow label="Order ID" value={
              <span
                style={{ color: "#F97316", fontWeight: 700, cursor: "pointer" }}
                onClick={() => navigate(`/orders/${refund.order?.id ?? ""}`)}
              >
                #{orderCode}
              </span>
            } />
            <InfoRow label="Payment Method" value={refund.transaction?.method ?? "—"} />
            <InfoRow label="Total Paid" value={`RM ${Number(refund.transaction?.amount ?? 0).toFixed(2)}`} />
          </Card>

          {/* Right stacked: Reason + Note + Transfer Details */}
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>

            {/* Reason */}
            <Card style={{ padding: "16px 20px" }}>
              <SectionLabel icon={<FileTextOutlined />}>Refund Reason</SectionLabel>
              <Text style={{ fontSize: 14, color: "#212121" }}>{refund.reason}</Text>
            </Card>

            {/* Internal note */}
            {merchantNote && !transferMethod && (
              <Card style={{ padding: "16px 20px" }}>
                <SectionLabel icon={<InfoCircleFilled />}>Internal Note</SectionLabel>
                <Text style={{ fontSize: 14, color: "#212121" }}>{merchantNote}</Text>
              </Card>
            )}

            {/* Transfer details */}
            {transferMethod && (
              <div style={{
                background: "#F0FDF4", border: "1px solid #BBF7D0",
                borderRadius: 12, padding: "16px 20px",
              }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}>
                  <DollarOutlined style={{ color: "#16A34A", fontSize: 16 }} />
                  <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.8, color: "#16A34A", textTransform: "uppercase" }}>
                    Transfer Details
                  </span>
                </div>
                <InfoRow label="Method" value={transferMethod} />
                {transferTime && <InfoRow label="Time" value={transferTime} />}
                {merchantNote && (
                  <div style={{ marginTop: 8 }}>
                    <div style={{ fontSize: 11, color: "#16A34A", fontWeight: 700, marginBottom: 4 }}>MERCHANT NOTE</div>
                    <Text italic style={{ fontSize: 13, color: "#166534" }}>{merchantNote}</Text>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Process Timeline */}
        <Card>
          <SectionLabel icon={<ClockCircleFilled />}>Process Timeline</SectionLabel>
          <div style={{ paddingLeft: 8 }}>
            {timeline.map((event, i) => (
              <div key={i} style={{ display: "flex", gap: 16, position: "relative", paddingBottom: i < timeline.length - 1 ? 24 : 0 }}>
                {/* Vertical line */}
                {i < timeline.length - 1 && (
                  <div style={{
                    position: "absolute", left: 9, top: 20, bottom: 0,
                    width: 2, background: "#E5E7EB",
                  }} />
                )}
                {/* Dot */}
                <div style={{
                  width: 20, height: 20, borderRadius: "50%",
                  background: event.dotColor, flexShrink: 0, marginTop: 2,
                  display: "flex", alignItems: "center", justifyContent: "center",
                }}>
                  <div style={{ width: 8, height: 8, borderRadius: "50%", background: "#fff" }} />
                </div>
                {/* Content */}
                <div>
                  <div style={{ fontSize: 14, fontWeight: 700, color: "#212121" }}>{event.label}</div>
                  <div style={{ fontSize: 12, color: "#9E9E9E", marginTop: 2 }}>
                    {event.time} &nbsp;/&nbsp; {event.staff}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </Card>

      </div>
    </AdminShell>
  );
}
