import { useState } from "react";
import {
  Button, Modal, Drawer, Form, Input, InputNumber, Switch,
  Typography, Space, Tag, Tooltip, App,
} from "antd";
import { EditOutlined, PlusOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { Stall } from "@kawkaw/shared";
import { DataTable } from "../components/DataTable";
import { AdminShell } from "../layouts/AdminShell";
import { useAdminStalls, useUpdateStall, useCreateStall } from "../api/hooks";

const { Title } = Typography;

// ─── Section header used in the Add Stall modal ─────────────────────────────
function SectionHeader({ icon, label }: { icon: React.ReactNode; label: string }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16, marginTop: 4 }}>
      <div style={{
        width: 28, height: 28, borderRadius: "50%",
        display: "flex", alignItems: "center", justifyContent: "center",
        fontSize: 14,
      }}>
        {icon}
      </div>
      <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 1, color: "#212121", textTransform: "uppercase" }}>
        {label}
      </span>
    </div>
  );
}

// ─── Add Stall Drawer (Figma 57-1546) ───────────────────────────────────────
type AddStallValues = {
  name: string;
  description?: string | null;
  is_open: boolean;
  sort_order: number;
};

function AddStallModal({ open, onClose }: { open: boolean; onClose: () => void }) {
  const { message } = App.useApp();
  const [form] = Form.useForm<AddStallValues>();
  const createStall = useCreateStall();

  const onFinish = async (values: AddStallValues) => {
    try {
      await createStall.mutateAsync({
        name: values.name,
        description: values.description ?? null,
        is_open: values.is_open,
        sort_order: values.sort_order,
      });
      void message.success("Stall created");
      form.resetFields();
      onClose();
    } catch {
      void message.error("Failed to create stall");
    }
  };

  const handleDiscard = () => {
    form.resetFields();
    onClose();
  };

  return (
    <Drawer
      open={open}
      onClose={handleDiscard}
      placement="right"
      width={420}
      title={<span style={{ fontSize: 18, fontWeight: 800, color: "#212121" }}>Add Stall</span>}
      footer={null}
      closeIcon={<span style={{ fontSize: 18, color: "#9E9E9E" }}>×</span>}
      styles={{ body: { padding: "20px 24px" } }}
    >
      <Form
        form={form}
        layout="vertical"
        onFinish={onFinish}
        initialValues={{ is_open: true, sort_order: 1 }}
        style={{ paddingTop: 8 }}
      >
        {/* ── BASIC INFO ────────────────────────────── */}
        <SectionHeader
          icon={<span style={{ fontSize: 16, background: "#FFF7ED", borderRadius: "50%", width: 28, height: 28, display: "flex", alignItems: "center", justifyContent: "center" }}>ℹ️</span>}
          label="Basic Info"
        />
        <Form.Item
          name="name"
          label={<span style={{ fontWeight: 600, fontSize: 13, color: "#212121" }}>Stall Name <span style={{ color: "#DC2626" }}>*</span></span>}
          rules={[{ required: true, message: "Stall name is required" }, { max: 120 }]}
          style={{ marginBottom: 16 }}
        >
          <Input
            placeholder="e.g. Beverage Stall"
            maxLength={120}
            style={{ borderRadius: 10, height: 44, fontSize: 14, color: "#9E9E9E" }}
          />
        </Form.Item>
        <Form.Item
          name="description"
          label={<span style={{ fontWeight: 600, fontSize: 13, color: "#212121" }}>Description</span>}
          style={{ marginBottom: 24 }}
        >
          <Input.TextArea
            placeholder="Short description of stall"
            maxLength={400}
            rows={3}
            style={{ borderRadius: 10, fontSize: 14, resize: "none", color: "#9E9E9E" }}
          />
        </Form.Item>

        <div style={{ borderTop: "1px solid #F3F4F6", marginBottom: 20 }} />

        {/* ── STATUS ────────────────────────────────── */}
        <SectionHeader
          icon={<span style={{ fontSize: 16, background: "#F0FDF4", borderRadius: "50%", width: 28, height: 28, display: "flex", alignItems: "center", justifyContent: "center" }}>⚡</span>}
          label="Status"
        />
        <div style={{
          background: "#F9FAFB", borderRadius: 12,
          padding: "14px 16px",
          display: "flex", alignItems: "center", justifyContent: "space-between",
          marginBottom: 24,
        }}>
          <div>
            <div style={{ fontWeight: 700, fontSize: 14, color: "#212121" }}>Stall Status</div>
            <div style={{ fontSize: 12, color: "#9E9E9E", marginTop: 2, maxWidth: 230 }}>
              If paused, all items under this stall will be unavailable
            </div>
          </div>
          <Form.Item name="is_open" valuePropName="checked" noStyle>
            <Switch />
          </Form.Item>
        </div>

        <div style={{ borderTop: "1px solid #F3F4F6", marginBottom: 20 }} />

        {/* ── DISPLAY ORDER ─────────────────────────── */}
        <SectionHeader
          icon={<span style={{ fontSize: 16, background: "#EFF6FF", borderRadius: "50%", width: 28, height: 28, display: "flex", alignItems: "center", justifyContent: "center" }}>☰</span>}
          label="Display Order"
        />
        <Form.Item name="sort_order" style={{ marginBottom: 4 }}>
          <InputNumber
            min={0}
            style={{ width: 120, borderRadius: 10, height: 44 }}
          />
        </Form.Item>
        <div style={{ fontSize: 12, color: "#9E9E9E", marginBottom: 24 }}>
          Lower number appears first in the customer app
        </div>

        <div style={{ borderTop: "1px solid #F3F4F6", marginBottom: 20 }} />

        {/* ── OPENING HOURS ─────────────────────────── */}
        <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 1, color: "#212121", textTransform: "uppercase", marginBottom: 14 }}>
          Opening Hours
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 12 }}>
          <span style={{ fontWeight: 600, fontSize: 14, color: "#212121" }}>Mon – Fri</span>
          <span style={{ fontSize: 14, color: "#616161" }}>08:00 AM – 10:00 PM</span>
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 28 }}>
          <span style={{ fontWeight: 600, fontSize: 14, color: "#212121" }}>Sat – Sun</span>
          <span style={{ fontSize: 14, color: "#616161" }}>09:00 AM – 11:00 PM</span>
        </div>

        {/* ── FOOTER BUTTONS ────────────────────────── */}
        <div style={{ display: "flex", gap: 12 }}>
          <Button
            onClick={handleDiscard}
            style={{ flex: 1, height: 48, borderRadius: 24, fontWeight: 700, fontSize: 14, border: "1px solid #E5E7EB", color: "#212121" }}
          >
            Discard
          </Button>
          <Button
            type="primary"
            htmlType="submit"
            loading={createStall.isPending}
            style={{ flex: 1.5, height: 48, borderRadius: 24, fontWeight: 700, fontSize: 14, background: "#F97316", border: "none" }}
          >
            Create Stall
          </Button>
        </div>
      </Form>
    </Drawer>
  );
}

// ─── Main screen ─────────────────────────────────────────────────────────────

export function StallsScreen() {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const [addOpen, setAddOpen] = useState(false);
  const [editOpen, setEditOpen] = useState(false);
  const [editing, setEditing] = useState<Stall | null>(null);
  const [editForm] = Form.useForm<Partial<Stall>>();

  const { data, isLoading } = useAdminStalls();
  const updateStall = useUpdateStall();

  const openEdit = (s: Stall) => {
    setEditing(s);
    editForm.setFieldsValue({
      name: s.name,
      description: s.description,
      sort_order: s.sort_order,
      cover_image: s.cover_image,
      is_open: s.is_open,
    });
    setEditOpen(true);
  };

  const onSave = async (values: Partial<Stall>) => {
    if (!editing) return;
    try {
      await updateStall.mutateAsync({ id: editing.id, ...values });
      void message.success(t("stalls.updateSuccess", "Stall updated"));
      setEditOpen(false);
    } catch {
      void message.error(t("stalls.saveFailed", "Failed to save stall"));
    }
  };

  const toggleOpen = async (row: Stall, next: boolean) => {
    try {
      await updateStall.mutateAsync({ id: row.id, is_open: next });
      void message.success(next ? t("stalls.opened", "Stall opened") : t("stalls.closed", "Stall closed"));
    } catch {
      void message.error(t("stalls.saveFailed", "Failed to save stall"));
    }
  };

  const columns: ColumnsType<Stall> = [
    {
      title: t("stalls.colCover", "Cover"), dataIndex: "cover_image", key: "cover", width: 80,
      render: (v?: string | null) => v
        ? <img src={v} alt="" style={{ width: 56, height: 40, objectFit: "cover", borderRadius: 6 }} />
        : <span style={{ color: "#9CA3AF" }}>—</span>,
    },
    { title: t("stalls.colName", "Name"), dataIndex: "name", key: "name" },
    {
      title: t("stalls.colDescription", "Description"), dataIndex: "description", key: "description",
      render: (v?: string | null) => v ?? <span style={{ color: "#9CA3AF" }}>—</span>,
    },
    {
      title: t("stalls.colSortOrder", "Sort"), dataIndex: "sort_order", key: "sort_order", width: 70,
      render: (v: number) => <Tag>{v}</Tag>,
    },
    {
      title: t("stalls.colOpen", "Open"), dataIndex: "is_open", key: "is_open", width: 100,
      render: (v: boolean, row) => (
        <Switch checked={v} onChange={(checked) => void toggleOpen(row, checked)} size="small" />
      ),
    },
    {
      title: "", key: "actions", width: 60, fixed: "right",
      render: (_, row) => (
        <Tooltip title={t("stalls.tooltipEdit", "Edit stall")}>
          <Button size="small" icon={<EditOutlined />} onClick={() => openEdit(row)} />
        </Tooltip>
      ),
    },
  ];

  return (
    <AdminShell>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <Title level={4} style={{ margin: 0 }}>{t("stalls.title", "Stalls")}</Title>
        <Space>
          <Button
            type="primary"
            icon={<PlusOutlined />}
            onClick={() => setAddOpen(true)}
            style={{ background: "#F97316", border: "none", borderRadius: 8, fontWeight: 700 }}
          >
            Add Stall
          </Button>
        </Space>
      </div>

      <DataTable<Stall> columns={columns} dataSource={data?.data ?? []} loading={isLoading} />

      {/* Add Stall Drawer */}
      <AddStallModal open={addOpen} onClose={() => setAddOpen(false)} />

      {/* Edit Stall Modal */}
      <Modal
        open={editOpen}
        title={`${t("stalls.editTitle", "Edit stall")} — ${editing?.name ?? ""}`}
        onCancel={() => setEditOpen(false)}
        onOk={() => void editForm.submit()}
        okButtonProps={{ style: { background: "#F97316", borderColor: "#F97316" }, loading: updateStall.isPending }}
      >
        <Form form={editForm} layout="vertical" onFinish={onSave}>
          <Form.Item name="name" label={t("stalls.formName", "Name")} rules={[{ required: true, max: 120 }]}>
            <Input maxLength={120} />
          </Form.Item>
          <Form.Item name="description" label={t("stalls.formDescription", "Description")}>
            <Input.TextArea maxLength={400} rows={3} showCount />
          </Form.Item>
          <Form.Item name="cover_image" label={t("stalls.formCoverImage", "Cover image URL")}>
            <Input placeholder="https://..." maxLength={500} />
          </Form.Item>
          <Form.Item name="sort_order" label={t("stalls.formSortOrder", "Sort order")}>
            <InputNumber min={0} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="is_open" label={t("stalls.formIsOpen", "Open for orders")} valuePropName="checked">
            <Switch />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
