import { useState, useMemo } from "react";
import {
  Input, Select, Button, Modal, Form, Dropdown, App, Typography, Divider, DatePicker,
} from "antd";
import type { MenuProps } from "antd";
import {
  SearchOutlined, MoreOutlined, DownloadOutlined,
  DollarOutlined, FileTextOutlined, PieChartOutlined, ClockCircleOutlined,
  RiseOutlined, WarningOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import type { RangePickerProps } from "antd/es/date-picker";
import dayjs from "dayjs";
import { useNavigate } from "react-router-dom";
import { DataTable } from "../components/DataTable";
import { AdminShell } from "../layouts/AdminShell";
import {
  useAdminRefunds, useReviewRefund, useRefundStats,
  type AdminRefundItem,
} from "../api/hooks";

const { Text } = Typography;
const { RangePicker } = DatePicker;

// ─── Constants ───────────────────────────────────────────────────────────────

const PAYMENT_LABELS: Record<string, string> = {
  visa: "Visa / Card", fpx: "FPX", grabpay: "GrabPay",
  cash: "Cash", ewallet: "E-wallet", tng: "Touch 'n Go", boost: "Boost",
};

const STATUS_MAP: Record<string, { bg: string; color: string; label: string }> = {
  success:  { bg: "#D1FAE5", color: "#065F46", label: "SUCCESS" },
  pending:  { bg: "#FEF3C7", color: "#92400E", label: "PENDING" },
  rejected: { bg: "#FEE2E2", color: "#991B1B", label: "REJECTED" },
  failed:   { bg: "#F3F4F6", color: "#6B7280", label: "FAILED" },
};

const TYPE_MAP: Record<string, { bg: string; color: string; label: string }> = {
  full:    { bg: "#FFF7ED", color: "#C2410C", label: "FULL REF" },
  partial: { bg: "#FFFBEB", color: "#D97706", label: "PARTIAL REF" },
};

// ─── Helpers ─────────────────────────────────────────────────────────────────

function refundDisplayId(id: string) {
  return `RFD-${id.slice(-3).toUpperCase().padStart(3, "0")}`;
}

function txnDisplayId(ref: string | null, id: string) {
  if (ref) return ref.toUpperCase();
  return `TXN-${id.slice(0, 12).toUpperCase()}`;
}

function StatusPill({ status }: { status: string }) {
  const s = STATUS_MAP[status] ?? { bg: "#F3F4F6", color: "#6B7280", label: status.toUpperCase() };
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 5,
      background: s.bg, color: s.color, borderRadius: 20,
      padding: "3px 10px", fontSize: 11, fontWeight: 700, letterSpacing: 0.3,
    }}>
      <span style={{ width: 6, height: 6, borderRadius: "50%", background: s.color, display: "inline-block" }} />
      {s.label}
    </span>
  );
}

function TypeBadge({ type }: { type: string }) {
  const t = TYPE_MAP[type] ?? { bg: "#F3F4F6", color: "#6B7280", label: type.toUpperCase() };
  return (
    <span style={{
      background: t.bg, color: t.color, borderRadius: 4,
      padding: "2px 8px", fontSize: 10, fontWeight: 800, letterSpacing: 0.5,
    }}>
      {t.label}
    </span>
  );
}

// ─── Update Status Modal ─────────────────────────────────────────────────────

function UpdateStatusModal({
  refund,
  onClose,
}: {
  refund: AdminRefundItem;
  onClose: () => void;
}) {
  const { message } = App.useApp();
  const [form] = Form.useForm();
  const reviewRefund = useReviewRefund();
  const [selectedStatus, setSelectedStatus] = useState<string>("completed");

  const onSubmit = async (vals: {
    status: string;
    transfer_method?: string;
    transfer_time?: string;
    reference_note?: string;
  }) => {
    const action = vals.status === "rejected" ? "reject" : "approve";
    try {
      await reviewRefund.mutateAsync({
        id: refund.id,
        action,
        note: vals.reference_note,
        transfer_method: vals.transfer_method,
        transfer_time: vals.transfer_time,
      });
      void message.success("Refund status updated");
      onClose();
    } catch {
      void message.error("Failed to update refund status");
    }
  };

  const rfdId = refundDisplayId(refund.id);
  const txnRef = txnDisplayId(refund.transaction?.reference ?? null, refund.transaction_id);
  const orderCode = refund.order?.order_code ?? "—";
  const customerName = refund.order?.customer?.name ?? "Guest";
  const currentStatus = STATUS_MAP[refund.status] ?? { bg: "#F3F4F6", color: "#6B7280", label: refund.status.toUpperCase() };
  const typeInfo = TYPE_MAP[refund.type] ?? { bg: "#F3F4F6", color: "#6B7280", label: refund.type.toUpperCase() };

  return (
    <Modal
      open
      onCancel={onClose}
      footer={null}
      width={720}
      centered
      destroyOnHidden
      title={
        <div>
          <div style={{ fontSize: 18, fontWeight: 800, color: "#1A1A1A" }}>Update Refund Status</div>
          <div style={{ fontSize: 13, color: "#F97316", fontWeight: 600, marginTop: 2 }}>
            Refund ID: {rfdId}
          </div>
        </div>
      }
      styles={{ body: { paddingTop: 20 } }}
    >
      {/* Summary row */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: 24 }}>
        {/* Refund summary */}
        <div style={{ background: "#F9FAFB", borderRadius: 12, padding: "16px 20px", border: "1px solid #E5E7EB" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}>
            <div style={{ background: "#FFF7ED", borderRadius: 8, padding: 6 }}>
              <WarningOutlined style={{ color: "#F97316", fontSize: 14 }} />
            </div>
            <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.8, color: "#616161", textTransform: "uppercase" }}>
              Refund Summary
            </span>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {[
              { label: "Customer", value: customerName },
              { label: "Order ID", value: `#${orderCode}` },
              { label: "Transaction ID", value: txnRef },
            ].map(({ label, value }) => (
              <div key={label} style={{ display: "flex", justifyContent: "space-between" }}>
                <span style={{ fontSize: 13, color: "#616161" }}>{label}</span>
                <span style={{ fontSize: 13, fontWeight: 700, color: "#212121" }}>{value}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Refund amount */}
        <div style={{ background: "#fff", borderRadius: 12, padding: "16px 20px", border: "1px solid #E5E7EB" }}>
          <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.8, color: "#616161", textTransform: "uppercase", marginBottom: 12 }}>
            Refund Amount
          </div>
          <div style={{ fontSize: 32, fontWeight: 900, color: "#212121", marginBottom: 10 }}>
            RM {Number(refund.amount).toFixed(2)}
          </div>
          <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
            <span style={{ background: typeInfo.bg, color: typeInfo.color, borderRadius: 4, padding: "2px 8px", fontSize: 10, fontWeight: 800 }}>
              {typeInfo.label}
            </span>
            <span style={{ fontSize: 12, color: "#616161" }}>Current Status:</span>
            <span style={{ background: currentStatus.bg, color: currentStatus.color, borderRadius: 20, padding: "2px 8px", fontSize: 11, fontWeight: 700 }}>
              {currentStatus.label}
            </span>
          </div>
        </div>
      </div>

      <Form form={form} layout="vertical" onFinish={vals => void onSubmit(vals as Parameters<typeof onSubmit>[0])}
        initialValues={{ status: "completed" }}>
        <Form.Item name="status" label={<span style={{ fontWeight: 700 }}>Update Status</span>}>
          <Select
            size="large"
            style={{ borderRadius: 8 }}
            onChange={(v) => setSelectedStatus(v as string)}
            options={[
              { value: "completed", label: "COMPLETED" },
              { value: "rejected",  label: "REJECTED" },
            ]}
          />
        </Form.Item>

        {selectedStatus === "completed" && (
          <div style={{ border: "1px solid #E5E7EB", borderRadius: 12, padding: "16px 20px", marginBottom: 16 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}>
              <div style={{ background: "#F0FDF4", borderRadius: 8, padding: 6 }}>
                <DollarOutlined style={{ color: "#16A34A", fontSize: 14 }} />
              </div>
              <span style={{ fontSize: 12, fontWeight: 800, letterSpacing: 0.6, color: "#16A34A", textTransform: "uppercase" }}>
                Transfer Details
              </span>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 12 }}>
              <Form.Item name="transfer_method" label="Transfer Method" style={{ marginBottom: 0 }}>
                <Select
                  options={[
                    { value: "E-wallet", label: "E-wallet" },
                    { value: "Bank Transfer", label: "Bank Transfer" },
                    { value: "Cash", label: "Cash" },
                    { value: "FPX", label: "FPX" },
                    { value: "Card", label: "Visa/Card" },
                  ]}
                  placeholder="Select method"
                />
              </Form.Item>
              <Form.Item name="transfer_time" label="Transfer Time" style={{ marginBottom: 0 }}>
                <Input placeholder="MM/DD/YYYY, HH:MM AM/PM" />
              </Form.Item>
            </div>
            <Form.Item name="reference_note" label="Reference Note" style={{ marginBottom: 0 }}>
              <Input.TextArea rows={2} placeholder="e.g. Maybank receipt #8812" />
            </Form.Item>
          </div>
        )}

        {selectedStatus === "rejected" && (
          <Form.Item name="reference_note" label="Rejection Reason">
            <Input.TextArea rows={3} placeholder="Reason for rejection..." />
          </Form.Item>
        )}

        {/* Warning */}
        <div style={{
          background: "#FEF2F2", border: "1px solid #FECACA", borderRadius: 8,
          padding: "12px 16px", display: "flex", gap: 10, alignItems: "flex-start", marginBottom: 20,
        }}>
          <WarningOutlined style={{ color: "#DC2626", marginTop: 1 }} />
          <span style={{ fontSize: 13, color: "#DC2626" }}>
            Please confirm that the refund has been successfully transferred. This action cannot be undone.
          </span>
        </div>

        <div style={{ display: "flex", justifyContent: "flex-end", gap: 12 }}>
          <Button size="large" onClick={onClose} style={{ borderRadius: 8, minWidth: 100, fontWeight: 700 }}>
            CANCEL
          </Button>
          <Button
            size="large"
            type="primary"
            htmlType="submit"
            loading={reviewRefund.isPending}
            style={{ borderRadius: 8, minWidth: 160, background: "#F97316", borderColor: "#F97316", fontWeight: 800 }}
          >
            CONFIRM UPDATE
          </Button>
        </div>
      </Form>
    </Modal>
  );
}

// ─── Main screen ─────────────────────────────────────────────────────────────

export function RefundsScreen() {
  const navigate = useNavigate();
  const [page, setPage] = useState(1);
  const [status, setStatus] = useState<string | undefined>();
  const [type, setType] = useState<string | undefined>();
  const [method, setMethod] = useState<string | undefined>();
  const [search, setSearch] = useState("");
  const [dateRange, setDateRange] = useState<[string, string] | null>(null);
  const [updateTarget, setUpdateTarget] = useState<AdminRefundItem | null>(null);

  const filterParams = useMemo(() => ({
    page, limit: 20,
    status: status || undefined,
    type: type || undefined,
    method: method || undefined,
    q: search || undefined,
    from: dateRange?.[0] || undefined,
    to: dateRange?.[1] || undefined,
  }), [page, status, type, method, search, dateRange]);

  const { data, isLoading } = useAdminRefunds(filterParams);
  const { data: stats } = useRefundStats();

  const refunds = (data?.data ?? []) as AdminRefundItem[];
  const totalCount = data?.meta.total ?? 0;

  const TH = (label: string) => (
    <span style={{ fontSize: 10, fontWeight: 800, color: "#9E9E9E", textTransform: "uppercase", letterSpacing: 0.5 }}>{label}</span>
  );

  const columns: ColumnsType<AdminRefundItem> = [
    {
      title: TH("Refund ID"),
      key: "rfd_id", width: 130,
      render: (_, row) => (
        <div>
          <div style={{ fontSize: 13, fontWeight: 800, color: "#212121" }}>{refundDisplayId(row.id)}</div>
          <div style={{ fontSize: 11, color: "#9E9E9E" }}>
            {dayjs(row.created_at).format("MMM DD, YYYY")}<br />
            {dayjs(row.created_at).format("h:mm A")}
          </div>
        </div>
      ),
    },
    {
      title: TH("Transaction ID"),
      key: "txn_id", width: 160,
      render: (_, row) => (
        <div
          style={{ cursor: "pointer" }}
          onClick={() => navigate(`/transactions/${row.transaction_id}`)}
        >
          <div style={{ fontSize: 12, fontWeight: 700, color: "#F97316", fontFamily: "monospace" }}>
            {txnDisplayId(row.transaction?.reference ?? null, row.transaction_id)}
          </div>
          <div style={{ fontSize: 11, color: "#9E9E9E" }}>
            #{row.order?.order_code ?? "—"}
          </div>
        </div>
      ),
    },
    {
      title: TH("Customer / Order"),
      key: "customer", width: 160,
      render: (_, row) => (
        <div>
          <div style={{ fontSize: 13, fontWeight: 600, color: "#212121" }}>
            {row.order?.customer?.name ?? "Guest"}
          </div>
          <div style={{ fontSize: 11, color: "#9E9E9E" }}>
            #{row.order?.order_code ?? "—"}
          </div>
        </div>
      ),
    },
    {
      title: TH("Amount"),
      key: "amount", width: 110,
      render: (_, row) => (
        <div>
          <div style={{ fontSize: 15, fontWeight: 800, color: "#212121" }}>
            RM {Number(row.amount).toFixed(2)}
          </div>
          <div style={{ fontSize: 10, color: "#9E9E9E", marginTop: 2 }}>
            {PAYMENT_LABELS[row.method] ?? row.method}
          </div>
        </div>
      ),
    },
    {
      title: TH("Type"),
      key: "type", width: 100,
      render: (_, row) => <TypeBadge type={row.type} />,
    },
    {
      title: TH("Reason"),
      dataIndex: "reason", key: "reason", width: 140,
      render: (v: string) => <Text style={{ fontSize: 12, color: "#616161" }}>{v}</Text>,
    },
    {
      title: TH("Status"),
      key: "status", width: 130,
      render: (_, row) => <StatusPill status={row.status} />,
    },
    {
      title: TH("Action"),
      key: "actions", width: 56, fixed: "right",
      render: (_, row) => {
        const items: MenuProps["items"] = [
          {
            key: "update",
            label: <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: 0.5 }}>UPDATE STATUS</span>,
            disabled: row.status !== "pending",
            onClick: () => setUpdateTarget(row),
          },
          {
            key: "detail",
            label: <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: 0.5 }}>VIEW DETAILS</span>,
            onClick: () => navigate(`/refunds/${row.id}`),
          },
          {
            key: "order",
            label: <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: 0.5 }}>VIEW ORDERS</span>,
            onClick: () => navigate(`/orders/${row.order?.id ?? ""}`),
          },
        ];
        return (
          <Dropdown menu={{ items }} trigger={["click"]}>
            <Button type="text" icon={<MoreOutlined />} style={{ padding: "0 8px" }} />
          </Dropdown>
        );
      },
    },
  ];

  // ── Stat cards config ──
  const statCards = [
    {
      label: "TOTAL REFUND AMOUNT",
      value: stats ? `RM ${Number(stats.totalAmount).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",")}` : "—",
      sub: stats ? "+12.5% vs last month" : "",
      subColor: "#16A34A",
      icon: <DollarOutlined />,
      iconBg: "#FFF7ED", iconColor: "#F97316",
    },
    {
      label: "TOTAL REFUND COUNT",
      value: stats ? String(stats.totalCount) : "—",
      sub: "Accumulated this month",
      subColor: "#9E9E9E",
      icon: <FileTextOutlined />,
      iconBg: "#F3F4F6", iconColor: "#616161",
    },
    {
      label: "PARTIAL REFUND COUNT",
      value: stats ? String(stats.partialCount) : "—",
      sub: stats && stats.totalCount > 0
        ? `${Math.round(stats.partialCount / stats.totalCount * 100)}% of total volume`
        : "",
      subColor: "#9E9E9E",
      icon: <PieChartOutlined />,
      iconBg: "#F0FDF4", iconColor: "#16A34A",
    },
    {
      label: "TODAY REFUND AMOUNT",
      value: stats ? `RM ${Number(stats.todayAmount).toFixed(2)}` : "—",
      sub: "Updated just now",
      subColor: "#9E9E9E",
      icon: <ClockCircleOutlined />,
      iconBg: "#EFF6FF", iconColor: "#3B82F6",
    },
  ];

  return (
    <AdminShell>
      <div style={{ padding: "28px 32px", background: "#F9FAFB", minHeight: "100vh" }}>

        {/* Title */}
        <div style={{ fontSize: 26, fontWeight: 800, color: "#212121", marginBottom: 24 }}>Refund</div>

        {/* Stat cards */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 16, marginBottom: 28 }}>
          {statCards.map((card) => (
            <div
              key={card.label}
              style={{ background: "#fff", borderRadius: 12, border: "1px solid #E5E7EB", padding: "20px 24px" }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                <div style={{ fontSize: 10, fontWeight: 800, color: "#9E9E9E", letterSpacing: 0.8, textTransform: "uppercase", marginBottom: 12, flex: 1 }}>
                  {card.label}
                </div>
                <div style={{ background: card.iconBg, borderRadius: 8, padding: 8, color: card.iconColor, fontSize: 18 }}>
                  {card.icon}
                </div>
              </div>
              <div style={{ fontSize: 28, fontWeight: 900, color: "#212121", lineHeight: 1.1, marginBottom: 8 }}>
                {card.value}
              </div>
              {card.sub && (
                <div style={{ fontSize: 12, color: card.subColor, display: "flex", alignItems: "center", gap: 4 }}>
                  {card.subColor === "#16A34A" && <RiseOutlined />}
                  {card.sub}
                </div>
              )}
            </div>
          ))}
        </div>

        {/* Filter bar */}
        <div style={{ background: "#fff", borderRadius: 12, border: "1px solid #E5E7EB", padding: "16px 20px", marginBottom: 20 }}>
          <div style={{ display: "flex", gap: 20, flexWrap: "wrap", alignItems: "flex-end" }}>
            <div>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#616161", marginBottom: 6 }}>DATE RANGE</div>
              <RangePicker
                style={{ height: 40 }}
                onChange={(_, s) => {
                  const [from, to] = s as [string, string];
                  setDateRange(from && to ? [
                    dayjs(from).startOf("day").toISOString(),
                    dayjs(to).endOf("day").toISOString(),
                  ] : null);
                  setPage(1);
                }}
              />
            </div>
            <div>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#616161", marginBottom: 6 }}>REFUND TYPE</div>
              <Select
                value={type}
                onChange={(v) => { setType(v as string | undefined); setPage(1); }}
                allowClear
                style={{ width: 140, height: 40 }}
                placeholder="All Types"
                options={[
                  { value: "full", label: "Full Refund" },
                  { value: "partial", label: "Partial Refund" },
                ]}
              />
            </div>
            <div>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#616161", marginBottom: 6 }}>PAYMENT METHOD</div>
              <Select
                value={method}
                onChange={(v) => { setMethod(v as string | undefined); setPage(1); }}
                allowClear
                style={{ width: 160, height: 40 }}
                placeholder="All Methods"
                options={Object.entries(PAYMENT_LABELS).map(([v, l]) => ({ value: v, label: l }))}
              />
            </div>
            <div>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#616161", marginBottom: 6 }}>STATUS</div>
              <Select
                value={status}
                onChange={(v) => { setStatus(v as string | undefined); setPage(1); }}
                allowClear
                style={{ width: 140, height: 40 }}
                placeholder="All Status"
                options={[
                  { value: "pending", label: "Pending" },
                  { value: "success", label: "Success" },
                  { value: "rejected", label: "Rejected" },
                  { value: "failed", label: "Failed" },
                ]}
              />
            </div>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#616161", marginBottom: 6 }}>QUICK SEARCH</div>
              <Input
                prefix={<SearchOutlined style={{ color: "#9E9E9E" }} />}
                placeholder="TXN ID / Name"
                value={search}
                onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                style={{ height: 40, borderRadius: 8 }}
                allowClear
              />
            </div>
          </div>
        </div>

        {/* Table */}
        <div style={{ background: "#fff", borderRadius: 12, border: "1px solid #E5E7EB", overflow: "hidden" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "16px 20px", borderBottom: "1px solid #F3F4F6" }}>
            <div style={{ fontSize: 16, fontWeight: 700, color: "#212121" }}>Recent Refund Records</div>
            <Button icon={<DownloadOutlined />} style={{ borderRadius: 8, color: "#16A34A", borderColor: "#BBF7D0" }}>
              Export CSV
            </Button>
          </div>
          <DataTable<AdminRefundItem>
            columns={columns}
            dataSource={refunds}
            loading={isLoading}
            pagination={{ current: page, total: totalCount, pageSize: 20, onChange: (p) => setPage(p) }}
          />
        </div>

      </div>

      {updateTarget && (
        <UpdateStatusModal
          refund={updateTarget}
          onClose={() => setUpdateTarget(null)}
        />
      )}
    </AdminShell>
  );
}

