import { Table } from "antd";
import type { TableProps } from "antd";

/**
 * DataTable — thin wrapper around Ant Design Table with KawKaw defaults:
 * - Sticky header
 * - Row hover amber tint (via theme token)
 * - Size = "middle"
 * - Pagination: 20 per page, show total
 */
export function DataTable<T extends object>(props: TableProps<T>) {
  return (
    <Table<T>
      size="middle"
      scroll={{ x: "max-content" }}
      sticky={{ offsetHeader: 64 }}
      pagination={
        props.pagination === false
          ? false
          : {
              defaultPageSize: 20,
              showSizeChanger: true,
              pageSizeOptions: ["10", "20", "50", "100"],
              showTotal: (total, range) => `${range[0]}–${range[1]} of ${total}`,
              ...((props.pagination as object) ?? {}),
            }
      }
      rowKey="id"
      {...props}
    />
  );
}
