import { useState, useEffect } from "react";
import {
  Card, Row, Col, Form, TimePicker, Switch, Button,
  Typography, Divider, DatePicker, Input, Table, Popconfirm, message, Space,
} from "antd";
import { PlusOutlined, DeleteOutlined, EditOutlined, CheckOutlined, CloseOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import dayjs from "dayjs";
import { AdminShell } from "../layouts/AdminShell";
import {
  useKopitiamHours, useUpdateHours,
  useHolidays, useAddHoliday, useUpdateHoliday, useDeleteHoliday,
} from "../api/hooks";

const { Title, Text } = Typography;

interface HourRow { dayOfWeek: number; openTime: string; closeTime: string; isClosed: boolean }
interface HolidayRow { id: string; date: string; note: string | null }

export function HoursScreen() {
  const { t } = useTranslation();
  const { data: hoursData, isLoading: hoursLoading } = useKopitiamHours();
  const { data: holidaysData, isLoading: holidaysLoading } = useHolidays();
  const updateHours = useUpdateHours();
  const addHoliday = useAddHoliday();
  const updateHoliday = useUpdateHoliday();
  const deleteHoliday = useDeleteHoliday();

  const [rows, setRows] = useState<HourRow[]>([]);
  const [addForm] = Form.useForm<{ date: dayjs.Dayjs; note?: string }>();
  const [editingHoliday, setEditingHoliday] = useState<{ id: string; date: dayjs.Dayjs; note: string } | null>(null);

  const DAY_NAMES = [
    t("hours.days.sunday"),
    t("hours.days.monday"),
    t("hours.days.tuesday"),
    t("hours.days.wednesday"),
    t("hours.days.thursday"),
    t("hours.days.friday"),
    t("hours.days.saturday"),
  ];

  useEffect(() => {
    if (hoursData?.data) {
      setRows(hoursData.data.map((d) => ({ ...d })));
    }
  }, [hoursData]);

  const updateRow = (dayOfWeek: number, changes: Partial<HourRow>) => {
    setRows((prev) => prev.map((r) => r.dayOfWeek === dayOfWeek ? { ...r, ...changes } : r));
  };

  const saveHours = async () => {
    try {
      await updateHours.mutateAsync(rows);
      void message.success(t("hours.saveSuccess"));
    } catch {
      void message.error(t("hours.saveFailed"));
    }
  };

  const onAddHoliday = async (values: { date: dayjs.Dayjs; note?: string }) => {
    try {
      await addHoliday.mutateAsync({ date: values.date.format("YYYY-MM-DD"), note: values.note });
      void message.success(t("hours.holidayAdded"));
      addForm.resetFields();
    } catch {
      void message.error(t("hours.holidayAddFailed"));
    }
  };

  return (
    <AdminShell>
      <Title level={4} style={{ marginBottom: 20 }}>{t("hours.title")}</Title>

      <Row gutter={[16, 16]}>
        {/* Operating Hours */}
        <Col xs={24} lg={14}>
          <Card
            title={t("hours.cardOperatingHours")}
            loading={hoursLoading}
            style={{ borderRadius: 12 }}
            extra={
              <Button type="primary" size="small" onClick={saveHours} loading={updateHours.isPending}
                style={{ background: "#D97706", borderColor: "#D97706" }}>
                {t("hours.saveHours")}
              </Button>
            }
          >
            {rows.map((row) => (
              <div key={row.dayOfWeek} style={{
                display: "flex", alignItems: "center", gap: 12,
                padding: "8px 0", borderBottom: "1px solid #F3F4F6",
              }}>
                <Text style={{ width: 96, fontWeight: 500 }}>{DAY_NAMES[row.dayOfWeek]}</Text>
                <Switch
                  checked={!row.isClosed}
                  onChange={(v) => updateRow(row.dayOfWeek, { isClosed: !v })}
                  checkedChildren={t("hours.open")}
                  unCheckedChildren={t("hours.closed")}
                  size="small"
                />
                {!row.isClosed && (
                  <>
                    <TimePicker
                      value={dayjs(row.openTime, "HH:mm")}
                      format="HH:mm"
                      minuteStep={30}
                      size="small"
                      onChange={(t_) => t_ && updateRow(row.dayOfWeek, { openTime: t_.format("HH:mm") })}
                    />
                    <Text type="secondary">–</Text>
                    <TimePicker
                      value={dayjs(row.closeTime, "HH:mm")}
                      format="HH:mm"
                      minuteStep={30}
                      size="small"
                      onChange={(t_) => t_ && updateRow(row.dayOfWeek, { closeTime: t_.format("HH:mm") })}
                    />
                  </>
                )}
              </div>
            ))}
          </Card>
        </Col>

        {/* Holidays */}
        <Col xs={24} lg={10}>
          <Card title={t("hours.cardHolidays")} style={{ borderRadius: 12 }} loading={holidaysLoading}>
            <Form form={addForm} layout="inline" onFinish={onAddHoliday} style={{ marginBottom: 16 }}>
              <Form.Item name="date" rules={[{ required: true, message: t("hours.dateRequired") }]}>
                <DatePicker placeholder={t("hours.datePickerPlaceholder")} size="small" style={{ width: 130 }} />
              </Form.Item>
              <Form.Item name="note">
                <Input placeholder={t("hours.notePlaceholder")} size="small" style={{ width: 140 }} />
              </Form.Item>
              <Form.Item>
                <Button type="primary" htmlType="submit" size="small" icon={<PlusOutlined />}
                  loading={addHoliday.isPending}
                  style={{ background: "#D97706", borderColor: "#D97706" }}>
                  {t("hours.addHolidayBtn")}
                </Button>
              </Form.Item>
            </Form>

            <Divider style={{ margin: "8px 0 12px" }} />

            <Table<HolidayRow>
              size="small"
              dataSource={(holidaysData?.data ?? []) as HolidayRow[]}
              rowKey="id"
              pagination={false}
              columns={[
                {
                  title: t("hours.colDate"), dataIndex: "date", key: "date",
                  render: (v: string, row) => editingHoliday?.id === row.id
                    ? <DatePicker size="small" value={editingHoliday.date} onChange={(d) => d && setEditingHoliday({ ...editingHoliday, date: d })} />
                    : <Text strong>{dayjs(v).format("D MMM YYYY (ddd)")}</Text>,
                },
                {
                  title: t("hours.colNote"), dataIndex: "note", key: "note",
                  render: (v: string | null, row) => editingHoliday?.id === row.id
                    ? <Input size="small" value={editingHoliday.note} onChange={(e) => setEditingHoliday({ ...editingHoliday, note: e.target.value })} />
                    : (v ?? <Text type="secondary">—</Text>),
                },
                {
                  title: "", key: "actions", width: 96,
                  render: (_, row) => editingHoliday?.id === row.id ? (
                    <Space size={2}>
                      <Button
                        size="small" type="text" icon={<CheckOutlined />}
                        loading={updateHoliday.isPending}
                        onClick={async () => {
                          try {
                            await updateHoliday.mutateAsync({
                              id: row.id,
                              date: editingHoliday.date.format("YYYY-MM-DD"),
                              note: editingHoliday.note,
                            });
                            void message.success(t("hours.updateHolidaySuccess", "Holiday updated"));
                            setEditingHoliday(null);
                          } catch {
                            void message.error(t("hours.updateHolidayFailed", "Failed to update holiday"));
                          }
                        }}
                      />
                      <Button size="small" type="text" icon={<CloseOutlined />} onClick={() => setEditingHoliday(null)} />
                    </Space>
                  ) : (
                    <Space size={2}>
                      <Button
                        size="small" type="text" icon={<EditOutlined />}
                        onClick={() => setEditingHoliday({ id: row.id, date: dayjs(row.date), note: row.note ?? "" })}
                      />
                      <Popconfirm title={t("hours.confirmRemoveHoliday")} onConfirm={() => void deleteHoliday.mutateAsync(row.id)}>
                        <Button size="small" danger icon={<DeleteOutlined />} type="text" />
                      </Popconfirm>
                    </Space>
                  ),
                },
              ]}
            />
          </Card>
        </Col>
      </Row>
    </AdminShell>
  );
}
