const PAYMENT_LABELS: Record<string, string> = {
  visa: "Visa / Card", fpx: "FPX (Online Banking)", grabpay: "GrabPay",
  cash: "Cash", ewallet: "eWallet", tng: "Touch 'n Go", boost: "Boost",
};

const REFUND_METHODS = [
  { value: "cash", label: "Cash" }, { value: "fpx", label: "FPX" },
  { value: "visa", label: "Visa/Card" }, { value: "grabpay", label: "GrabPay" },
  { value: "tng", label: "Touch 'n Go" }, { value: "boost", label: "Boost" },
  { value: "ewallet", label: "eWallet" },
];

const STATUS_MAP: Record<string, { bg: string; color: string; label: string }> = {
  success:        { bg: "#14532D", color: "#fff",     label: "PAID" },
  partial_refund: { bg: "#F97316", color: "#fff",     label: "PARTIAL REFUND" },
  refunded:       { bg: "#FEE2E2", color: "#DC2626",  label: "REFUNDED" },
  pending:        { bg: "#FEF9C3", color: "#854D0E",  label: "PENDING" },
  failed:         { bg: "#F3F4F6", color: "#6B7280",  label: "FAILED" },
};

const REFUND_STATUS_MAP: Record<string, { bg: string; color: string }> = {
  completed: { bg: "#F0FDF4", color: "#166534" },
  approved:  { bg: "#F0FDF4", color: "#166534" },
  pending:   { bg: "#FEF9C3", color: "#854D0E" },
  rejected:  { bg: "#FEE2E2", color: "#DC2626" },
};

function txnDisplayCode(id: string, ref: string | null) {
  if (ref) return ref.toUpperCase();
  return `TXN-${id.slice(0, 12).toUpperCase()}`;
}

function buildTimeline(txn: NonNullable<ReturnType<typeof useAdminTransaction>["data"]>) {
  type TimelineEvent = { id: string; ts: string; title: string; desc: string; dot: "green" | "orange" | "red" | "grey" };
  const events: TimelineEvent[] = [];

  // From activity logs
  const ACTION_LABELS: Record<string, string> = {
    "refund.create":  "Refund Initiated",
    "refund.approve": "Refund Approved",
    "refund.reject":  "Refund Rejected",
    "order.admin_cancel": "Order Cancelled by Admin",
  };
  for (const log of txn.activity_logs ?? []) {
    const title = ACTION_LABELS[log.action] ?? log.action.replace(/\./g, " ").replace(/\b\w/g, c => c.toUpperCase());
    const metaDesc = log.meta
      ? Object.entries(log.meta)
          .filter(([k]) => !["orderId", "prevStatus"].includes(k))
          .map(([k, v]) => `${k}: ${String(v)}`)
          .join(", ")
      : "";
    events.push({ id: log.id, ts: log.created_at, title, desc: metaDesc, dot: "grey" });
  }

  // Synthetic: payment completed
  if (txn.paid_at) {
    events.push({
      id: "paid",
      ts: txn.paid_at,
      title: "Payment Completed (Success)",
      desc: txn.reference ? `Auth Code: ${txn.reference}` : "",
      dot: "green",
    });
  }

  // Synthetic: payment initiated
  events.push({
    id: "initiated",
    ts: txn.created_at,
    title: "Payment Initiated",
    desc: txn.order?.customer?.name ? `${txn.order.customer.name} checkout` : "",
    dot: "grey",
  });

  // Sort newest first, deduplicate by ts proximity to activity logs
  events.sort((a, b) => dayjs(b.ts).valueOf() - dayjs(a.ts).valueOf());
  return events;
}

