import { useState } from "react";
import {
  Button, Checkbox, Input, InputNumber, Select, Spin, App, Divider, Typography,
} from "antd";
import {
  ArrowLeftOutlined,
  SafetyCertificateOutlined,
  WarningFilled,
  InfoCircleOutlined,
  AlignLeftOutlined,
  CreditCardOutlined,
} from "@ant-design/icons";
import { useNavigate, useParams } from "react-router-dom";
import dayjs from "dayjs";
import { AdminShell } from "../layouts/AdminShell";
import { useAdminTransaction, useInitiateRefund } from "../api/hooks";

const { Text } = Typography;

const PAYMENT_LABELS: Record<string, string> = {
  visa: "Visa / Card – Verified Source",
  fpx: "FPX – Verified Source",
  grabpay: "GrabPay – Verified Source",
  cash: "Cash",
  ewallet: "eWallet – Verified Source",
  tng: "Touch 'n Go – Verified Source",
  boost: "Boost – Verified Source",
};

const PAYMENT_DESC: Record<string, string> = {
  visa: "Funds will be returned to the original card. Processing time: 5–7 business days.",
  fpx: "Funds will be returned to the original payment instrument. Processing time: 3–5 business days.",
  grabpay: "Funds will be returned to the GrabPay wallet. Processing time: 1–3 business days.",
  cash: "Cash refund to be handed to customer directly.",
  ewallet: "Funds will be returned to the original eWallet. Processing time: 1–3 business days.",
  tng: "Funds will be returned to the Touch 'n Go wallet. Processing time: 1–3 business days.",
  boost: "Funds will be returned to the Boost wallet. Processing time: 1–3 business days.",
};

const REFUND_REASONS = [
  { value: "Customer Cancelled", label: "Customer Cancelled" },
  { value: "Out of stock", label: "Out of Stock" },
  { value: "Wrong item", label: "Wrong Item" },
  { value: "Duplicate payment", label: "Duplicate Payment" },
  { value: "Order not delivered", label: "Order Not Delivered" },
  { value: "Quality issue", label: "Quality Issue" },
  { value: "Other", label: "Other" },
];

export function IssueRefundScreen() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { message } = App.useApp();

  const { data: txn, isLoading } = useAdminTransaction(id);
  const initiateRefund = useInitiateRefund();

  const [refundType, setRefundType] = useState<"full" | "partial">("full");
  const [partialAmount, setPartialAmount] = useState<number | null>(null);
  const [reason, setReason] = useState<string | null>(null);
  const [internalNote, setInternalNote] = useState("");
  const [confirmed, setConfirmed] = useState(false);

  const txnTotal = txn ? Number(txn.amount) : 0;
  const refundAmount = refundType === "full" ? txnTotal : (partialAmount ?? 0);

  const canSubmit = !!reason && confirmed && refundAmount > 0 && !!txn?.order?.id;

  const onSubmit = async () => {
    if (!txn?.order?.id || !reason) return;
    try {
      await initiateRefund.mutateAsync({
        orderId: txn.order.id,
        amount: refundAmount.toFixed(2),
        type: refundType,
        reason,
        method: txn.method,
      });
      void message.success("Refund initiated successfully");
      navigate(`/transactions/${id ?? ""}`);
    } catch {
      void message.error("Failed to initiate refund. Please try again.");
    }
  };

  if (isLoading) {
    return (
      <AdminShell>
        <div style={{ display: "flex", justifyContent: "center", alignItems: "center", minHeight: 300 }}>
          <Spin size="large" />
        </div>
      </AdminShell>
    );
  }

  if (!txn) {
    return (
      <AdminShell>
        <div style={{ padding: 40, textAlign: "center", color: "#9CA3AF" }}>Transaction not found.</div>
      </AdminShell>
    );
  }

  const order = txn.order;
  const txnDisplayCode = txn.reference?.toUpperCase() ?? `TXN-${txn.id.slice(0, 12).toUpperCase()}`;

  return (
    <AdminShell>
      <div style={{ background: "#F9FAFB", minHeight: "100vh", padding: "28px 32px" }}>

        {/* ── Page title / meta ── */}
        <div style={{ marginBottom: 28 }}>
          <div style={{ fontSize: 30, fontWeight: 800, color: "#212121", marginBottom: 8 }}>Process Refund</div>
          <div style={{ display: "flex", alignItems: "center", gap: 20, fontSize: 13, color: "#616161", flexWrap: "wrap" }}>
            <span>TXN ID: <Text copyable style={{ fontFamily: "monospace", fontWeight: 600, color: "#212121" }}>{txnDisplayCode}</Text></span>
            {order && (
              <span>
                Order ID:{" "}
                <span
                  style={{ color: "#F97316", fontWeight: 700, cursor: "pointer" }}
                  onClick={() => navigate(`/orders/${order.id}`)}
                >
                  #{order.order_code}
                </span>
              </span>
            )}
            <span>Date Paid: {dayjs(txn.paid_at ?? txn.created_at).format("MMM D, YYYY [at] h:mm A")}</span>
            <button
              onClick={() => navigate(-1)}
              style={{ background: "none", border: "none", cursor: "pointer", color: "#9E9E9E", display: "flex", alignItems: "center", gap: 4, padding: 0, fontSize: 13 }}
            >
              <ArrowLeftOutlined /> Back
            </button>
          </div>
        </div>

        {/* ── Two-column layout ── */}
        <div style={{ display: "flex", gap: 24, alignItems: "flex-start" }}>

          {/* ── Left column ── */}
          <div style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column", gap: 20 }}>

            {/* REFUND TYPE */}
            <div style={{ background: "#fff", borderRadius: 16, padding: "24px 28px", border: "1px solid #E5E7EB" }}>
              <SectionHeader icon="↺" label="REFUND TYPE" />
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginTop: 16 }}>

                {/* Full Refund card */}
                <div
                  onClick={() => setRefundType("full")}
                  style={{
                    borderRadius: 12, border: `2px solid ${refundType === "full" ? "#F97316" : "#E5E7EB"}`,
                    padding: "18px 20px", cursor: "pointer", transition: "border-color 0.15s",
                    background: refundType === "full" ? "#FFFBF5" : "#fff", position: "relative",
                  }}
                >
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                    <div style={{ fontSize: 15, fontWeight: 700, color: "#212121", marginBottom: 8 }}>Full Refund</div>
                    <RadioDot selected={refundType === "full"} />
                  </div>
                  <div style={{ fontSize: 13, color: "#616161", lineHeight: 1.5 }}>
                    Refund the total transaction amount of{" "}
                    <strong>RM {txnTotal.toFixed(2)}</strong> to the original source.
                  </div>
                </div>

                {/* Partial Refund card */}
                <div
                  onClick={() => setRefundType("partial")}
                  style={{
                    borderRadius: 12, border: `2px solid ${refundType === "partial" ? "#F97316" : "#E5E7EB"}`,
                    padding: "18px 20px", cursor: "pointer", transition: "border-color 0.15s",
                    background: refundType === "partial" ? "#FFFBF5" : "#fff",
                  }}
                >
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                    <div style={{ fontSize: 15, fontWeight: 700, color: "#212121", marginBottom: 8 }}>Partial Refund</div>
                    <RadioDot selected={refundType === "partial"} />
                  </div>
                  <div style={{ fontSize: 13, color: "#616161", lineHeight: 1.5, marginBottom: 12 }}>
                    Select items or specify a custom amount to return to the customer.
                  </div>
                  {refundType === "partial" && (
                    <>
                      <InputNumber
                        prefix="RM"
                        min={0.01}
                        max={txnTotal}
                        precision={2}
                        placeholder="0.00"
                        style={{ width: "100%", borderRadius: 8 }}
                        value={partialAmount}
                        onChange={v => setPartialAmount(v)}
                        onClick={e => e.stopPropagation()}
                      />
                      <div style={{ fontSize: 11, color: "#9E9E9E", marginTop: 6 }}>
                        Max refundable: RM {txnTotal.toFixed(2)}
                      </div>
                    </>
                  )}
                </div>
              </div>
            </div>

            {/* REFUND BREAKDOWN */}
            {order && (
              <div style={{ background: "#fff", borderRadius: 16, padding: "24px 28px", border: "1px solid #E5E7EB" }}>
                <SectionHeader icon="≡" label="REFUND BREAKDOWN" />
                <div style={{ display: "flex", flexDirection: "column", gap: 14, marginTop: 20 }}>
                  {refundType === "full" ? (
                    <>
                      <BreakdownRow label="Food & Beverages" amount={Number(order.subtotal)} />
                      {Number(order.delivery_fee) > 0 && <BreakdownRow label="Delivery Fee" amount={Number(order.delivery_fee)} />}
                      {Number(order.sst_amount) > 0 && <BreakdownRow label="SST (6%)" amount={Number(order.sst_amount)} />}
                      {order.voucher_code && Number(order.voucher_discount) > 0 && (
                        <div style={{ display: "flex", justifyContent: "space-between" }}>
                          <span style={{ fontSize: 14, color: "#16A34A" }}>Applied Discount</span>
                          <span style={{ fontSize: 14, fontWeight: 600, color: "#16A34A" }}>
                            −RM {Number(order.voucher_discount).toFixed(2)}
                          </span>
                        </div>
                      )}
                    </>
                  ) : (
                    <BreakdownRow label="Refund Amount" amount={partialAmount ?? 0} />
                  )}
                </div>
                <Divider style={{ margin: "20px 0" }} />
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <span style={{ fontSize: 15, fontWeight: 700, color: "#212121" }}>Total Refund Amount</span>
                  <span style={{ fontSize: 18, fontWeight: 800, color: "#212121" }}>
                    RM {refundAmount.toFixed(2)}
                  </span>
                </div>
              </div>
            )}

            {/* REASON & DOCUMENTATION */}
            <div style={{ background: "#fff", borderRadius: 16, padding: "24px 28px", border: "1px solid #E5E7EB" }}>
              <SectionHeader icon={<AlignLeftOutlined style={{ fontSize: 13 }} />} label="REASON & DOCUMENTATION" />
              <div style={{ marginTop: 20, display: "flex", flexDirection: "column", gap: 16 }}>
                <div>
                  <div style={{ fontSize: 11, fontWeight: 700, color: "#9E9E9E", letterSpacing: 0.8, marginBottom: 8 }}>
                    REFUND REASON
                  </div>
                  <Select
                    style={{ width: "100%" }}
                    placeholder="Select a reason..."
                    value={reason}
                    onChange={setReason}
                    options={REFUND_REASONS}
                  />
                </div>
                <div>
                  <div style={{ fontSize: 11, fontWeight: 700, color: "#9E9E9E", letterSpacing: 0.8, marginBottom: 8 }}>
                    INTERNAL NOTE <span style={{ fontWeight: 400, color: "#D1D5DB" }}>(OPTIONAL)</span>
                  </div>
                  <Input.TextArea
                    rows={4}
                    placeholder="Add specific details about the refund for merchant auditing..."
                    value={internalNote}
                    onChange={e => setInternalNote(e.target.value)}
                    style={{ borderRadius: 8, resize: "none" }}
                  />
                </div>
              </div>
            </div>

            {/* REFUND METHOD */}
            <div style={{ background: "#fff", borderRadius: 16, padding: "24px 28px", border: "1px solid #E5E7EB" }}>
              <SectionHeader icon={<CreditCardOutlined style={{ fontSize: 13 }} />} label="REFUND METHOD" />
              <div style={{ marginTop: 16 }}>
                <div style={{
                  display: "flex", alignItems: "center", gap: 14,
                  background: "#F9FAFB", borderRadius: 12, padding: "16px 20px",
                  border: "1px solid #E5E7EB",
                }}>
                  <div style={{
                    width: 44, height: 44, borderRadius: "50%", flexShrink: 0,
                    background: "#14532D", display: "flex", alignItems: "center", justifyContent: "center",
                  }}>
                    <SafetyCertificateOutlined style={{ color: "#fff", fontSize: 20 }} />
                  </div>
                  <div>
                    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                      <span style={{ fontSize: 14, fontWeight: 700, color: "#212121" }}>
                        {PAYMENT_LABELS[txn.method] ?? txn.method.toUpperCase()}
                      </span>
                      <div style={{ width: 8, height: 8, borderRadius: "50%", background: "#16A34A" }} />
                    </div>
                    <div style={{ fontSize: 12, color: "#616161", lineHeight: 1.5 }}>
                      {PAYMENT_DESC[txn.method] ?? "Funds will be returned to the original payment instrument."}
                    </div>
                  </div>
                </div>
              </div>
            </div>

          </div>

          {/* ── Right sidebar ── */}
          <div style={{ width: 280, flexShrink: 0, display: "flex", flexDirection: "column", gap: 16 }}>

            {/* Original paid amount */}
            <div style={{ background: "#fff", borderRadius: 16, padding: "20px", border: "1px solid #E5E7EB", textAlign: "right" }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#9E9E9E", letterSpacing: 0.8, marginBottom: 8, textTransform: "uppercase" }}>
                Original Paid Amount
              </div>
              <div style={{ fontSize: 26, fontWeight: 800, color: "#212121" }}>
                RM {txnTotal.toFixed(2)}
              </div>
            </div>

            {/* Settlement summary card */}
            <div style={{ background: "#1A1A1A", borderRadius: 16, padding: "24px", display: "flex", flexDirection: "column", gap: 16 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#9E9E9E", letterSpacing: 0.8, textTransform: "uppercase" }}>
                Settlement Summary
              </div>
              <div style={{ fontSize: 28, fontWeight: 800, color: "#fff" }}>
                RM {refundAmount > 0 ? refundAmount.toFixed(2) : "0.00"}
              </div>

              {/* Warning box */}
              <div style={{
                background: "#3B1A1A", border: "1px solid #7F1D1D", borderRadius: 10,
                padding: "12px 14px", display: "flex", alignItems: "flex-start", gap: 10,
              }}>
                <WarningFilled style={{ color: "#F87171", fontSize: 14, marginTop: 1, flexShrink: 0 }} />
                <div style={{ fontSize: 12, color: "#FCA5A5", lineHeight: 1.5 }}>
                  This action cannot be undone. Once processed, the refund will be initiated immediately through the gateway.
                </div>
              </div>

              {/* Confirm checkbox */}
              <div style={{ display: "flex", alignItems: "flex-start", gap: 10 }}>
                <Checkbox
                  checked={confirmed}
                  onChange={e => setConfirmed(e.target.checked)}
                  style={{ marginTop: 1 }}
                />
                <span style={{ fontSize: 12, color: "#D1D5DB", lineHeight: 1.6, cursor: "pointer" }} onClick={() => setConfirmed(v => !v)}>
                  I confirm that I have verified the order details and authorize this refund action.
                </span>
              </div>

              {/* Confirm button */}
              <Button
                block
                type="primary"
                loading={initiateRefund.isPending}
                disabled={!canSubmit}
                onClick={() => void onSubmit()}
                style={{
                  background: canSubmit ? "#DC2626" : "#6B7280",
                  borderColor: canSubmit ? "#DC2626" : "#6B7280",
                  borderRadius: 10, height: 48,
                  fontSize: 15, fontWeight: 700, letterSpacing: 0.3,
                }}
              >
                Confirm Refund
              </Button>

              {/* Cancel link */}
              <div style={{ textAlign: "center" }}>
                <button
                  onClick={() => navigate(-1)}
                  style={{ background: "none", border: "none", cursor: "pointer", fontSize: 13, color: "#9E9E9E", textDecoration: "underline" }}
                >
                  Cancel &amp; Return
                </button>
              </div>

              {/* Merchant info */}
              {order && (
                <div style={{ paddingTop: 8, borderTop: "1px solid #2D2D2D", fontSize: 11, color: "#4B5563", lineHeight: 1.8 }}>
                  <div>Merchant ID: KPI-{txn.id.slice(0, 7).toUpperCase()}</div>
                  <div>Authorized by: admin</div>
                </div>
              )}
            </div>

            {/* Partial refund tip */}
            {refundType === "partial" && (
              <div style={{
                background: "#EFF6FF", borderRadius: 12, padding: "14px 16px",
                border: "1px solid #BFDBFE", display: "flex", alignItems: "flex-start", gap: 10,
              }}>
                <InfoCircleOutlined style={{ color: "#2563EB", fontSize: 14, marginTop: 2, flexShrink: 0 }} />
                <div>
                  <div style={{ fontSize: 12, fontWeight: 700, color: "#1D4ED8", marginBottom: 4 }}>Partial Refund Tip</div>
                  <div style={{ fontSize: 12, color: "#3B82F6", lineHeight: 1.5 }}>
                    For missed items, calculate the per-unit price before SST to ensure accurate customer reimbursement.
                  </div>
                </div>
              </div>
            )}

          </div>
        </div>
      </div>
    </AdminShell>
  );
}

/* ── Helpers ── */

function RadioDot({ selected }: { selected: boolean }) {
  return (
    <div style={{
      width: 18, height: 18, borderRadius: "50%", flexShrink: 0, marginTop: 2,
      border: `2px solid ${selected ? "#F97316" : "#D1D5DB"}`,
      display: "flex", alignItems: "center", justifyContent: "center",
    }}>
      {selected && <div style={{ width: 8, height: 8, borderRadius: "50%", background: "#F97316" }} />}
    </div>
  );
}

function SectionHeader({ icon, label }: { icon: React.ReactNode; label: string }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
      <span style={{ fontSize: 14, color: "#9E9E9E" }}>{icon}</span>
      <span style={{ fontSize: 11, fontWeight: 700, color: "#616161", letterSpacing: 0.8, textTransform: "uppercase" as const }}>
        {label}
      </span>
    </div>
  );
}

function BreakdownRow({ label, amount }: { label: string; amount: number }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between" }}>
      <span style={{ fontSize: 14, color: "#616161" }}>{label}</span>
      <span style={{ fontSize: 14, color: "#212121", fontWeight: 500 }}>RM {amount.toFixed(2)}</span>
    </div>
  );
}
