import { useEffect } from "react";
import { Modal, Button, Divider } from "antd";
import {
  DownloadOutlined,
  PrinterOutlined,
  CloseOutlined,
  ShopOutlined,
  CarOutlined,
  ShoppingOutlined,
} from "@ant-design/icons";
import dayjs from "dayjs";
import type { TxnDetail } from "../api/hooks";

// ─── Types ──────────────────────────────────────────────────────────────────

export type ReceiptTxn = TxnDetail & {
  order: TxnDetail["order"] & {
    kopitiam: { name: string; address: string; phone: string };
    items: Array<{ id: string; name: string; qty: number; price: string; options: unknown }>;
  };
};

interface Props {
  open: boolean;
  onClose: () => void;
  txn: ReceiptTxn;
}

// ─── Constants ──────────────────────────────────────────────────────────────

const PAYMENT_LABELS: Record<string, string> = {
  visa: "Visa / Card",
  fpx: "FPX",
  grabpay: "GrabPay",
  cash: "Cash",
  ewallet: "eWallet",
  tng: "Touch 'n Go",
  boost: "Boost",
};

const TEAL = "#0E7490";
const RECEIPT_ID = "kawkaw-receipt-printable";

// ─── Helpers ────────────────────────────────────────────────────────────────

function parseOptions(raw: unknown): string {
  if (!raw) return "";
  try {
    const arr = typeof raw === "string" ? (JSON.parse(raw) as unknown[]) : (raw as unknown[]);
    if (!Array.isArray(arr) || arr.length === 0) return "";
    return arr
      .map((o) => {
        if (typeof o === "string") return o;
        if (typeof o === "object" && o !== null) {
          const obj = o as Record<string, unknown>;
          return (obj["label"] ?? obj["name"] ?? obj["value"] ?? String(o)) as string;
        }
        return String(o);
      })
      .join(", ");
  } catch {
    return "";
  }
}

function MetaLabel({ children }: { children: React.ReactNode }) {
  return (
    <div
      style={{
        fontSize: 9,
        fontWeight: 700,
        color: TEAL,
        letterSpacing: 0.6,
        textTransform: "uppercase",
        marginBottom: 2,
      }}
    >
      {children}
    </div>
  );
}

function TotalRow({
  label,
  value,
  accent,
  bold,
  large,
}: {
  label: string;
  value: string;
  accent?: boolean;
  bold?: boolean;
  large?: boolean;
}) {
  const color = accent ? "#0D9488" : "#212121";
  return (
    <div style={{ display: "flex", justifyContent: "space-between", gap: 64, minWidth: 220 }}>
      <span style={{ fontSize: large ? 11 : 12, fontWeight: bold ? 700 : 400, color, letterSpacing: bold ? 0.5 : 0, textTransform: bold ? "uppercase" : "none" }}>
        {label}
      </span>
      <span style={{ fontSize: large ? 16 : 12, fontWeight: bold ? 800 : 400, color }}>
        {value}
      </span>
    </div>
  );
}

function BarcodeDecoration({ code }: { code: string }) {
  const bars = [1, 2, 1, 1, 3, 1, 2, 1, 1, 2, 3, 1, 1, 2, 1, 2, 1, 1, 3, 1, 1, 2, 1, 1, 2, 3, 1, 2, 1, 1, 2, 1, 1, 3, 1, 1, 2, 1, 2, 1];
  return (
    <div style={{ textAlign: "center" }}>
      <div
        style={{
          display: "inline-flex",
          gap: 2,
          height: 40,
          alignItems: "stretch",
        }}
      >
        {bars.map((w, i) => (
          <div
            key={i}
            style={{ width: w * 1.5, background: "#1A1A1A", opacity: i % 5 === 4 ? 0.3 : 1 }}
          />
        ))}
      </div>
      <div
        style={{
          fontSize: 9,
          color: "#9E9E9E",
          marginTop: 6,
          letterSpacing: 2,
          fontVariantNumeric: "tabular-nums",
        }}
      >
        {code}
      </div>
    </div>
  );
}

// ─── Receipt card content (also used for print) ─────────────────────────────

function ReceiptContent({ txn }: { txn: ReceiptTxn }) {
  const kop = txn.order.kopitiam;
  const order = txn.order;

  const totalRefunded = txn.refunds
    .filter((r) => r.status === "completed" || r.status === "approved")
    .reduce((sum, r) => sum + Number(r.amount), 0);

  const latestRefund = txn.refunds.find(
    (r) => r.status === "completed" || r.status === "approved",
  );

  const receiptCode = txn.reference
    ? txn.reference.toUpperCase()
    : `TXN-${txn.id.slice(0, 12).toUpperCase()}`;

  const barcodeNum = `${txn.id.slice(0, 10)}-${order.order_code}`.toUpperCase();

  const addressLines = kop.address.split(",").map((s) => s.trim()).filter(Boolean);

  return (
    <div style={{ fontFamily: "-apple-system, BlinkMacSystemFont, 'Inter', sans-serif" }}>
      {/* ── Header ── */}
      <div style={{ textAlign: "center", marginBottom: 20 }}>
        <div
          style={{
            width: 44,
            height: 44,
            background: "#1A1A1A",
            borderRadius: 10,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            margin: "0 auto 12px",
          }}
        >
          <ShopOutlined style={{ color: "#fff", fontSize: 22 }} />
        </div>
        <div
          style={{
            fontSize: 18,
            fontWeight: 800,
            letterSpacing: 1.5,
            textTransform: "uppercase",
            color: "#1A1A1A",
          }}
        >
          {kop.name}
        </div>
        <div style={{ fontSize: 11, color: "#616161", marginTop: 6, lineHeight: 1.7 }}>
          {addressLines.slice(0, 2).join(", ")}
          {addressLines.length > 2 && (
            <>
              <br />
              {addressLines.slice(2).join(", ")}
            </>
          )}
        </div>
        <div style={{ fontSize: 11, color: "#616161", marginTop: 2 }}>
          Tel. {kop.phone}
        </div>
      </div>

      <Divider style={{ margin: "0 0 14px" }} />

      {/* ── Receipt meta ── */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "12px 16px",
          marginBottom: 14,
        }}
      >
        <div>
          <MetaLabel>Receipt No</MetaLabel>
          <div style={{ fontSize: 13, fontWeight: 700 }}>{receiptCode}</div>
        </div>
        <div style={{ textAlign: "right" }}>
          <MetaLabel>Order ID</MetaLabel>
          <div style={{ fontSize: 13, fontWeight: 700 }}>#{order.order_code}</div>
        </div>
        <div>
          <MetaLabel>Date &amp; Time</MetaLabel>
          <div style={{ fontSize: 12 }}>
            {txn.paid_at ? dayjs(txn.paid_at).format("MMM D, YYYY h:mm A") : "—"}
          </div>
        </div>
        <div style={{ textAlign: "right" }}>
          <MetaLabel>Payment Method</MetaLabel>
          <div style={{ fontSize: 12 }}>
            {PAYMENT_LABELS[txn.method] ?? txn.method.toUpperCase()}
          </div>
        </div>
      </div>

      <Divider style={{ margin: "0 0 14px" }} />

      {/* ── Customer + channel ── */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr auto",
          gap: 8,
          marginBottom: 14,
          alignItems: "start",
        }}
      >
        <div>
          <MetaLabel>Customer Name</MetaLabel>
          <div style={{ fontSize: 14, fontWeight: 600 }}>
            {order.customer?.name ?? "Guest"}
          </div>
        </div>
        <div style={{ textAlign: "right" }}>
          <MetaLabel>Order Channel</MetaLabel>
          <div style={{ marginTop: 4 }}>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 5,
                background: "#F3F4F6",
                borderRadius: 20,
                padding: "3px 10px",
                fontSize: 11,
                fontWeight: 600,
                color: "#374151",
              }}
            >
              {order.type === "delivery" ? (
                <CarOutlined style={{ fontSize: 10 }} />
              ) : (
                <ShoppingOutlined style={{ fontSize: 10 }} />
              )}
              {order.type.toUpperCase()}
            </span>
          </div>
        </div>
      </div>

      <Divider style={{ margin: "0 0 14px" }} />

      {/* ── Items table ── */}
      <div style={{ marginBottom: 14 }}>
        {/* Header row */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 36px 60px 68px",
            gap: "4px 8px",
            borderBottom: "1.5px solid #E5E7EB",
            paddingBottom: 6,
            marginBottom: 8,
          }}
        >
          {["ITEM NAME", "QTY", "PRICE (RM)", "SUBTOTAL (RM)"].map((h, i) => (
            <div
              key={h}
              style={{
                fontSize: 9,
                fontWeight: 700,
                color: "#616161",
                letterSpacing: 0.5,
                textTransform: "uppercase",
                textAlign: i === 0 ? "left" : "right",
              }}
            >
              {h}
            </div>
          ))}
        </div>

        {/* Item rows */}
        {order.items.map((item) => {
          const opts = parseOptions(item.options);
          const subtotal = (Number(item.price) * item.qty).toFixed(2);
          return (
            <div
              key={item.id}
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 36px 60px 68px",
                gap: "2px 8px",
                marginBottom: 10,
              }}
            >
              <div>
                <div style={{ fontSize: 12, fontWeight: 700 }}>{item.name}</div>
                {opts && (
                  <div style={{ fontSize: 10, color: "#16A34A", marginTop: 1 }}>
                    + {opts}
                  </div>
                )}
              </div>
              <div style={{ fontSize: 12, textAlign: "right", paddingTop: 1 }}>{item.qty}</div>
              <div style={{ fontSize: 12, textAlign: "right", paddingTop: 1 }}>
                {Number(item.price).toFixed(2)}
              </div>
              <div style={{ fontSize: 12, textAlign: "right", paddingTop: 1 }}>{subtotal}</div>
            </div>
          );
        })}
      </div>

      <Divider style={{ margin: "0 0 14px" }} />

      {/* ── Totals ── */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 6,
          alignItems: "flex-end",
          marginBottom: 14,
        }}
      >
        <TotalRow label="Subtotal" value={`RM ${Number(order.subtotal).toFixed(2)}`} />
        {Number(order.delivery_fee) > 0 && (
          <TotalRow
            label="Delivery Fee"
            value={`RM ${Number(order.delivery_fee).toFixed(2)}`}
          />
        )}
        {Number(order.sst_amount) > 0 && (
          <TotalRow
            label={`SST (${Math.round(Number(order.sst_amount) / Number(order.subtotal) * 100)}%)`}
            value={`RM ${Number(order.sst_amount).toFixed(2)}`}
          />
        )}
        {Number(order.voucher_discount) > 0 && (
          <TotalRow
            label="Discount"
            value={`– RM ${Number(order.voucher_discount).toFixed(2)}`}
            accent
          />
        )}
        <div
          style={{
            borderTop: "1.5px solid #E5E7EB",
            paddingTop: 10,
            marginTop: 4,
            width: "100%",
            display: "flex",
            justifyContent: "flex-end",
          }}
        >
          <TotalRow
            label="TOTAL PAID"
            value={`RM ${Number(txn.amount).toFixed(2)}`}
            bold
            large
          />
        </div>
      </div>

      {/* ── Refund section ── */}
      {totalRefunded > 0 && latestRefund && (
        <>
          <Divider style={{ margin: "0 0 14px" }} />
          <div
            style={{
              borderLeft: "3px solid #F97316",
              paddingLeft: 12,
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: 8,
              marginBottom: 14,
            }}
          >
            <div>
              <MetaLabel>Refunded Amount</MetaLabel>
              <div style={{ fontSize: 15, fontWeight: 800, color: "#F97316" }}>
                RM {totalRefunded.toFixed(2)}
              </div>
            </div>
            <div style={{ textAlign: "right" }}>
              <MetaLabel>Refund Date</MetaLabel>
              <div style={{ fontSize: 12 }}>
                {dayjs(latestRefund.created_at).format("MMM D, YYYY")}
              </div>
            </div>
          </div>
        </>
      )}

      <Divider style={{ margin: "0 0 16px" }} />

      {/* ── Footer ── */}
      <div style={{ textAlign: "center" }}>
        <div style={{ fontSize: 13, fontWeight: 600, color: "#1A1A1A", marginBottom: 4 }}>
          Thank you for your purchase
        </div>
        <div
          style={{
            fontSize: 9,
            color: "#9E9E9E",
            letterSpacing: 1.2,
            textTransform: "uppercase",
            marginBottom: 18,
          }}
        >
          THIS IS A SYSTEM GENERATED RECEIPT
        </div>
        <BarcodeDecoration code={barcodeNum} />
      </div>
    </div>
  );
}

// ─── Print helper ────────────────────────────────────────────────────────────

function printReceipt(receiptId: string) {
  const el = document.getElementById(receiptId);
  if (!el) return;
  const win = window.open("", "_blank", "width=480,height=760");
  if (!win) return;
  win.document.write(`<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8"/>
  <title>Receipt</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: -apple-system, BlinkMacSystemFont, "Inter", sans-serif; padding: 24px; color: #1A1A1A; }
    @media print { body { padding: 0; } }
    hr { border: none; border-top: 1px solid #E5E7EB; margin: 14px 0; }
    svg { vertical-align: middle; }
  </style>
</head>
<body>${el.innerHTML}</body>
</html>`);
  win.document.close();
  win.focus();
  setTimeout(() => { win.print(); win.close(); }, 300);
}

// ─── Modal ──────────────────────────────────────────────────────────────────

export function ReceiptModal({ open, onClose, txn }: Props) {
  // Inject print style so Ant Design modal doesn't show during page-level print
  useEffect(() => {
    const id = "receipt-modal-print-style";
    if (document.getElementById(id)) return;
    const style = document.createElement("style");
    style.id = id;
    style.textContent = `@media print { body > * { display: none !important; } #${RECEIPT_ID} { display: block !important; } }`;
    document.head.appendChild(style);
    return () => { document.getElementById(id)?.remove(); };
  }, []);

  return (
    <Modal
      open={open}
      onCancel={onClose}
      footer={null}
      width={520}
      centered
      destroyOnHidden
      styles={{
        body: { padding: "0 0 16px" },
        content: { borderRadius: 16, padding: 0, overflow: "hidden" },
      }}
      closable={false}
    >
      {/* Scrollable receipt area */}
      <div
        style={{
          maxHeight: "70vh",
          overflowY: "auto",
          padding: "28px 32px 4px",
        }}
      >
        <div id={RECEIPT_ID}>
          <ReceiptContent txn={txn} />
        </div>
      </div>

      {/* Action bar */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 12,
          padding: "16px 32px 0",
          borderTop: "1px solid #F3F4F6",
        }}
      >
        <Button
          icon={<DownloadOutlined />}
          onClick={() => printReceipt(RECEIPT_ID)}
          style={{ borderRadius: 24, height: 40, paddingInline: 20, fontWeight: 600 }}
        >
          Download PDF
        </Button>
        <Button
          type="primary"
          icon={<PrinterOutlined />}
          onClick={() => printReceipt(RECEIPT_ID)}
          style={{
            borderRadius: 24,
            height: 40,
            paddingInline: 20,
            fontWeight: 600,
            background: "#1A1A1A",
            borderColor: "#1A1A1A",
          }}
        >
          Print Receipt
        </Button>
        <Button
          type="text"
          icon={<CloseOutlined />}
          onClick={onClose}
          style={{ fontWeight: 600, color: "#616161" }}
        >
          Close
        </Button>
      </div>
    </Modal>
  );
}
