import { Switch, Typography, Card, Table, App, Spin } from "antd";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import { useFeatureFlags, useToggleFlag } from "../api/hooks";
import { AdminShell } from "../layouts/AdminShell";

const { Title, Text } = Typography;

interface Flag { id: string; key: string; enabled: boolean; description: string | null }

export function FeatureFlagsScreen() {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const { data, isLoading } = useFeatureFlags();
  const toggle = useToggleFlag();

  const onChange = async (key: string, enabled: boolean) => {
    try {
      await toggle.mutateAsync({ key, enabled });
      void message.success(enabled ? t("featureFlags.flagEnabled", { key }) : t("featureFlags.flagDisabled", { key }));
    } catch {
      void message.error(t("featureFlags.updateFailed"));
    }
  };

  const columns: ColumnsType<Flag> = [
    {
      title: t("featureFlags.colFlagKey"), dataIndex: "key", key: "key", width: 240,
      render: (v) => <Text code>{v}</Text>,
    },
    {
      title: t("featureFlags.colDescription"), dataIndex: "description", key: "desc",
      render: (v) => v ?? <Text type="secondary">{t("featureFlags.noDescription")}</Text>,
    },
    {
      title: t("featureFlags.colEnabled"), dataIndex: "enabled", key: "enabled", width: 100, align: "center",
      render: (v: boolean, row) => (
        <Switch
          checked={v}
          loading={toggle.isPending}
          onChange={(checked) => void onChange(row.key, checked)}
          checkedChildren="ON"
          unCheckedChildren="OFF"
        />
      ),
    },
  ];

  return (
    <AdminShell>
      <Title level={4} style={{ marginBottom: 16 }}>{t("featureFlags.title")}</Title>
      <Card style={{ borderRadius: 12 }}>
        {isLoading ? (
          <div style={{ textAlign: "center", padding: 40 }}><Spin /></div>
        ) : (
          <Table<Flag>
            columns={columns}
            dataSource={data?.data ?? []}
            rowKey="key"
            pagination={false}
            size="middle"
          />
        )}
      </Card>
    </AdminShell>
  );
}
