import { useState } from "react";
import type { ReactNode } from "react";
import { useNavigate } from "react-router-dom";
import { Card, Spin, Table, Dropdown } from "antd";
import {
  DollarOutlined, ContainerOutlined, ShoppingOutlined,
  CarOutlined, FireOutlined, CheckCircleOutlined, EllipsisOutlined,
} from "@ant-design/icons";
import {
  BarChart, Bar, XAxis, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, Label,
} from "recharts";
import { formatDistanceToNow } from "date-fns";
import type { ColumnsType } from "antd/es/table";
import { useDashboardStats, useAdminDailyReport, useAdminOrders, useRevenueReport } from "../api/hooks";
import { AdminShell } from "../layouts/AdminShell";

// ── Colors ──────────────────────────────────────────────────────────────────
const C = {
  orange:  "#F5841F",
  green:   "#4CAF50",
  teal:    "#00BCD4",
  blue:    "#2196F3",
  dark:    "#212121",
  mid:     "#616161",
  grey:    "#9E9E9E",
  bg:      "#F8F8F8",
  white:   "#FFFFFF",
} as const;

// ── Stat Card ────────────────────────────────────────────────────────────────
function StatCard({ label, value, sub, icon, topBorderColor, barPct, barColor }: {
  label: string;
  value: ReactNode;
  sub?: ReactNode;
  icon: ReactNode;
  topBorderColor?: string;
  barPct?: number;
  barColor?: string;
}) {
  return (
    <Card
      style={{
        borderRadius: 12,
        border: "1px solid #EBEBEB",
        borderTop: topBorderColor ? `3px solid ${topBorderColor}` : "1px solid #EBEBEB",
        boxShadow: "0 1px 4px rgba(0,0,0,.05)",
      }}
      styles={{ body: { padding: "20px 24px 16px" } }}
    >
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 11, fontWeight: 600, color: C.grey, letterSpacing: 0.8, textTransform: "uppercase", marginBottom: 10 }}>
            {label}
          </div>
          <div style={{ fontSize: 28, fontWeight: 700, color: C.dark, lineHeight: 1.1 }}>{value}</div>
          {sub && <div style={{ marginTop: 8 }}>{sub}</div>}
        </div>
        <div style={{ flexShrink: 0, marginLeft: 12, paddingTop: 2 }}>
          {icon}
        </div>
      </div>
      {barPct !== undefined && barColor && (
        <div style={{ marginTop: 16, height: 4, background: "#EEEEEE", borderRadius: 2 }}>
          <div style={{ width: `${Math.min(100, barPct)}%`, height: "100%", background: barColor, borderRadius: 2, transition: "width .5s" }} />
        </div>
      )}
    </Card>
  );
}

// ── Status Counter ───────────────────────────────────────────────────────────
function StatusCounter({ label, count, icon, color, iconBg }: {
  label: string; count: number; icon: ReactNode; color: string; iconBg: string;
}) {
  return (
    <Card
      style={{ borderRadius: 12, border: "1px solid #EBEBEB", boxShadow: "0 1px 4px rgba(0,0,0,.05)", flex: 1 }}
      styles={{ body: { padding: "20px 24px" } }}
    >
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
        <div style={{ fontSize: 11, fontWeight: 600, color: C.grey, textTransform: "uppercase", letterSpacing: 0.8, lineHeight: 1.4 }}>
          {label}
        </div>
        <div style={{
          width: 44, height: 44, borderRadius: "50%", background: iconBg, flexShrink: 0,
          display: "flex", alignItems: "center", justifyContent: "center", marginLeft: 12,
        }}>
          {icon}
        </div>
      </div>
      <div style={{ fontSize: 40, fontWeight: 700, color, lineHeight: 1, marginTop: 16, fontVariantNumeric: "tabular-nums" }}>
        {String(count).padStart(2, "0")}
      </div>
    </Card>
  );
}

// ── Top Item Row ─────────────────────────────────────────────────────────────
function TopItemRow({ name, orders, revenue, imageUrl, last }: {
  name: string; orders: number; revenue: string; imageUrl?: string | null; last: boolean;
}) {
  return (
    <div style={{
      display: "flex", alignItems: "center", gap: 14,
      paddingBottom: last ? 0 : 18, marginBottom: last ? 0 : 18,
      borderBottom: last ? "none" : "1px solid #F0F0F0",
    }}>
      {/* Food image / placeholder */}
      {imageUrl ? (
        <img
          src={imageUrl}
          alt={name}
          style={{ width: 52, height: 52, borderRadius: 8, objectFit: "cover", flexShrink: 0, background: "#212121" }}
        />
      ) : (
        <div style={{
          width: 52, height: 52, borderRadius: 8, background: "#212121",
          display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
          color: "#fff", fontSize: 18, fontWeight: 700, letterSpacing: -0.5,
        }}>
          {name.charAt(0).toUpperCase()}
        </div>
      )}
      {/* Name + orders */}
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontWeight: 700, fontSize: 14, color: C.dark, lineHeight: 1.3 }}>{name}</div>
        <div style={{ fontSize: 12, color: C.grey, marginTop: 3, fontWeight: 500, letterSpacing: 0.3 }}>{orders} ORDERS</div>
      </div>
      {/* Revenue + period */}
      <div style={{ textAlign: "right", flexShrink: 0 }}>
        <div style={{ fontWeight: 700, fontSize: 14, color: "#4CAF50" }}>RM {revenue}</div>
        <div style={{ fontSize: 11, color: C.grey, marginTop: 3 }}>Today</div>
      </div>
    </div>
  );
}

// ── Status Badge ─────────────────────────────────────────────────────────────
const STATUS_BADGE: Record<string, { bg: string; color: string; filled?: boolean }> = {
  preparing:         { bg: "#FFF3E0", color: "#F97316" },
  ready:             { bg: "#166534", color: "#fff", filled: true },
  out_for_delivery:  { bg: "#CCFBF1", color: "#0F766E" },
  in_transit:        { bg: "#CCFBF1", color: "#0F766E" },
  delivered:         { bg: "#14532D", color: "#fff", filled: true },
  completed:         { bg: "#14532D", color: "#fff", filled: true },
  cancelled:         { bg: "#F5F5F5", color: "#9E9E9E" },
  confirmed:         { bg: "#EDE7F6", color: "#6A1B9A" },
  pending:           { bg: "#FFF8E1", color: "#F57F17" },
  new:               { bg: "#FFF8E1", color: "#F57F17" },
};

function StatusBadge({ status }: { status: string }) {
  const s = STATUS_BADGE[status] ?? { bg: "#F5F5F5", color: "#9E9E9E" };
  return (
    <span style={{
      background: s.bg, color: s.color, borderRadius: 20,
      padding: s.filled ? "4px 12px" : "4px 12px",
      fontSize: 11, fontWeight: 700, textTransform: "uppercase",
      letterSpacing: 0.5, whiteSpace: "nowrap", display: "inline-block",
    }}>
      {status.replace(/_/g, " ")}
    </span>
  );
}

// ── Order row type (API returns customer joined) ──────────────────────────────
interface RecentOrder {
  id: string;
  order_code: string | null;
  type: string;
  status: string;
  total: string;
  created_at: string;
  customer?: { name?: string | null } | null;
}

// ── Main Component ────────────────────────────────────────────────────────────
export function DashboardScreen() {
  const [chartView, setChartView] = useState<"today" | "weekly">("today");

  const { data: statsData, isLoading: statsLoading } = useDashboardStats();
  const stats = statsData?.data;

  const { data: dailyData, isLoading: dailyLoading } = useAdminDailyReport();
  const daily = dailyData?.data;

  const { data: ordersData, isLoading: ordersLoading } = useAdminOrders({ limit: 8 });
  const recentOrders = (ordersData?.data ?? []) as RecentOrder[];

  const pickupOrders     = stats?.pickupOrders    ?? 0;
  const deliveryOrders   = stats?.deliveryOrders  ?? 0;
  const preparingNow     = stats?.preparingNow    ?? 0;
  const readyForPickup   = stats?.readyForPickup  ?? 0;
  const readyForDelivery = stats?.readyForDelivery ?? 0;

  const totalPD   = pickupOrders + deliveryOrders || 1;
  const pickupPct = Math.round((pickupOrders / totalPD) * 100);

  // Hourly bar chart data (business hours 6 – max(current,18))
  const nowHour  = new Date().getHours();
  const hourlyFiltered = (daily?.hourly ?? [])
    .filter((h) => h.hour >= 6 && h.hour <= Math.max(nowHour, 18));
  const chartData = hourlyFiltered.map((h, i, arr) => ({
    label:     h.hour === nowHour ? "CURRENT" : `${String(h.hour).padStart(2, "0")}:00`,
    revenue:   Number(h.revenue),
    isCurrent: h.hour === nowHour,
    // progress 0→1 from oldest to most recent non-current bar
    progress:  arr.length > 1 ? i / (arr.length - 1) : 1,
  }));

  // Weekly bar chart data (last 7 days)
  const todayStr = new Date().toISOString().slice(0, 10);
  const weekFromDate = new Date(); weekFromDate.setDate(weekFromDate.getDate() - 6);
  const weekFromStr  = weekFromDate.toISOString().slice(0, 10);
  const { data: weeklyRaw } = useRevenueReport({ from: weekFromStr, to: todayStr, granularity: "daily" });
  const weeklyChartData = (weeklyRaw?.data ?? []).map((d, i, arr) => {
    const parts = d.label.split("-");
    const date = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
    const dayLabel = date.toLocaleDateString("en-US", { weekday: "short" }).toUpperCase();
    const isToday = d.label === todayStr;
    return {
      label:     isToday ? "TODAY" : dayLabel,
      revenue:   Number(d.revenue),
      isCurrent: isToday,
      progress:  arr.length > 1 ? i / (arr.length - 1) : 1,
    };
  });

  const activeChartData = chartView === "today" ? chartData : weeklyChartData;

  const donutData = [
    { name: "PICKUP",   value: pickupOrders,  color: "#F97316" },
    { name: "DELIVERY", value: deliveryOrders, color: "#166534" },
  ];

  const navigate = useNavigate();

  const colHeaderStyle: React.CSSProperties = {
    fontSize: 11, fontWeight: 600, color: C.grey, letterSpacing: 0.6, textTransform: "uppercase",
  };

  const recentColumns: ColumnsType<RecentOrder> = [
    {
      title: <span style={colHeaderStyle}>ORDER ID</span>,
      dataIndex: "order_code", key: "order_code", width: 140,
      render: (v, row) => (
        <span style={{ fontWeight: 700, fontSize: 14, color: C.dark }}>#{v ?? row.id.slice(-8)}</span>
      ),
    },
    {
      title: <span style={colHeaderStyle}>CHANNEL</span>,
      dataIndex: "type", key: "type", width: 130,
      render: (v) => (
        <span style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13, color: C.dark }}>
          {v === "delivery"
            ? <CarOutlined style={{ color: "#00BCD4", fontSize: 15 }} />
            : <ShoppingOutlined style={{ color: "#00BCD4", fontSize: 15 }} />}
          <span style={{ textTransform: "capitalize", fontWeight: 500 }}>{v}</span>
        </span>
      ),
    },
    {
      title: <span style={colHeaderStyle}>CUSTOMER</span>,
      key: "customer", width: 160,
      render: (_, row) => (
        <span style={{ fontSize: 13, color: C.dark }}>{(row as RecentOrder).customer?.name ?? "—"}</span>
      ),
    },
    {
      title: <span style={colHeaderStyle}>AMOUNT</span>,
      dataIndex: "total", key: "total", width: 120,
      render: (v) => <span style={{ fontWeight: 700, fontSize: 14, color: C.dark }}>RM {v}</span>,
    },
    {
      title: <span style={colHeaderStyle}>STATUS</span>,
      dataIndex: "status", key: "status", width: 180,
      render: (v) => <StatusBadge status={v} />,
    },
    {
      title: <span style={colHeaderStyle}>TIME</span>,
      dataIndex: "created_at", key: "created_at", width: 140,
      render: (v) => (
        <span style={{ color: C.grey, fontSize: 13 }}>
          {formatDistanceToNow(new Date(v), { addSuffix: true })}
        </span>
      ),
    },
    {
      title: <span style={colHeaderStyle}>ACTION</span>,
      key: "action", width: 70, fixed: "right" as const,
      render: (_, row) => (
        <Dropdown
          trigger={["click"]}
          menu={{
            items: [{
              key: "view",
              label: <span style={{ fontWeight: 600, fontSize: 13 }}>VIEW DETAILS</span>,
              onClick: () => navigate(`/orders?highlight=${row.id}`),
            }],
          }}
        >
          <EllipsisOutlined style={{ fontSize: 18, color: C.mid, cursor: "pointer", padding: "0 4px" }} />
        </Dropdown>
      ),
    },
  ];

  const isLoading = statsLoading || dailyLoading;

  return (
    <AdminShell>
      <div style={{ background: C.bg, minHeight: "100%", padding: "4px 0 32px" }}>
        {isLoading ? (
          <div style={{ textAlign: "center", padding: 80 }}><Spin size="large" /></div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>

            {/* ── Row 1: Four stat cards ─────────────────────────────── */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 16 }}>

              {/* Total Revenue */}
              <StatCard
                label="TOTAL REVENUE"
                topBorderColor={C.orange}
                value={
                  <div style={{ lineHeight: 1.2 }}>
                    <span style={{ fontSize: 15, fontWeight: 600, display: "block", marginBottom: 2 }}>RM</span>
                    {stats?.todayRevenue ?? "0.00"}
                  </div>
                }
                sub={
                  stats?.revChangePercent != null ? (
                    <span style={{ fontSize: 12, fontWeight: 600, color: (stats.revChangePercent ?? 0) >= 0 ? "#15803D" : "#C62828" }}>
                      {(stats.revChangePercent ?? 0) >= 0 ? "↗" : "↘"} {(stats.revChangePercent ?? 0) >= 0 ? "+" : ""}{stats.revChangePercent}% FROM YESTERDAY
                    </span>
                  ) : undefined
                }
                icon={<DollarOutlined style={{ fontSize: 22, color: C.orange }} />}
              />

              {/* Total Orders */}
              <StatCard
                label="TOTAL ORDERS TODAY"
                value={stats?.todayOrders ?? 0}
                icon={<ContainerOutlined style={{ fontSize: 22, color: "#0D9488" }} />}
              />

              {/* Pickup Orders */}
              <StatCard
                label="PICKUP ORDERS"
                value={pickupOrders}
                icon={<ShoppingOutlined style={{ fontSize: 22, color: "#0D9488" }} />}
                barPct={pickupPct}
                barColor={C.green}
              />

              {/* Delivery Orders */}
              <StatCard
                label="DELIVERY ORDERS"
                value={deliveryOrders}
                icon={<CarOutlined style={{ fontSize: 22, color: "#2563EB" }} />}
                barPct={100 - pickupPct}
                barColor={C.blue}
              />
            </div>

            {/* ── Row 2: Status counters + Channel distribution ──────── */}
            <div style={{ display: "grid", gridTemplateColumns: "3fr 2fr", gap: 16 }}>

              {/* Live status counters – 3 individual cards */}
              <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 16 }}>
                <StatusCounter
                  label="PREPARING NOW"
                  count={preparingNow}
                  icon={<FireOutlined style={{ fontSize: 20, color: "#92400E" }} />}
                  color="#92400E"
                  iconBg="#FDE68A"
                />
                <StatusCounter
                  label="READY FOR PICKUP"
                  count={readyForPickup}
                  icon={<CheckCircleOutlined style={{ fontSize: 20, color: "#fff" }} />}
                  color="#059669"
                  iconBg="#10B981"
                />
                <StatusCounter
                  label="READY FOR DELIVERY"
                  count={readyForDelivery}
                  icon={<CarOutlined style={{ fontSize: 20, color: "#2563EB" }} />}
                  color="#2563EB"
                  iconBg="#BFDBFE"
                />
              </div>

              {/* Channel Distribution */}
              <Card
                style={{ borderRadius: 12, border: "1px solid #EBEBEB", boxShadow: "0 1px 4px rgba(0,0,0,.05)" }}
                styles={{ body: { padding: "20px 24px 24px" } }}
              >
                <div style={{ fontSize: 11, fontWeight: 600, color: C.grey, letterSpacing: 0.8, textTransform: "uppercase", marginBottom: 16 }}>
                  CHANNEL DISTRIBUTION
                </div>

                {/* Donut – centered */}
                <div style={{ display: "flex", justifyContent: "center" }}>
                  <PieChart width={160} height={160} style={{ pointerEvents: "none" }}>
                    <Pie
                      data={donutData}
                      cx={80} cy={80}
                      innerRadius={52} outerRadius={76}
                      dataKey="value"
                      startAngle={90} endAngle={-270}
                      strokeWidth={0}
                      isAnimationActive={false}
                    >
                      {donutData.map((d, i) => <Cell key={i} fill={d.color} />)}
                      <Label
                        content={({ viewBox }) => {
                          const { cx = 80, cy = 80 } = (viewBox ?? {}) as { cx?: number; cy?: number };
                          return (
                            <g>
                              <text x={cx} y={cy - 10} textAnchor="middle" dominantBaseline="central"
                                fill={C.dark} fontSize={26} fontWeight={700}>
                                {pickupPct}%
                              </text>
                              <text x={cx} y={cy + 14} textAnchor="middle" dominantBaseline="central"
                                fill={C.grey} fontSize={11}>
                                PICKUP
                              </text>
                            </g>
                          );
                        }}
                      />
                    </Pie>
                  </PieChart>
                </div>

                {/* Legend – horizontal at bottom */}
                <div style={{ display: "flex", justifyContent: "center", gap: 24, marginTop: 20 }}>
                  {donutData.map((d) => (
                    <div key={d.name} style={{ display: "flex", alignItems: "center", gap: 7, fontSize: 12, fontWeight: 600, color: C.mid }}>
                      <div style={{ width: 10, height: 10, borderRadius: "50%", background: d.color, flexShrink: 0 }} />
                      {d.name}
                    </div>
                  ))}
                </div>
              </Card>
            </div>

            {/* ── Row 3: Revenue trend + Top selling items ──────────── */}
            <div style={{ display: "grid", gridTemplateColumns: "3fr 2fr", gap: 16 }}>

              {/* Revenue Trend */}
              <Card
                style={{ borderRadius: 12, border: "1px solid #EBEBEB", boxShadow: "0 1px 4px rgba(0,0,0,.05)" }}
                styles={{ body: { padding: "20px 24px" } }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 16 }}>
                  <div>
                    <div style={{ fontWeight: 700, fontSize: 16, color: C.dark }}>Revenue Trend</div>
                    <div style={{ fontSize: 12, color: C.grey, marginTop: 2 }}>Daily performance across all channels</div>
                  </div>
                  <div style={{ display: "flex", border: "1px solid #E0E0E0", borderRadius: 6, overflow: "hidden" }}>
                    {(["today", "weekly"] as const).map((v) => (
                      <button
                        key={v}
                        onClick={() => setChartView(v)}
                        style={{
                          padding: "4px 14px", fontSize: 12, fontWeight: 600, border: "none",
                          cursor: "pointer", letterSpacing: 0.4,
                          background: chartView === v ? C.orange : C.white,
                          color: chartView === v ? C.white : C.grey,
                          transition: "background .15s, color .15s",
                        }}
                      >
                        {v === "today" ? "TODAY" : "WEEKLY"}
                      </button>
                    ))}
                  </div>
                </div>
                <ResponsiveContainer width="100%" height={220}>
                  <BarChart data={activeChartData} barCategoryGap="18%" margin={{ top: 8, right: 4, bottom: 0, left: 4 }}>
                    <XAxis
                      dataKey="label"
                      tick={({ x, y, payload }) => (
                        <text
                          x={x} y={y + 10}
                          textAnchor="middle"
                          fontSize={10}
                          fill={payload.value === "CURRENT" || payload.value === "TODAY" ? "#F97316" : C.grey}
                          fontWeight={payload.value === "CURRENT" || payload.value === "TODAY" ? 700 : 400}
                        >
                          {payload.value}
                        </text>
                      )}
                      axisLine={false} tickLine={false}
                    />
                    <Tooltip
                      cursor={{ fill: "rgba(0,0,0,0.04)" }}
                      formatter={(v) => [`RM ${Number(v).toFixed(2)}`, "Revenue"]}
                      contentStyle={{ borderRadius: 8, border: "1px solid #EBEBEB", fontSize: 12 }}
                    />
                    <Bar dataKey="revenue" radius={[6, 6, 0, 0]}>
                      {activeChartData.map((entry, i) => {
                        // interpolate peach→amber for non-current bars
                        const t = entry.progress;
                        const fill = entry.isCurrent
                          ? "#F97316"
                          : `rgba(251, ${Math.round(191 + (211 - 191) * (1 - t))}, ${Math.round(36 + (128 - 36) * (1 - t))}, ${(0.45 + 0.55 * t).toFixed(2)})`;
                        return <Cell key={i} fill={fill} />;
                      })}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </Card>

              {/* Top Selling Items */}
              <Card
                title={<span style={{ fontWeight: 700, fontSize: 16, color: C.dark }}>Top Selling Items</span>}
                style={{ borderRadius: 12, border: "1px solid #EBEBEB", boxShadow: "0 1px 4px rgba(0,0,0,.05)" }}
                styles={{ body: { padding: "4px 24px 20px" } }}
                loading={dailyLoading}
              >
                {(daily?.topItems ?? []).length === 0 ? (
                  <span style={{ color: C.grey, fontSize: 13 }}>No item sales yet today</span>
                ) : (
                  (daily?.topItems ?? []).slice(0, 4).map((it, i, arr) => (
                    <TopItemRow
                      key={it.menuItemId}
                      name={it.name}
                      orders={it.qty}
                      revenue={it.revenue}
                      imageUrl={it.imageUrl}
                      last={i === Math.min(arr.length, 4) - 1}
                    />
                  ))
                )}
              </Card>
            </div>

            {/* ── Row 4: Recent Activity ─────────────────────────────── */}
            <Card
              style={{ borderRadius: 12, border: "1px solid #EBEBEB", boxShadow: "0 1px 4px rgba(0,0,0,.05)" }}
              styles={{ body: { padding: "0 0 8px" } }}
              title={
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <span style={{ fontWeight: 700, fontSize: 16, color: C.dark }}>Recent Activity</span>
                  <a href="/orders" style={{ fontSize: 13, color: C.orange, fontWeight: 600, textDecoration: "none", letterSpacing: 0.3 }}>
                    VIEW ALL HISTORY
                  </a>
                </div>
              }
            >
              <Table<RecentOrder>
                dataSource={recentOrders}
                columns={recentColumns}
                rowKey="id"
                pagination={false}
                loading={ordersLoading}
                size="large"
                scroll={{ x: 900 }}
                rowClassName={() => "recent-activity-row"}
              />
            </Card>

          </div>
        )}
      </div>
    </AdminShell>
  );
}

