/* ─── Add / Edit Drawer ───────────────────────────────────── */
type DrawerFormValues = {
  name: string; phone: string; role: "admin" | "stall_staff";
  stallId?: string; pin?: string; confirm_pin?: string;
};

function AddEditDrawer({ open, editing, onClose, stallsData, onSaved }: {
  open: boolean; editing: Staff | null;
  onClose: () => void; stallsData: { id: string; name: string }[];
  onSaved: () => void;
}) {
  const [form] = Form.useForm<DrawerFormValues>();
  const [selectedRole, setSelectedRole] = useState<"admin" | "stall_staff">("stall_staff");
  const createStaff = useCreateStaff();
  const updateStaff = useUpdateStaff();
  const isEdit = !!editing;

  const ROLE_INFO: Record<"admin" | "stall_staff", string> = {
    admin: "Can access all features including reports, menu, and staff management.",
    stall_staff: "Can access POS features and manage orders for their assigned stall.",
  };

  const handleAfterOpen = (visible: boolean) => {
    if (!visible) return;
    if (editing) {
      const r: "admin" | "stall_staff" = editing.role === "admin" || editing.role === "superadmin" ? "admin" : "stall_staff";
      setSelectedRole(r);
      form.setFieldsValue({ name: editing.name, phone: editing.phone, role: r, stallId: editing.stall_id ?? undefined });
    } else {
      setSelectedRole("stall_staff");
      form.resetFields();
      form.setFieldValue("role", "stall_staff");
    }
  };

  const onFinish = async (values: DrawerFormValues) => {
    try {
      if (isEdit && editing) {
        await updateStaff.mutateAsync({ id: editing.id, name: values.name, role: values.role, stallId: values.stallId });
        void message.success("Staff updated successfully");
      } else {
        await createStaff.mutateAsync({ name: values.name, phone: values.phone, role: values.role, stallId: values.stallId, pin: values.pin ?? "" });
        void message.success("Staff added successfully");
      }
      onSaved();
    } catch {
      void message.error("Failed to save staff. Please try again.");
    }
  };

  const loading = createStaff.isPending || updateStaff.isPending;

  return (
    <Drawer
      open={open} onClose={onClose} placement="right" width={440}
      closable={false} afterOpenChange={handleAfterOpen}
      styles={{
        body: { padding: "20px 20px 100px", background: "#F9FAFB" },
        header: { display: "none" },
        footer: { padding: 0, border: "none" },
      }}
      footer={
        <div style={{ padding: "16px 20px", display: "flex", gap: 12, background: "#fff", borderTop: "1px solid #F3F4F6" }}>
          <Button onClick={onClose} style={{ flex: 1, height: 48, borderRadius: 12, fontWeight: 700, fontSize: 15 }}>Cancel</Button>
          <Button type="primary" onClick={() => void form.submit()} loading={loading}
            style={{ flex: 2, height: 48, borderRadius: 12, fontWeight: 800, fontSize: 15, background: "#F97316", borderColor: "#F97316" }}>
            {isEdit ? "Save Changes" : "Save Staff →"}
          </Button>
        </div>
      }
    >
      {/* Custom header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
        <span style={{ fontSize: 22, fontWeight: 900, color: "#212121" }}>{isEdit ? "Edit Staff" : "Add Staff"}</span>
        <button type="button" onClick={onClose}
          style={{ border: "none", background: "transparent", cursor: "pointer", fontSize: 22, color: "#9E9E9E", lineHeight: 1 }}>×</button>
      </div>

      <Form form={form} layout="vertical" onFinish={onFinish}>
        {/* Personal Info */}
        <DrawerSection icon={<UserOutlined />} title="PERSONAL INFO">
          <Form.Item name="name"
            label={<span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5 }}>FULL NAME <span style={{ color: "#F97316" }}>*</span></span>}
            rules={[{ required: true, message: "Full name is required" }]} style={{ marginBottom: 14 }}>
            <Input placeholder="e.g. Wei Kang" style={{ height: 44, borderRadius: 10, fontSize: 14 }} />
          </Form.Item>
          <Form.Item name="phone"
            label={<span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5 }}>PHONE NUMBER <span style={{ color: "#F97316" }}>*</span></span>}
            rules={[{ required: true, message: "Phone number is required" }]} style={{ marginBottom: 0 }}>
            <Input placeholder="+60 12–345 6789" disabled={isEdit} style={{ height: 44, borderRadius: 10, fontSize: 14 }} />
          </Form.Item>
        </DrawerSection>

        {/* Role & Access */}
        <DrawerSection icon={<SafetyCertificateOutlined />} title="ROLE & ACCESS">
          <Form.Item name="role" style={{ marginBottom: 12 }}>
            <div style={{ display: "flex", background: "#F3F4F6", borderRadius: 10, padding: 4 }}>
              {(["admin", "stall_staff"] as const).map(r => (
                <button key={r} type="button"
                  onClick={() => { setSelectedRole(r); form.setFieldValue("role", r); }}
                  style={{
                    flex: 1, padding: "9px 0", borderRadius: 8, border: "none", cursor: "pointer",
                    fontSize: 14, fontWeight: 700,
                    background: selectedRole === r ? "#F97316" : "transparent",
                    color: selectedRole === r ? "#fff" : "#9E9E9E",
                    transition: "all .15s",
                  }}>
                  {r === "admin" ? "Admin" : "Staff"}
                </button>
              ))}
            </div>
          </Form.Item>
          <div style={{ background: "#FFF7ED", borderLeft: "3px solid #F97316", borderRadius: 8, padding: "10px 14px", marginBottom: 16, fontSize: 13, color: "#92400E" }}>
            {ROLE_INFO[selectedRole]}
          </div>
          <Form.Item name="stallId"
            label={<span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5 }}>ASSIGNED TABLET</span>}
            style={{ marginBottom: 0 }}>
            <Select allowClear placeholder="Not Assigned" style={{ height: 44 }}
              options={[
                { value: "", label: "Not Assigned" },
                ...stallsData.map(s => ({ value: s.id, label: s.name })),
              ]}
            />
          </Form.Item>
        </DrawerSection>

        {/* Login PIN — create only */}
        {!isEdit && (
          <DrawerSection icon={<KeyOutlined />} title="LOGIN PIN">
            <Form.Item name="pin"
              label={<span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, display: "block", textAlign: "center" }}>SETUP PIN</span>}
              rules={[
                { required: true, message: "PIN is required" },
                { len: 4, message: "PIN must be exactly 4 digits" },
                { pattern: /^\d+$/, message: "PIN must be numeric" },
              ]} style={{ marginBottom: 14 }}>
              <Input.Password maxLength={4} placeholder="• • • •"
                style={{ height: 56, borderRadius: 10, fontSize: 22, textAlign: "center", letterSpacing: 10 }} />
            </Form.Item>
            <Form.Item name="confirm_pin"
              label={<span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, display: "block", textAlign: "center" }}>CONFIRM PIN</span>}
              dependencies={["pin"]}
              rules={[
                { required: true, message: "Please confirm the PIN" },
                ({ getFieldValue }) => ({
                  validator: (_, value) =>
                    !value || getFieldValue("pin") === value
                      ? Promise.resolve()
                      : Promise.reject(new Error("PINs do not match")),
                }),
              ]} style={{ marginBottom: 14 }}>
              <Input.Password maxLength={4} placeholder="• • • •"
                style={{ height: 56, borderRadius: 10, fontSize: 22, textAlign: "center", letterSpacing: 10 }} />
            </Form.Item>
            <div style={{ display: "flex", gap: 8, alignItems: "flex-start", fontSize: 12, color: "#9E9E9E" }}>
              <InfoCircleOutlined style={{ flexShrink: 0, marginTop: 2 }} />
              <span>Staff will use this PIN to log in on the tablet. Ensure it is unique and confidential.</span>
            </div>
          </DrawerSection>
        )}
      </Form>
    </Drawer>
  );
}

/* ─── Reset PIN Modal ─────────────────────────────────────── */
function ResetPinDrawer({ staff, open, onClose }: { staff: Staff | null; open: boolean; onClose: () => void }) {
  const [form] = Form.useForm<{ newPin: string; confirm: string }>();
  const resetPin = useResetStaffPin();

  const handleClose = () => { form.resetFields(); onClose(); };

  const onFinish = async (values: { newPin: string }) => {
    if (!staff) return;
    try {
      await resetPin.mutateAsync({ id: staff.id, newPin: values.newPin });
      void message.success("PIN reset successfully");
      form.resetFields();
      onClose();
    } catch {
      void message.error("Failed to reset PIN");
    }
  };

  return (
    <Drawer
      open={open} onClose={handleClose} placement="right" width={440}
      closable={false}
      afterOpenChange={(v) => { if (!v) form.resetFields(); }}
      styles={{
        body: { padding: "20px 20px 100px", background: "#F9FAFB" },
        header: { display: "none" },
        footer: { padding: 0, border: "none" },
      }}
      footer={
        <div style={{ padding: "16px 20px", display: "flex", gap: 12, background: "#fff", borderTop: "1px solid #F3F4F6" }}>
          <Button onClick={handleClose} style={{ flex: 1, height: 48, borderRadius: 12, fontWeight: 700, fontSize: 15 }}>Cancel</Button>
          <Button type="primary" onClick={() => void form.submit()} loading={resetPin.isPending}
            style={{ flex: 2, height: 48, borderRadius: 12, fontWeight: 800, fontSize: 15, background: "#F97316", borderColor: "#F97316" }}>
            Reset PIN →
          </Button>
        </div>
      }
    >
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
        <span style={{ fontSize: 22, fontWeight: 900, color: "#212121" }}>Reset PIN</span>
        <button type="button" onClick={handleClose}
          style={{ border: "none", background: "transparent", cursor: "pointer", fontSize: 22, color: "#9E9E9E", lineHeight: 1 }}>×</button>
      </div>

      {staff && (
        <div style={{ display: "flex", alignItems: "center", gap: 12, background: "#fff", borderRadius: 12, border: "1px solid #F3F4F6", padding: "14px 16px", marginBottom: 20 }}>
          <Avatar size={40} style={{ background: getAvatarColor(staff.name), fontSize: 14, fontWeight: 900, flexShrink: 0 }}>
            {getInitials(staff.name)}
          </Avatar>
          <div>
            <div style={{ fontWeight: 700, color: "#212121", fontSize: 14 }}>{staff.name}</div>
            <div style={{ fontSize: 12, color: "#9E9E9E" }}>{staff.phone}</div>
          </div>
        </div>
      )}

      <Form form={form} layout="vertical" onFinish={onFinish}>
        <DrawerSection icon={<KeyOutlined />} title="NEW PIN">
          <Form.Item name="newPin"
            label={<span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, display: "block", textAlign: "center" }}>NEW PIN</span>}
            rules={[{ required: true, message: "PIN is required" }, { len: 4, message: "PIN must be 4 digits" }, { pattern: /^\d+$/, message: "Numeric only" }]}
            style={{ marginBottom: 14 }}>
            <Input.Password maxLength={4} placeholder="• • • •"
              style={{ height: 56, borderRadius: 10, fontSize: 22, textAlign: "center", letterSpacing: 10 }} />
          </Form.Item>
          <Form.Item name="confirm"
            label={<span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, display: "block", textAlign: "center" }}>CONFIRM PIN</span>}
            dependencies={["newPin"]}
            rules={[{ required: true, message: "Please confirm the PIN" }, ({ getFieldValue }) => ({
              validator: (_, value) => !value || getFieldValue("newPin") === value ? Promise.resolve() : Promise.reject(new Error("PINs do not match")),
            })]}
            style={{ marginBottom: 14 }}>
            <Input.Password maxLength={4} placeholder="• • • •"
              style={{ height: 56, borderRadius: 10, fontSize: 22, textAlign: "center", letterSpacing: 10 }} />
          </Form.Item>
          <div style={{ display: "flex", gap: 8, alignItems: "flex-start", fontSize: 12, color: "#9E9E9E" }}>
            <InfoCircleOutlined style={{ flexShrink: 0, marginTop: 2 }} />
            <span>The new PIN will take effect immediately. The staff member will need to use it on their next login.</span>
          </div>
        </DrawerSection>
      </Form>
    </Drawer>
  );
}

/* ─── Screen ─────────────────────────────────────────────── */
type PeriodKey = "today" | "week" | "month";
type RoleFilter = "all" | "admin" | "staff";
type StatusFilter = "all" | "active" | "inactive";

export function StaffScreen() {
  const [period, setPeriod] = useState<PeriodKey>("today");
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState<RoleFilter>("all");
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [editingStaff, setEditingStaff] = useState<Staff | null>(null);
  const [historyStaff, setHistoryStaff] = useState<Staff | null>(null);
  const [historyOpen, setHistoryOpen] = useState(false);
  const [pinStaff, setPinStaff] = useState<Staff | null>(null);
  const [pinOpen, setPinOpen] = useState(false);

  const { data, isLoading } = useAdminStaff();
  const { data: stallsData } = useAdminStalls();
  const deleteStaff = useDeleteStaff();
  const meId = useAuthStore((s) => s.staff?.id);

  const allStaff: Staff[] = data?.data ?? [];
  const stalls = stallsData?.data ?? [];

  const totalStaff   = allStaff.length;
  const activeCount  = allStaff.filter(s => s.is_active).length;
  const inactiveCount = allStaff.filter(s => !s.is_active).length;

  const filteredStaff = useMemo(() => allStaff.filter(s => {
    if (search) {
      const q = search.toLowerCase();
      if (!s.name.toLowerCase().includes(q) && !s.phone.includes(q)) return false;
    }
    if (roleFilter !== "all") {
      const isAdmin = s.role === "admin" || s.role === "superadmin";
      if (roleFilter === "admin" && !isAdmin) return false;
      if (roleFilter === "staff" && isAdmin) return false;
    }
    if (statusFilter === "active"   && !s.is_active) return false;
    if (statusFilter === "inactive" &&  s.is_active) return false;
    return true;
  }), [allStaff, search, roleFilter, statusFilter]);

  const today = dayjs();
  const periodLabel = useMemo(() => {
    if (period === "today") return today.format("MMM D, YYYY");
    if (period === "week")  return `${today.subtract(6, "day").format("MMM D")} - ${today.format("MMM D, YYYY")}`;
    return `${today.startOf("month").format("MMM D")} - ${today.format("MMM D, YYYY")}`;
  }, [period, today]);

  const openCreate = () => { setEditingStaff(null); setDrawerOpen(true); };
  const openEdit   = (s: Staff) => { setEditingStaff(s); setDrawerOpen(true); };

  const columns: ColumnsType<Staff> = [
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, color: "#9E9E9E", letterSpacing: 0.5 }}>STAFF DETAILS</span>,
      key: "details", width: 220,
      render: (_, row) => (
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <Avatar size={38} style={{ background: getAvatarColor(row.name), fontSize: 13, fontWeight: 900, flexShrink: 0 }}>
            {getInitials(row.name)}
          </Avatar>
          <div>
            <div style={{ fontWeight: 700, color: "#212121", fontSize: 14 }}>{row.name}</div>
            <div style={{ fontSize: 12, color: "#9E9E9E", fontFamily: "monospace" }}>{row.phone}</div>
          </div>
        </div>
      ),
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, color: "#9E9E9E", letterSpacing: 0.5 }}>ROLE</span>,
      dataIndex: "role", key: "role", width: 110,
      render: (v: string) => {
        const isAdmin = v === "admin" || v === "superadmin";
        return (
          <span style={{
            padding: "4px 14px", borderRadius: 100, fontSize: 12, fontWeight: 800,
            background: isAdmin ? "#FFF7ED" : "#F3F4F6",
            color: isAdmin ? "#F97316" : "#616161",
          }}>
            {isAdmin ? "ADMIN" : "STAFF"}
          </span>
        );
      },
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, color: "#9E9E9E", letterSpacing: 0.5 }}>ASSIGNED TABLET</span>,
      dataIndex: "tablet_label", key: "tablet", width: 150,
      render: (v: string | null) => (
        <span style={{ color: v ? "#212121" : "#9E9E9E", fontSize: 13 }}>{v ?? "Not assigned"}</span>
      ),
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, color: "#9E9E9E", letterSpacing: 0.5 }}>STATUS</span>,
      dataIndex: "is_active", key: "status", width: 120,
      render: (v: boolean) => (
        <span style={{
          padding: "5px 14px", borderRadius: 100, fontSize: 12, fontWeight: 700,
          background: v ? "#DCFCE7" : "#FEE2E2",
          color: v ? "#166534" : "#DC2626",
        }}>
          {v ? "● Active" : "● Inactive"}
        </span>
      ),
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, color: "#9E9E9E", letterSpacing: 0.5 }}>LAST LOGIN</span>,
      dataIndex: "last_login_at", key: "lastLogin", width: 130,
      render: (v: string | null) => <span style={{ fontSize: 13, color: "#616161" }}>{formatLastLogin(v)}</span>,
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, color: "#9E9E9E", letterSpacing: 0.5 }}>ACTIONS</span>,
      key: "actions", width: 70, align: "center",
      render: (_, row) => {
        const items: MenuProps["items"] = [
          { key: "edit",    label: <span style={{ fontWeight: 600 }}>Edit</span>,           onClick: () => openEdit(row) },
          { key: "history", label: <span style={{ fontWeight: 600 }}>Login History</span>,  onClick: () => { setHistoryStaff(row); setHistoryOpen(true); } },
          { key: "reset",   label: <span style={{ fontWeight: 600 }}>Reset Password</span>, onClick: () => { setPinStaff(row); setPinOpen(true); } },
          { type: "divider" },
          {
            key: "delete", danger: true, disabled: row.id === meId,
            label: <span style={{ fontWeight: 600 }}>Remove Staff</span>,
            onClick: async () => {
              try {
                await deleteStaff.mutateAsync(row.id);
                void message.success("Staff removed");
              } catch {
                void message.error("Failed to remove staff");
              }
            },
          },
        ];
        return (
          <Dropdown menu={{ items }} trigger={["click"]} placement="bottomRight">
            <Button type="text" icon={<MoreOutlined style={{ fontSize: 18 }} />} style={{ color: "#616161", width: 36, height: 36 }} />
          </Dropdown>
        );
      },
    },
  ];

  return (
    <AdminShell>
      {/* Page header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
        <h2 style={{ margin: 0, fontSize: 24, fontWeight: 900, color: "#212121" }}>Staff Management</h2>
        <Button type="primary" icon={<PlusOutlined />} onClick={openCreate}
          style={{ height: 44, borderRadius: 10, fontWeight: 700, fontSize: 14, background: "#F97316", borderColor: "#F97316", paddingInline: 20 }}>
          + Add Staff
        </Button>
      </div>

      {/* Period tabs */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20 }}>
        <div style={{ display: "flex", gap: 4 }}>
          {(["today", "week", "month"] as PeriodKey[]).map(p => (
            <button key={p} type="button" onClick={() => setPeriod(p)} style={{
              padding: "8px 20px", borderRadius: 8, cursor: "pointer",
              border: period === p ? "2px solid #212121" : "1px solid #E5E7EB",
              background: period === p ? "#212121" : "#fff",
              color: period === p ? "#fff" : "#616161",
              fontSize: 13, fontWeight: 600, transition: "all .15s",
            }}>
              {p === "today" ? "Today" : p === "week" ? "This Week" : "This Month"}
            </button>
          ))}
        </div>
        <span style={{ fontSize: 12, color: "#616161" }}>📅 {periodLabel}</span>
      </div>

      {/* Stat cards */}
      <div style={{ display: "flex", gap: 16, marginBottom: 24 }}>
        <div style={{ flex: 1, background: "#fff", borderRadius: 14, border: "1px solid #F3F4F6", borderBottom: "3px solid #F97316", padding: "20px 24px" }}>
          <div style={{ fontSize: 12, color: "#9E9E9E", fontWeight: 600, marginBottom: 6 }}>TOTAL STAFF</div>
          <div style={{ fontSize: 32, fontWeight: 900, color: "#212121" }}>{totalStaff}</div>
          <div style={{ fontSize: 13, color: "#9E9E9E", marginTop: 4 }}>Team Members</div>
        </div>
        <div style={{ flex: 1, background: "#fff", borderRadius: 14, border: "1px solid #F3F4F6", borderBottom: "3px solid #16A34A", padding: "20px 24px" }}>
          <div style={{ fontSize: 12, color: "#9E9E9E", fontWeight: 600, marginBottom: 6 }}>ACTIVE</div>
          <div style={{ fontSize: 32, fontWeight: 900, color: "#16A34A" }}>{activeCount}</div>
          <div style={{ fontSize: 13, color: "#9E9E9E", marginTop: 4 }}>Currently Working</div>
        </div>
        <div style={{ flex: 1, background: "#fff", borderRadius: 14, border: "1px solid #F3F4F6", borderBottom: "3px solid #9E9E9E", padding: "20px 24px" }}>
          <div style={{ fontSize: 12, color: "#9E9E9E", fontWeight: 600, marginBottom: 6 }}>INACTIVE</div>
          <div style={{ fontSize: 32, fontWeight: 900, color: "#212121" }}>{inactiveCount}</div>
          <div style={{ fontSize: 13, color: "#9E9E9E", marginTop: 4 }}>Off Duty</div>
        </div>
      </div>

      {/* Filter bar */}
      <div style={{ display: "flex", gap: 10, marginBottom: 16, alignItems: "center" }}>
        <div style={{ position: "relative", flex: 1, maxWidth: 320 }}>
          <span style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", color: "#9E9E9E", zIndex: 1, pointerEvents: "none" }}>🔍</span>
          <input
            placeholder="Search name or phone..."
            value={search} onChange={e => setSearch(e.target.value)}
            style={{ width: "100%", height: 42, paddingLeft: 36, paddingRight: 12, border: "1px solid #E5E7EB", borderRadius: 10, fontSize: 13, outline: "none", background: "#fff", color: "#212121" }}
          />
        </div>
        <Select value={roleFilter} onChange={v => setRoleFilter(v as RoleFilter)} style={{ width: 140, height: 42 }}
          options={[{ value: "all", label: "All Roles" }, { value: "admin", label: "Admin" }, { value: "staff", label: "Staff" }]} />
        <Select value={statusFilter} onChange={v => setStatusFilter(v as StatusFilter)} style={{ width: 140, height: 42 }}
          options={[{ value: "all", label: "All Status" }, { value: "active", label: "Active" }, { value: "inactive", label: "Inactive" }]} />
      </div>

      {/* Table */}
      <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #F3F4F6", overflow: "hidden" }}>
        <DataTable<Staff>
          columns={columns} dataSource={filteredStaff} loading={isLoading} rowKey="id" sticky={false}
          footer={() => (
            <span style={{ fontSize: 12, color: "#9E9E9E" }}>Showing {filteredStaff.length} of {totalStaff} staff members</span>
          )}
        />
      </div>

      {/* Drawer, Modals */}
      <AddEditDrawer open={drawerOpen} editing={editingStaff} onClose={() => setDrawerOpen(false)} stallsData={stalls} onSaved={() => setDrawerOpen(false)} />
      <LoginHistoryModal staff={historyStaff} open={historyOpen} onClose={() => setHistoryOpen(false)} />
      <ResetPinDrawer staff={pinStaff} open={pinOpen} onClose={() => setPinOpen(false)} />
    </AdminShell>
  );
}
