import { Form, Input, Button } from "antd";
import { LockOutlined, UserOutlined } from "@ant-design/icons";
import { useNavigate } from "react-router-dom";
import { message } from "antd";
import { useAdminLogin } from "../api/hooks";
import { useAuthStore } from "../store/auth";

interface LoginForm { email: string; password: string }

export function LoginScreen() {
  const navigate = useNavigate();
  const login = useAdminLogin();
  const { setTokens, setStaff } = useAuthStore();
  const [form] = Form.useForm<LoginForm>();

  const onFinish = async (values: LoginForm) => {
    try {
      const res = await login.mutateAsync(values);
      setTokens(res.data.tokens.accessToken, res.data.tokens.refreshToken);
      setStaff({
        id: res.data.admin.id,
        name: res.data.admin.name,
        role: res.data.admin.role,
        kopitiamId: res.data.admin.kopitiam_id,
      });
      void navigate("/");
    } catch {
      void message.error("Invalid email or password. Please try again.");
    }
  };

  return (
    <div style={{
      minHeight: "100vh",
      background: "#F9FAFB",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      fontFamily: "inherit",
    }}>
      {/* Two-panel card */}
      <div style={{
        display: "flex",
        borderRadius: 20,
        overflow: "hidden",
        boxShadow: "0 8px 48px rgba(0,0,0,0.10)",
        width: 820,
        minHeight: 500,
        background: "#fff",
      }}>
        {/* Left — branding panel */}
        <div style={{
          width: 340,
          background: "linear-gradient(160deg, #1C1C1C 0%, #2D1B00 100%)",
          padding: "48px 40px",
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          flexShrink: 0,
        }}>
          {/* Logo */}
          <div>
            <div style={{
              width: 52, height: 52, borderRadius: 14,
              background: "#F97316",
              display: "flex", alignItems: "center", justifyContent: "center",
              fontSize: 26, marginBottom: 24,
            }}>
              ☕
            </div>
            <div style={{ fontSize: 22, fontWeight: 900, color: "#fff", marginBottom: 6, letterSpacing: -0.3 }}>
              KawKaw Kopitiam
            </div>
            <div style={{ fontSize: 13, color: "#9E9E9E", lineHeight: 1.6 }}>
              Admin Dashboard — manage your store, staff, menu, and orders all in one place.
            </div>
          </div>

          {/* Feature list */}
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {[
              { icon: "📦", text: "Real-time order management" },
              { icon: "👥", text: "Staff & role management" },
              { icon: "📊", text: "Sales reports & analytics" },
              { icon: "⚙️", text: "Store settings & branding" },
            ].map(f => (
              <div key={f.text} style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span style={{ fontSize: 16 }}>{f.icon}</span>
                <span style={{ fontSize: 13, color: "#D1D5DB" }}>{f.text}</span>
              </div>
            ))}
          </div>

          <div style={{ fontSize: 11, color: "#616161" }}>© 2026 KawKaw Kopitiam</div>
        </div>

        {/* Right — form panel */}
        <div style={{
          flex: 1,
          padding: "52px 48px",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
        }}>
          <div style={{ marginBottom: 36 }}>
            <div style={{ fontSize: 26, fontWeight: 900, color: "#212121", marginBottom: 6 }}>
              Welcome back
            </div>
            <div style={{ fontSize: 14, color: "#9E9E9E" }}>
              Sign in to your admin account to continue
            </div>
          </div>

          <Form form={form} layout="vertical" onFinish={onFinish} autoComplete="off">
            <Form.Item
              name="email"
              label={<span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: "#9E9E9E" }}>EMAIL ADDRESS</span>}
              rules={[{ required: true, message: "Email is required" }, { type: "email", message: "Enter a valid email" }]}
              style={{ marginBottom: 18 }}
            >
              <Input
                prefix={<UserOutlined style={{ color: "#9E9E9E" }} />}
                placeholder="admin@kawkaw.my"
                style={{ height: 48, borderRadius: 12, fontSize: 14 }}
              />
            </Form.Item>

            <Form.Item
              name="password"
              label={<span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: "#9E9E9E" }}>PASSWORD</span>}
              rules={[{ required: true, message: "Password is required" }]}
              style={{ marginBottom: 28 }}
            >
              <Input.Password
                prefix={<LockOutlined style={{ color: "#9E9E9E" }} />}
                placeholder="Enter your password"
                style={{ height: 48, borderRadius: 12, fontSize: 14 }}
              />
            </Form.Item>

            <Form.Item style={{ marginBottom: 0 }}>
              <Button
                htmlType="submit"
                loading={login.isPending}
                block
                style={{
                  height: 50,
                  borderRadius: 12,
                  fontSize: 16,
                  fontWeight: 700,
                  background: "#F97316",
                  borderColor: "#F97316",
                  color: "#fff",
                  letterSpacing: 0.2,
                }}
              >
                Sign In →
              </Button>
            </Form.Item>
          </Form>

          {import.meta.env.DEV && (
            <div style={{
              marginTop: 24,
              padding: "12px 16px",
              background: "#FFF7ED",
              border: "1px solid #FED7AA",
              borderRadius: 10,
              fontSize: 12,
              color: "#92400E",
              lineHeight: 1.8,
            }}>
              <strong style={{ display: "block", marginBottom: 4 }}>🔑 Demo credentials</strong>
              <span style={{ fontFamily: "monospace" }}>admin@kawkaw.my</span> / <span style={{ fontFamily: "monospace" }}>Admin@Kawkaw1</span> — superadmin<br />
              <span style={{ fontFamily: "monospace" }}>admin2@kawkaw.my</span> / <span style={{ fontFamily: "monospace" }}>Admin@Kawkaw2</span> — admin
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
