import { useState } from "react";
import { Button, DatePicker, Input, Select } from "antd";
import {
  DownloadOutlined, FilterOutlined, SearchOutlined,
} from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import type { ActivityLog } from "@kawkaw/shared";
import dayjs from "dayjs";
import { DataTable } from "../components/DataTable";
import { AdminShell } from "../layouts/AdminShell";
import { useActivityLog } from "../api/hooks";

const { RangePicker } = DatePicker;

/* ── Action pill colours ─────────────────────────── */
const ACTION_STYLE: Record<string, { bg: string; color: string }> = {
  create:    { bg: "#DCFCE7", color: "#166534" },
  update:    { bg: "#EFF6FF", color: "#1E40AF" },
  delete:    { bg: "#FEE2E2", color: "#DC2626" },
  login:     { bg: "#F3E8FF", color: "#7E22CE" },
  logout:    { bg: "#F3F4F6", color: "#616161" },
  refund:    { bg: "#FFF7ED", color: "#C2410C" },
  reset_pin: { bg: "#FEF3C7", color: "#92400E" },
};

function ActionPill({ action }: { action: string }) {
  const s = ACTION_STYLE[action] ?? { bg: "#F3F4F6", color: "#616161" };
  return (
    <span style={{
      display: "inline-block", padding: "3px 10px", borderRadius: 20,
      fontSize: 11, fontWeight: 700, letterSpacing: 0.4,
      background: s.bg, color: s.color,
    }}>
      {action.replace("_", " ").toUpperCase()}
    </span>
  );
}

/* ── Screen ──────────────────────────────────────── */
export function ActivityLogScreen() {
  const [page, setPage]           = useState(1);
  const [search, setSearch]       = useState("");
  const [action, setAction]       = useState<string | undefined>();
  const [dateRange, setDateRange] = useState<[string, string] | null>(null);

  const { data, isLoading } = useActivityLog({
    page, limit: 20,
    q: search || undefined,
    action,
    from: dateRange?.[0],
    to: dateRange?.[1],
  });

  const columns: ColumnsType<ActivityLog> = [
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: "#9E9E9E" }}>STAFF</span>,
      key: "staff", width: 160,
      render: (_, row) => {
        const r = row as unknown as { staff?: { name: string } };
        const name = r.staff?.name ?? "System";
        return <span style={{ fontSize: 14, fontWeight: 600, color: "#212121" }}>{name}</span>;
      },
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: "#9E9E9E" }}>ACTION</span>,
      dataIndex: "action", key: "action", width: 130,
      render: (v: string) => <ActionPill action={v} />,
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: "#9E9E9E" }}>ENTITY</span>,
      key: "entity", width: 180,
      render: (_, row) => {
        const r = row as unknown as { entity_type?: string; entity_id?: string };
        if (!r.entity_type) return <span style={{ color: "#9E9E9E" }}>—</span>;
        return (
          <span style={{ fontSize: 13 }}>
            <span style={{ color: "#212121", fontWeight: 600 }}>{r.entity_type}</span>
            {r.entity_id && (
              <span style={{ marginLeft: 6, padding: "1px 6px", background: "#F3F4F6", borderRadius: 4, fontSize: 11, color: "#616161", fontFamily: "monospace" }}>
                {r.entity_id.slice(-8)}
              </span>
            )}
          </span>
        );
      },
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: "#9E9E9E" }}>DETAILS</span>,
      dataIndex: "meta", key: "desc",
      render: (v: Record<string, unknown> | null) =>
        v && Object.keys(v).length > 0
          ? <span style={{ fontSize: 12, color: "#616161", fontFamily: "monospace", wordBreak: "break-all" }}>{JSON.stringify(v)}</span>
          : <span style={{ color: "#9E9E9E" }}>—</span>,
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: "#9E9E9E" }}>IP ADDRESS</span>,
      dataIndex: "ip", key: "ip", width: 140,
      render: (v: string | null) =>
        v
          ? <span style={{ padding: "2px 8px", background: "#F3F4F6", borderRadius: 6, fontSize: 12, fontFamily: "monospace", color: "#616161" }}>{v}</span>
          : <span style={{ color: "#9E9E9E" }}>—</span>,
    },
    {
      title: <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, color: "#9E9E9E" }}>TIME</span>,
      dataIndex: "created_at", key: "time", width: 168,
      render: (v: string) => (
        <span style={{ fontSize: 13, color: "#616161" }}>
          {dayjs(v).format("DD MMM YYYY")}{" "}
          <span style={{ color: "#9E9E9E" }}>{dayjs(v).format("HH:mm:ss")}</span>
        </span>
      ),
      sorter: true,
    },
  ];

  return (
    <AdminShell>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
        <div>
          <h2 style={{ margin: 0, fontSize: 26, fontWeight: 900, color: "#212121" }}>Activity Log</h2>
          {data?.meta.total != null && (
            <div style={{ fontSize: 13, color: "#9E9E9E", marginTop: 2 }}>
              {data.meta.total.toLocaleString()} events recorded
            </div>
          )}
        </div>
        <Button icon={<DownloadOutlined />}
          style={{ height: 44, borderRadius: 10, fontWeight: 700, fontSize: 14, borderColor: "#E5E7EB", color: "#616161", paddingInline: 20 }}>
          Export CSV
        </Button>
      </div>

      {/* Filter bar */}
      <div style={{ display: "flex", gap: 12, marginBottom: 20, flexWrap: "wrap", alignItems: "center" }}>
        <Input
          prefix={<SearchOutlined style={{ color: "#9E9E9E" }} />}
          placeholder="Search staff, entity or details…"
          value={search}
          onChange={e => setSearch(e.target.value)}
          allowClear
          style={{ height: 44, borderRadius: 10, fontSize: 14, width: 280 }}
        />
        <Select
          placeholder={
            <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <FilterOutlined style={{ color: "#9E9E9E" }} />
              <span style={{ color: "#9E9E9E" }}>All actions</span>
            </span>
          }
          allowClear
          value={action}
          onChange={v => { setAction(v as string | undefined); setPage(1); }}
          style={{ height: 44, borderRadius: 10, width: 170 }}
          options={["create","update","delete","login","logout","refund","reset_pin"].map(a => ({
            value: a,
            label: <ActionPill action={a} />,
          }))}
        />
        <RangePicker
          showTime
          onChange={(_, s) => {
            setDateRange(s[0] && s[1] ? [s[0], s[1]] : null);
            setPage(1);
          }}
          style={{ height: 44, borderRadius: 10, fontSize: 14 }}
        />
        {(search || action || dateRange) && (
          <button
            type="button"
            onClick={() => { setSearch(""); setAction(undefined); setDateRange(null); setPage(1); }}
            style={{ border: "none", background: "transparent", color: "#F97316", fontSize: 13, fontWeight: 700, cursor: "pointer", padding: "0 4px" }}
          >
            Clear filters
          </button>
        )}
      </div>

      {/* Table */}
      <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #F3F4F6", overflow: "hidden" }}>
        <DataTable<ActivityLog>
          columns={columns}
          dataSource={data?.data ?? []}
          loading={isLoading}
          sticky={false}
          pagination={{
            current: page,
            total: data?.meta.total ?? 0,
            pageSize: 20,
            onChange: (p) => setPage(p),
          }}
        />
      </div>
    </AdminShell>
  );
}
