import { useState } from "react";
import type React from "react";
import { useNavigate } from "react-router-dom";
import { Button, Drawer, Descriptions, Typography, Divider, Modal, Form, App, Dropdown, Table, Input } from "antd";
import { CarOutlined, ShoppingOutlined, EllipsisOutlined, PhoneOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { Order, OrderItem } from "@kawkaw/shared";
import dayjs from "dayjs";
import { StatusTag } from "../components/StatusTag";
import { AdminShell } from "../layouts/AdminShell";
import { useAdminOrders, useAdminOrder, useAdminCancelOrder, useAdminUpdateOrderStatus, useDashboardStats } from "../api/hooks";

const { Text } = Typography;

// ── Colors ───────────────────────────────────────────────────────────────────
const C = {
  orange: "#F97316", dark: "#212121", mid: "#616161", grey: "#9E9E9E",
  bg: "#F9FAFB", white: "#FFFFFF", green: "#166534", teal: "#00BCD4",
};

// ── Status pill ──────────────────────────────────────────────────────────────
const STATUS_STYLE: Record<string, { bg: string; color: string }> = {
  preparing:        { bg: "#FFF3E0", color: "#F97316" },
  ready:            { bg: "#166534", color: "#fff" },
  out_for_delivery: { bg: "#CCFBF1", color: "#0F766E" },
  in_transit:       { bg: "#F3F4F6", color: "#6B7280" },
  delivered:        { bg: "#14532D", color: "#fff" },
  completed:        { bg: "#14532D", color: "#fff" },
  cancelled:        { bg: "#F3F4F6", color: "#9E9E9E" },
  confirmed:        { bg: "#EDE7F6", color: "#6A1B9A" },
  pending:          { bg: "#FFF8E1", color: "#F57F17" },
  new:              { bg: "#FFF8E1", color: "#F57F17" },
};

function OrderStatusPill({ status }: { status: string }) {
  const s = STATUS_STYLE[status] ?? { bg: "#F3F4F6", color: "#9E9E9E" };
  return (
    <span style={{
      background: s.bg, color: s.color, borderRadius: 20, padding: "4px 14px",
      fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.5,
      whiteSpace: "nowrap", display: "inline-block",
    }}>
      {status.replace(/_/g, " ")}
    </span>
  );
}

// ── Contextual action button ─────────────────────────────────────────────────
function ActionButton({ order, onAction }: {
  order: Order & { type: string };
  onAction: (id: string, status: string) => void;
}) {
  const s = order.status;
  const t = order.type;

  if (s === "preparing")
    return <Button size="small" style={{ background: C.orange, color: "#fff", border: "none", fontWeight: 700, borderRadius: 50, padding: "0 18px", height: 36, fontSize: 13 }} onClick={() => onAction(order.id, "ready")}>Mark Ready</Button>;
  if (s === "ready" && t === "pickup")
    return <Button size="small" style={{ background: "#3B2A1A", color: "#fff", border: "none", fontWeight: 700, borderRadius: 50, padding: "0 18px", height: 36, fontSize: 13 }} onClick={() => onAction(order.id, "completed")}>Picked Up</Button>;
  if (s === "ready" && t === "delivery")
    return <Button size="small" style={{ background: C.orange, color: "#fff", border: "none", fontWeight: 700, borderRadius: 50, padding: "0 18px", height: 36, fontSize: 13 }} onClick={() => onAction(order.id, "out_for_delivery")}>Out for Delivery</Button>;
  if (s === "out_for_delivery" || s === "in_transit")
    return <Button size="small" style={{ background: "#14532D", color: "#fff", border: "none", fontWeight: 700, borderRadius: 50, padding: "0 18px", height: 36, fontSize: 13 }} onClick={() => onAction(order.id, "delivered")}>Delivered</Button>;
  return null;
}

export function OrdersScreen() {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const navigate = useNavigate();
  const [page, setPage] = useState(1);
  const [statusTab, setStatusTab] = useState<string>("all");
  const [typeFilter, setTypeFilter] = useState<string>("all");
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const STATUS_TABS = [
    { key: "all", label: "All" },
    { key: "preparing", label: "Preparing" },
    { key: "ready", label: "Ready" },
    { key: "out_for_delivery", label: "Out for Delivery" },
    { key: "completed", label: "Completed" },
    { key: "cancelled", label: "Cancel" },
  ];

  const { data, isLoading } = useAdminOrders({
    page,
    limit: 20,
    status: statusTab !== "all" ? statusTab : undefined,
    type: typeFilter !== "all" ? typeFilter : undefined,
  });

  const { data: orderDetail } = useAdminOrder(selectedId ?? "");
  const cancelOrder = useAdminCancelOrder();
  const updateStatus = useAdminUpdateOrderStatus();
  const { data: statsData } = useDashboardStats();
  const stats = statsData?.data;
  const activeOrders = (stats?.preparingNow ?? 0) + (stats?.readyForPickup ?? 0) + (stats?.readyForDelivery ?? 0);

  const [cancelTarget, setCancelTarget] = useState<Order | null>(null);
  const [cancelForm] = Form.useForm<{ reason: string }>();

  const TERMINAL = new Set(["cancelled", "completed", "delivered"]);

  const onCancel = async ({ reason }: { reason: string }) => {
    if (!cancelTarget) return;
    try {
      await cancelOrder.mutateAsync({ id: cancelTarget.id, reason });
      void message.success(t("orders.cancelSuccess", "Order cancelled"));
      setCancelTarget(null);
      cancelForm.resetFields();
    } catch {
      void message.error(t("orders.cancelFailed", "Failed to cancel order"));
    }
  };

  const onAction = async (id: string, status: string) => {
    try {
      await updateStatus.mutateAsync({ id, status });
    } catch {
      void message.error("Failed to update order status");
    }
  };

  const colHeader = (label: string) => (
    <span style={{ fontSize: 11, fontWeight: 600, color: C.grey, letterSpacing: 0.6, textTransform: "uppercase" }}>{label}</span>
  );

  const columns: ColumnsType<Order> = [
    {
      title: colHeader("ORDER ID"),
      dataIndex: "order_code", key: "order_code", width: 160,
      render: (v, row) => {
        const ord = row as Order & { type: string };
        return (
          <div>
            <div style={{ fontWeight: 700, fontSize: 14, color: C.dark }}>#{v ?? row.id.slice(-8)}</div>
            <div style={{ display: "flex", alignItems: "center", gap: 4, marginTop: 3 }}>
              {ord.type === "delivery"
                ? <CarOutlined style={{ fontSize: 11, color: C.grey }} />
                : <ShoppingOutlined style={{ fontSize: 11, color: C.grey }} />}
              <span style={{ fontSize: 11, color: C.grey, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.3 }}>{ord.type}</span>
            </div>
          </div>
        );
      },
    },
    {
      title: colHeader("CUSTOMER"),
      key: "customer", width: 180,
      render: (_, row) => {
        const cust = (row as Order & { customer?: { name?: string; phone?: string } | null }).customer;
        return (
          <div>
            <div style={{ fontWeight: 600, fontSize: 13, color: C.dark }}>{cust?.name ?? "—"}</div>
            {cust?.phone && <div style={{ fontSize: 12, color: C.grey, marginTop: 2 }}>{cust.phone}</div>}
          </div>
        );
      },
    },
    {
      title: colHeader("AMOUNT"),
      dataIndex: "total", key: "total", width: 120,
      render: (v) => <span style={{ fontWeight: 700, fontSize: 14, color: C.dark }}>RM{v}</span>,
    },
    {
      title: colHeader("ORDER TIME"),
      dataIndex: "created_at", key: "created_at", width: 140,
      render: (v) => (
        <div>
          <div style={{ fontWeight: 600, fontSize: 13, color: C.dark }}>{dayjs(v).format("h:mm A")}</div>
          <div style={{ fontSize: 12, color: C.grey, marginTop: 2 }}>{dayjs(v).format("D MMM YYYY")}</div>
        </div>
      ),
    },
    {
      title: colHeader("STATUS"),
      dataIndex: "status", key: "status", width: 170,
      render: (v) => <OrderStatusPill status={v} />,
    },
    {
      title: colHeader("ACTION"),
      key: "actions", width: 200, fixed: "right" as const,
      render: (_, row) => {
        const ord = row as Order & { type: string };
        return (
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <ActionButton order={ord} onAction={onAction} />
            <Dropdown
              trigger={["click"]}
              menu={{
                items: [
                  { key: "details", label: <span style={{ fontWeight: 600, fontSize: 13, letterSpacing: 0.4, textTransform: "uppercase" }}>Overview</span>, onClick: () => setSelectedId(row.id) },
                  { key: "overview", label: <span style={{ fontWeight: 600, fontSize: 13, letterSpacing: 0.4, textTransform: "uppercase" }}>Full Details</span>, onClick: () => navigate(`/orders/${row.id}`) },
                  { key: "cancel", label: <span style={{ fontWeight: 600, fontSize: 13, letterSpacing: 0.4, color: TERMINAL.has(row.status) ? C.grey : "#EF4444", textTransform: "uppercase" }}>CANCEL ORDER</span>, disabled: TERMINAL.has(row.status), onClick: () => { cancelForm.resetFields(); setCancelTarget(row); } },
                ],
              }}
            >
              <EllipsisOutlined style={{ fontSize: 20, color: C.mid, cursor: "pointer", padding: "0 4px" }} />
            </Dropdown>
          </div>
        );
      },
    },
  ];

  return (
    <AdminShell>
      <div style={{ background: C.bg, minHeight: "100%", padding: "4px 0 32px" }}>

        {/* Header */}
        <div style={{ marginBottom: 20 }}>
          <h1 style={{ fontSize: 28, fontWeight: 800, color: C.dark, margin: 0 }}>Orders</h1>
          <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 4 }}>
            <span style={{ width: 8, height: 8, borderRadius: "50%", background: "#22C55E", display: "inline-block" }} />
            <span style={{ fontSize: 13, color: C.mid }}>Live Feed: {activeOrders} active orders</span>
          </div>
        </div>

        {/* Filter bar */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
          {/* Status tabs */}
          <div style={{ display: "flex", border: "1px solid #E5E7EB", borderRadius: 8, overflow: "hidden", background: C.white }}>
            {STATUS_TABS.map((tab) => (
              <button
                key={tab.key}
                onClick={() => { setStatusTab(tab.key); setPage(1); }}
                style={{
                  padding: "8px 20px", fontSize: 13, fontWeight: 600, border: "none", cursor: "pointer",
                  background: statusTab === tab.key ? C.orange : C.white,
                  color: statusTab === tab.key ? C.white : C.dark,
                  transition: "background .15s, color .15s",
                  borderRight: "1px solid #E5E7EB",
                }}
              >
                {tab.label}
              </button>
            ))}
          </div>

          {/* Type filter */}
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <span style={{ fontSize: 13, fontWeight: 600, color: C.mid }}>TYPE:</span>
            <div style={{ display: "flex", border: "1px solid #E5E7EB", borderRadius: 6, overflow: "hidden", background: C.white }}>
              {(["all", "pickup", "delivery"] as const).map((tp) => (
                <button
                  key={tp}
                  onClick={() => { setTypeFilter(tp); setPage(1); }}
                  style={{
                    padding: "6px 14px", fontSize: 12, fontWeight: 600, border: "none", cursor: "pointer",
                    background: typeFilter === tp ? C.dark : C.white,
                    color: typeFilter === tp ? C.white : C.dark,
                    transition: "background .15s, color .15s",
                    borderRight: "1px solid #E5E7EB",
                    textTransform: "capitalize",
                  }}
                >
                  {tp === "all" ? "All" : tp.charAt(0).toUpperCase() + tp.slice(1)}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Table */}
        <div style={{ background: C.white, borderRadius: 12, overflow: "hidden", boxShadow: "0 1px 6px rgba(0,0,0,.07)" }}>
          <Table<Order>
            columns={columns}
            dataSource={data?.data ?? []}
            rowKey="id"
            loading={isLoading}
            pagination={{
              current: page,
              total: data?.meta.total ?? 0,
              pageSize: 20,
              onChange: (p) => setPage(p),
              style: { padding: "12px 20px" },
            }}
            size="middle"
            scroll={{ x: 1000 }}
            rowClassName={() => "orders-table-row"}
            components={{
              header: {
                cell: (props: React.ThHTMLAttributes<HTMLTableCellElement>) => (
                  <th
                    {...props}
                    style={{
                      ...props.style,
                      background: "#F9FAFB",
                      padding: "14px 16px",
                      fontSize: 11,
                      fontWeight: 700,
                      color: C.grey,
                      letterSpacing: "0.07em",
                      textTransform: "uppercase",
                      borderBottom: "1px solid #E5E7EB",
                    }}
                  />
                ),
              },
              body: {
                row: (props: React.HTMLAttributes<HTMLTableRowElement>) => (
                  <tr
                    {...props}
                    style={{ ...props.style, borderBottom: "1px solid #F3F4F6" }}
                  />
                ),
                cell: (props: React.TdHTMLAttributes<HTMLTableCellElement>) => (
                  <td {...props} style={{ ...props.style, padding: "20px 16px", verticalAlign: "middle" }} />
                ),
              },
            }}
          />
        </div>

      </div>

      {/* Order Detail Drawer */}
      <Drawer
        open={!!selectedId}
        onClose={() => setSelectedId(null)}
        width={420}
        closeIcon={false}
        styles={{ body: { padding: 0 }, header: { display: "none" } }}
      >
        {orderDetail?.data && (() => {
          const od = orderDetail.data;
          const odExt = od as unknown as {
            order_code?: string;
            customer?: { name?: string; phone?: string } | null;
            payment_method?: string;
            voucher_code?: string;
            special_note?: string | null;
            items?: OrderItem[];
            sst_rate?: number;
          };
          const TERMINAL_STATUSES = new Set(["completed", "delivered", "cancelled"]);
          const custName = odExt.customer?.name ?? "—";
          const initials = custName === "—" ? "?" : custName.split(" ").filter(Boolean).map((w) => w[0]).slice(0, 2).join("").toUpperCase();
          const itemCount = odExt.items?.length ?? 0;
          const ord2 = od as Order & { type: string };

          const drawerActionLabel = (() => {
            const s = od.status; const tp = ord2.type;
            if (s === "preparing") return { label: "Mark as Ready", next: "ready", bg: C.orange };
            if (s === "ready" && tp === "pickup") return { label: "Picked Up", next: "completed", bg: "#3B2A1A" };
            if (s === "ready" && tp === "delivery") return { label: "Out for Delivery", next: "out_for_delivery", bg: C.orange };
            if (s === "out_for_delivery" || s === "in_transit") return { label: "Delivered", next: "delivered", bg: "#14532D" };
            return null;
          })();

          return (
            <div style={{ display: "flex", flexDirection: "column", height: "100%" }}>
              {/* Scrollable body */}
              <div style={{ flex: 1, overflowY: "auto", padding: "28px 24px", paddingBottom: drawerActionLabel ? 100 : 28 }}>

                {/* Close button */}
                <button
                  onClick={() => setSelectedId(null)}
                  style={{ position: "absolute", top: 20, right: 20, background: "none", border: "none", cursor: "pointer", fontSize: 18, color: C.mid, lineHeight: 1, zIndex: 10 }}
                >
                  ✕
                </button>

                {/* Order code + status pill */}
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", paddingRight: 36, marginBottom: 6 }}>
                  <span style={{ fontSize: 26, fontWeight: 800, color: C.dark }}>#{odExt.order_code ?? od.id.slice(-8)}</span>
                  <OrderStatusPill status={od.status} />
                </div>

                {/* Timestamp */}
                <div style={{ fontSize: 13, color: C.grey, marginBottom: 20 }}>
                  {dayjs(od.created_at).format("h:mm A")} • {dayjs(od.created_at).format("D MMM YYYY")}
                </div>

                {/* Channel + Paid tags */}
                <div style={{ display: "flex", gap: 8, marginBottom: 28 }}>
                  <span style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "5px 14px", border: "1px solid #D1D5DB", borderRadius: 20, fontSize: 13, color: C.dark, background: C.white }}>
                    {od.type === "delivery" ? <CarOutlined style={{ fontSize: 13 }} /> : <ShoppingOutlined style={{ fontSize: 13 }} />}
                    {od.type === "delivery" ? "Delivery" : "Self Pickup"}
                  </span>
                  <span style={{ display: "inline-flex", alignItems: "center", gap: 5, padding: "5px 14px", border: "1.5px solid #16A34A", borderRadius: 20, fontSize: 13, color: "#16A34A", fontWeight: 600, background: C.white }}>
                    ✓ Paid
                  </span>
                </div>

                {/* CUSTOMER DETAILS */}
                <div style={{ fontSize: 11, fontWeight: 700, color: C.grey, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 12 }}>Customer Details</div>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <div style={{ width: 44, height: 44, borderRadius: "50%", background: "#E5E7EB", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 15, fontWeight: 700, color: C.mid, flexShrink: 0 }}>
                      {initials}
                    </div>
                    <div>
                      <div style={{ fontSize: 15, fontWeight: 700, color: C.dark }}>{custName}</div>
                      {odExt.customer?.phone && <div style={{ fontSize: 13, color: C.grey, marginTop: 2 }}>{odExt.customer.phone}</div>}
                    </div>
                  </div>
                  {odExt.customer?.phone && (
                    <a
                      href={`tel:${odExt.customer.phone}`}
                      style={{ width: 36, height: 36, borderRadius: "50%", border: "1px solid #E5E7EB", display: "flex", alignItems: "center", justifyContent: "center", color: C.mid, flexShrink: 0, textDecoration: "none" }}
                    >
                      <PhoneOutlined style={{ fontSize: 16 }} />
                    </a>
                  )}
                </div>

                {/* Pickup / delivery time row */}
                <div style={{ background: "#F9FAFB", borderRadius: 8, padding: "10px 14px", display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 28 }}>
                  <span style={{ fontSize: 13, color: "#374151" }}>{od.type === "delivery" ? "Delivery Time" : "Pickup Time"}</span>
                  <span style={{ fontSize: 13, fontWeight: 700, color: C.dark }}>ASAP</span>
                </div>

                {/* ORDER ITEMS */}
                <div style={{ fontSize: 11, fontWeight: 700, color: C.grey, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 16 }}>Order Items ({itemCount})</div>
                {odExt.items?.map((item, i) => {
                  const extrasTotal = item.options.reduce((s, o) => s + parseFloat(o.extra_charge), 0);
                  const unitPrice = parseFloat(item.price) + extrasTotal;
                  return (
                    <div key={i} style={{ display: "flex", alignItems: "flex-start", gap: 12, marginBottom: 20 }}>
                      <div style={{ width: 52, height: 52, borderRadius: 8, background: "#F3F4F6", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, fontWeight: 700, color: C.grey, flexShrink: 0 }}>
                        {item.name.charAt(0)}
                      </div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontWeight: 700, fontSize: 13.5, color: C.dark, lineHeight: 1.35 }}>{item.name}</div>
                        {(item.options.length > 0 || item.note) && (
                          <div style={{ fontSize: 12, color: C.grey, marginTop: 3 }}>
                            {[item.options.map((o) => o.label).join(", "), item.note].filter(Boolean).join(" • ")}
                          </div>
                        )}
                        <div style={{ fontSize: 13, color: C.mid, marginTop: 4, fontWeight: 500 }}>RM {unitPrice.toFixed(2)}</div>
                      </div>
                      <div style={{ minWidth: 32, height: 32, borderRadius: "50%", background: "#FFF3E0", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 700, color: C.orange, flexShrink: 0 }}>
                        {item.qty}×
                      </div>
                    </div>
                  );
                })}

                {/* Price breakdown */}
                <div style={{ borderTop: "1px solid #F3F4F6", paddingTop: 16, marginTop: 4 }}>
                  {([
                    { label: "Subtotal", value: `RM ${od.subtotal}` },
                    parseFloat(od.voucher_discount) > 0 ? { label: `Discount (${odExt.voucher_code ?? "VOUCHER"})`, value: `-RM ${od.voucher_discount}`, red: true } : null,
                    parseFloat(od.sst_amount) > 0 ? { label: `SST (${odExt.sst_rate ?? 8}%)`, value: `RM ${od.sst_amount}` } : null,
                    parseFloat(od.delivery_fee) > 0 ? { label: "Delivery Fee", value: `RM ${od.delivery_fee}` } : null,
                  ] as Array<{ label: string; value: string; red?: boolean } | null>).filter(Boolean).map((row, i) => row && (
                    <div key={i} style={{ display: "flex", justifyContent: "space-between", marginBottom: 10 }}>
                      <span style={{ fontSize: 13, color: "#374151" }}>{row.label}</span>
                      <span style={{ fontSize: 13, color: row.red ? "#EF4444" : C.dark }}>{row.value}</span>
                    </div>
                  ))}
                </div>

                {/* Total Amount */}
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "14px 0", borderTop: "2px solid #F3F4F6", marginTop: 4 }}>
                  <span style={{ fontSize: 16, fontWeight: 800, color: C.dark }}>Total Amount</span>
                  <span style={{ fontSize: 22, fontWeight: 800, color: C.orange }}>RM {od.total}</span>
                </div>

                {/* Payment method */}
                <div style={{ background: "#F9FAFB", borderRadius: 10, padding: "12px 16px", marginTop: 4 }}>
                  <div style={{ fontSize: 10, fontWeight: 700, color: C.grey, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 8 }}>Payment Method</div>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <span style={{ fontSize: 14, fontWeight: 600, color: C.dark }}>{odExt.payment_method ?? "—"}</span>
                    <span style={{ background: "#14532D", color: "#fff", fontSize: 11, fontWeight: 700, padding: "3px 10px", borderRadius: 4, letterSpacing: 0.5 }}>PAID</span>
                  </div>
                </div>

              </div>

              {/* Footer actions */}
              {!TERMINAL_STATUSES.has(od.status) && (
                <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, background: C.white, borderTop: "1px solid #E5E7EB", padding: "16px 24px", display: "flex", gap: 12 }}>
                  <Button
                    style={{ flex: 1, height: 48, fontWeight: 600, borderRadius: 10, fontSize: 14 }}
                    onClick={() => { setSelectedId(null); cancelForm.resetFields(); setCancelTarget(od); }}
                  >
                    Cancel Order
                  </Button>
                  {drawerActionLabel && (
                    <Button
                      style={{ flex: 1.5, height: 48, fontWeight: 700, borderRadius: 10, fontSize: 14, background: drawerActionLabel.bg, color: "#fff", border: "none" }}
                      onClick={async () => { await onAction(od.id, drawerActionLabel.next); setSelectedId(null); }}
                    >
                      {drawerActionLabel.label}
                    </Button>
                  )}
                </div>
              )}
            </div>
          );
        })()}
      </Drawer>

      <Modal
        open={!!cancelTarget}
        title={t("orders.cancelModalTitle", "Cancel order")}
        onCancel={() => { setCancelTarget(null); cancelForm.resetFields(); }}
        onOk={() => void cancelForm.submit()}
        okText={t("orders.cancelConfirm", "Cancel order")}
        okButtonProps={{ danger: true, loading: cancelOrder.isPending }}
        cancelText={t("common.back", "Back")}
      >
        <p style={{ color: "#6B7280", marginBottom: 12 }}>
          {t("orders.cancelHint", "This will mark the order as cancelled and notify the customer. Refunds (if any) must be issued separately from the Refunds screen.")}
        </p>
        <Form form={cancelForm} layout="vertical" onFinish={onCancel}>
          <Form.Item
            name="reason"
            label={t("orders.cancelReason", "Reason (visible in activity log)")}
            rules={[{ required: true, min: 3, max: 500 }]}
          >
            <Input.TextArea rows={3} maxLength={500} showCount placeholder={t("orders.cancelReasonPlaceholder", "e.g. duplicate order, customer requested cancellation, ingredient shortage…")} />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
