import { useState } from "react";
import {
  Button, Modal, Form, Input, InputNumber, Switch,
  Space, Typography, message, Popconfirm,
} from "antd";
import { PlusOutlined, EditOutlined, DeleteOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { PromoBanner } from "@kawkaw/shared";
import { DataTable } from "../components/DataTable";
import { AdminShell } from "../layouts/AdminShell";
import { ImageUpload } from "../components/ImageUpload";
import { useAdminBanners, useCreateBanner, useUpdateBanner, useDeleteBanner } from "../api/hooks";

const { Title } = Typography;

export function BannersScreen() {
  const { t } = useTranslation();
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<PromoBanner | null>(null);
  const [form] = Form.useForm();

  const previewTitle = Form.useWatch("title", form);
  const previewTag = Form.useWatch("tag", form);
  const previewTagColor = Form.useWatch("tag_color", form);
  const previewImageUrl = Form.useWatch("image_url", form);

  const { data, isLoading } = useAdminBanners();
  const createBanner = useCreateBanner();
  const updateBanner = useUpdateBanner();
  const deleteBanner = useDeleteBanner();

  const openCreate = () => { setEditing(null); form.resetFields(); setModalOpen(true); };
  const openEdit = (b: PromoBanner) => {
    setEditing(b);
    form.setFieldsValue(b);
    setModalOpen(true);
  };

  const onSave = async (values: Record<string, unknown>) => {
    try {
      if (editing) {
        await updateBanner.mutateAsync({ id: editing.id, ...values });
        void message.success(t("banners.updateSuccess", "Banner updated"));
      } else {
        await createBanner.mutateAsync(values);
        void message.success(t("banners.createSuccess", "Banner created"));
      }
      setModalOpen(false);
    } catch {
      void message.error(t("banners.saveFailed", "Failed to save banner"));
    }
  };

  const columns: ColumnsType<PromoBanner> = [
    {
      title: t("banners.colOrder", "Order"),
      dataIndex: "sort_order",
      key: "sort_order",
      width: 80,
    },
    {
      title: t("banners.colTag", "Tag"),
      dataIndex: "tag",
      key: "tag",
      width: 140,
      render: (tag: string, row: PromoBanner) => (
        <span
          style={{
            background: row.tag_color,
            color: "#fff",
            padding: "2px 8px",
            borderRadius: 4,
            fontSize: 12,
            fontWeight: 600,
          }}
        >
          {tag}
        </span>
      ),
    },
    {
      title: t("banners.colTitle", "Title"),
      dataIndex: "title",
      key: "title",
    },
    {
      title: t("banners.colPreview", "Preview"),
      key: "preview",
      width: 120,
      render: (_: unknown, row: PromoBanner) => (
        <div style={{ width: 100, height: 36, borderRadius: 4, overflow: "hidden", position: "relative", background: row.bg_gradient, border: "1px solid #f0f0f0" }}>
          {row.image_url && (
            <img src={row.image_url} alt="" style={{ width: "100%", height: "100%", objectFit: "cover", position: "absolute", inset: 0 }} />
          )}
        </div>
      ),
    },
    {
      title: t("banners.colActive", "Active"),
      dataIndex: "is_active",
      key: "is_active",
      width: 80,
      render: (v: boolean) => (
        <Switch checked={v} disabled size="small" />
      ),
    },
    {
      title: "",
      key: "actions",
      width: 110,
      fixed: "right",
      render: (_, row) => (
        <Space size={4}>
          <Button size="small" icon={<EditOutlined />} onClick={() => openEdit(row)} />
          <Popconfirm
            title={t("banners.deleteConfirm", "Delete this banner?")}
            okText={t("common.yes", "Yes")}
            cancelText={t("common.no", "No")}
            onConfirm={async () => {
              try {
                await deleteBanner.mutateAsync(row.id);
                void message.success(t("banners.deleteSuccess", "Banner deleted"));
              } catch {
                void message.error(t("banners.deleteFailed", "Failed to delete banner"));
              }
            }}
          >
            <Button size="small" danger icon={<DeleteOutlined />} />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  const banners = (data as { data: PromoBanner[] } | undefined)?.data ?? [];

  return (
    <AdminShell>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <Title level={4} style={{ margin: 0 }}>{t("nav.banners", "Promo Banners")}</Title>
        <Button type="primary" icon={<PlusOutlined />} onClick={openCreate}>
          {t("banners.add", "Add Banner")}
        </Button>
      </div>

      <DataTable<PromoBanner>
        columns={columns}
        dataSource={banners}
        rowKey="id"
        loading={isLoading}
      />

      <Modal
        open={modalOpen}
        title={editing ? t("banners.editTitle", "Edit Banner") : t("banners.createTitle", "New Banner")}
        onCancel={() => setModalOpen(false)}
        onOk={() => form.submit()}
        confirmLoading={createBanner.isPending || updateBanner.isPending}
        destroyOnHidden
      >
        <Form form={form} layout="vertical" onFinish={onSave}>
          <Form.Item
            name="title"
            label={t("banners.fieldTitle", "Title")}
            rules={[{ required: true, message: t("banners.titleRequired", "Title is required") }]}
          >
            <Input placeholder={t("banners.titlePlaceholder", "e.g. Raya Special Deals")} />
          </Form.Item>

          <Form.Item
            name="tag"
            label={t("banners.fieldTag", "Tag")}
            rules={[{ required: true, message: t("banners.tagRequired", "Tag is required") }]}
          >
            <Input placeholder={t("banners.tagPlaceholder", "e.g. Promotion")} />
          </Form.Item>

          <Form.Item
            name="tag_color"
            label={t("banners.fieldTagColor", "Tag Color")}
            initialValue="#9c3e00"
          >
            <Input placeholder="#9c3e00" />
          </Form.Item>

          <Form.Item name="image_url" label={t("banners.fieldImageUrl", "Banner Image")}>
            <ImageUpload folder="banners" />
          </Form.Item>

          {/* Live banner preview */}
          {(previewTitle || previewTag || previewImageUrl) && (
            <div style={{ marginBottom: 24 }}>
              <div style={{ fontSize: 12, color: "#888", marginBottom: 8 }}>Preview</div>
              <div style={{
                width: "100%", height: 160, borderRadius: 16, overflow: "hidden",
                position: "relative",
                boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
              }}>
                {previewImageUrl && (
                  <img
                    src={previewImageUrl}
                    alt="banner preview"
                    style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }}
                  />
                )}
                <div style={{
                  position: "absolute", inset: 0, display: "flex", flexDirection: "column",
                  justifyContent: "flex-end", padding: 20,
                  background: "linear-gradient(0deg, rgba(0, 0, 0, 0.60) 0%, rgba(0, 0, 0, 0.00) 100%)",
                }}>
                  {previewTag && (
                    <div style={{
                      background: previewTagColor || "#9c3e00", borderRadius: 999,
                      alignSelf: "flex-start", padding: "3px 10px", marginBottom: 8,
                    }}>
                      <span style={{ fontSize: 10, fontWeight: 700, color: "#fff", letterSpacing: 1, textTransform: "uppercase" }}>
                        {previewTag}
                      </span>
                    </div>
                  )}
                  {previewTitle && (
                    <div style={{ fontSize: 20, fontWeight: 700, color: "#fff", lineHeight: 1.25 }}>
                      {previewTitle}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          <Form.Item
            name="sort_order"
            label={t("banners.fieldOrder", "Sort Order")}
            initialValue={0}
          >
            <InputNumber min={0} style={{ width: "100%" }} />
          </Form.Item>

          <Form.Item
            name="is_active"
            label={t("banners.fieldActive", "Active")}
            valuePropName="checked"
            initialValue={true}
          >
            <Switch />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
