import { useState } from "react";
import {
  Select, Button, Modal, Form, Input, InputNumber,
  Typography, Space, Popconfirm, App, Tag, Table,
} from "antd";
import { PlusOutlined, EditOutlined, DeleteOutlined, CloseOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import { AdminShell } from "../layouts/AdminShell";
import {
  useAdminStalls,
  useAdminMenuCategories, useCreateMenuCategory, useUpdateMenuCategory, useDeleteMenuCategory,
  type MenuCategoryRow,
} from "../api/hooks";

const { Title, Text } = Typography;

export function CategoriesScreen() {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<MenuCategoryRow | null>(null);
  const [form] = Form.useForm();
  const [sugarChoices, setSugarChoices] = useState<string[]>([]);
  const [newSugarChoice, setNewSugarChoice] = useState("");
  const [iceChoices, setIceChoices] = useState<string[]>([]);
  const [newIceChoice, setNewIceChoice] = useState("");

  const { data: stallsData } = useAdminStalls();
  const stallOptions = (stallsData?.data ?? []).map((s) => ({ value: s.id, label: s.name }));
  const stallNameMap = Object.fromEntries((stallsData?.data ?? []).map((s) => [s.id, s.name]));

  const { data: catData, isLoading } = useAdminMenuCategories();
  const categories: MenuCategoryRow[] = catData?.data ?? [];

  const createCat = useCreateMenuCategory();
  const updateCat = useUpdateMenuCategory();
  const deleteCat = useDeleteMenuCategory();

  const openCreate = () => {
    setEditing(null);
    form.resetFields();
    form.setFieldsValue({ sort_order: categories.length });
    setSugarChoices([]);
    setNewSugarChoice("");
    setIceChoices([]);
    setNewIceChoice("");
    setModalOpen(true);
  };

  const openEdit = (c: MenuCategoryRow) => {
    setEditing(c);
    form.setFieldsValue({ name: c.name, emoji: c.emoji ?? undefined, sort_order: c.sort_order, stall_id: c.stall_id ?? undefined });
    setSugarChoices(c.default_sugar_choices ?? []);
    setNewSugarChoice("");
    setIceChoices(c.default_ice_choices ?? []);
    setNewIceChoice("");
    setModalOpen(true);
  };

  const addSugarChoice = () => {
    const trimmed = newSugarChoice.trim();
    if (!trimmed || sugarChoices.includes(trimmed)) return;
    setSugarChoices([...sugarChoices, trimmed]);
    setNewSugarChoice("");
  };

  const removeSugarChoice = (label: string) => {
    setSugarChoices(sugarChoices.filter((c) => c !== label));
  };

  const addIceChoice = () => {
    const trimmed = newIceChoice.trim();
    if (!trimmed || iceChoices.includes(trimmed)) return;
    setIceChoices([...iceChoices, trimmed]);
    setNewIceChoice("");
  };

  const removeIceChoice = (label: string) => {
    setIceChoices(iceChoices.filter((c) => c !== label));
  };

  const onSave = async () => {
    try {
      const vals = await form.validateFields();
      const sugarPayload = sugarChoices.length > 0 ? sugarChoices : null;
      const icePayload = iceChoices.length > 0 ? iceChoices : null;
      if (editing) {
        await updateCat.mutateAsync({
          id: editing.id,
          name: vals.name,
          emoji: vals.emoji ?? null,
          sort_order: vals.sort_order,
          stall_id: vals.stall_id ?? null,
          default_sugar_choices: sugarPayload,
          default_ice_choices: icePayload,
        });
        void message.success(t("menu.categoryUpdateSuccess"));
      } else {
        await createCat.mutateAsync({
          name: vals.name,
          emoji: vals.emoji,
          sort_order: vals.sort_order ?? 0,
          stall_id: vals.stall_id,
          default_sugar_choices: sugarPayload,
          default_ice_choices: icePayload,
        });
        void message.success(t("menu.categoryCreateSuccess"));
      }
      setModalOpen(false);
    } catch {
      void message.error(t("menu.saveFailed"));
    }
  };

  const onDelete = async (c: MenuCategoryRow) => {
    try {
      await deleteCat.mutateAsync({ id: c.id });
      void message.success(t("menu.categoryDeleteSuccess"));
    } catch {
      void message.error(t("menu.deleteFailed"));
    }
  };

  return (
    <AdminShell>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
        <Title level={4} style={{ margin: 0 }}>
          {t("nav.categories", "Menu Categories")}
        </Title>
        <Button
          type="primary"
          icon={<PlusOutlined />}
          onClick={openCreate}
          style={{ background: "#D97706", borderColor: "#D97706" }}
        >
          {t("menu.addCategory")}
        </Button>
      </div>

      {isLoading ? (
        <div style={{ padding: 60, textAlign: "center", color: "#9CA3AF" }}>
          {t("common.loading", "Loading…")}
        </div>
      ) : (
        <Table
          rowKey="id"
          dataSource={categories}
          pagination={false}
          style={{ maxWidth: 800 }}
          columns={[
            {
              title: t("menu.categoryEmoji", "Emoji"),
              dataIndex: "emoji",
              key: "emoji",
              width: 64,
              render: (emoji: string | null) =>
                emoji ? <span style={{ fontSize: 24, lineHeight: 1 }}>{emoji}</span> : <Text type="secondary">—</Text>,
            },
            {
              title: t("menu.categoryName", "Name"),
              dataIndex: "name",
              key: "name",
              render: (name: string) => <Text strong>{name}</Text>,
            },
            {
              title: t("common.stall", "Stall"),
              dataIndex: "stall_id",
              key: "stall",
              width: 160,
              render: (stall_id: string | null) =>
                stall_id
                  ? <Tag color="orange">{stallNameMap[stall_id] ?? stall_id}</Tag>
                  : <Tag color="default">{t("menu.globalCategory", "Global")}</Tag>,
            },
            {
              title: t("menu.categorySortOrder", "Sort Order"),
              dataIndex: "sort_order",
              key: "sort_order",
              width: 110,
              defaultSortOrder: "ascend",
              sorter: (a: MenuCategoryRow, b: MenuCategoryRow) =>
                a.sort_order !== b.sort_order
                  ? a.sort_order - b.sort_order
                  : a.name.localeCompare(b.name),
              render: (v: number) => <Tag>{v}</Tag>,
            },
            {
              title: "",
              key: "actions",
              width: 90,
              render: (_: unknown, c: MenuCategoryRow) => (
                <Space>
                  <Button size="small" icon={<EditOutlined />} onClick={() => openEdit(c)} />
                  <Popconfirm
                    title={t("common.confirmDelete")}
                    onConfirm={() => void onDelete(c)}
                    okType="danger"
                  >
                    <Button size="small" danger icon={<DeleteOutlined />} />
                  </Popconfirm>
                </Space>
              ),
            },
          ]}
        />
      )}

      <Modal
        open={modalOpen}
        title={editing ? t("menu.categoryName") : t("menu.addCategory")}
        onCancel={() => setModalOpen(false)}
        onOk={() => void onSave()}
        okText={t("common.save")}
        okButtonProps={{
          loading: createCat.isPending || updateCat.isPending,
          style: { background: "#D97706", borderColor: "#D97706" },
        }}
      >
        <Form form={form} layout="vertical">
          <Form.Item name="emoji" label={t("menu.categoryEmoji", "Emoji")} extra={t("menu.categoryEmojiHint", "Paste a single emoji (e.g. ☕)") }>
            <Input maxLength={8} />
          </Form.Item>
          <Form.Item name="name" label={t("menu.categoryName")} rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="sort_order" label={t("menu.categorySortOrder")}>
            <InputNumber min={0} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item
            name="stall_id"
            label={t("common.stall", "Stall")}
            extra={t("menu.categoryStallOptional", "Optional \u2014 leave blank for a global category")}
          >
            <Select allowClear options={stallOptions} placeholder={t("common.selectStall")} />
          </Form.Item>

          <Form.Item
            label={t("menu.categorySugarChoices", "Sugar Level Choices")}
            tooltip={t("menu.categorySugarChoicesTooltip", "If set, these choices are used for items in this category. Leave empty to use app defaults.")}
          >
            <Space direction="vertical" style={{ width: "100%" }}>
              <Space wrap>
                {sugarChoices.length === 0 ? (
                  <Text type="secondary" style={{ fontSize: 12 }}>{t("menu.categorySugarChoicesEmpty", "Using app default")}</Text>
                ) : (
                  sugarChoices.map((choice) => (
                    <Tag
                      key={choice}
                      closable
                      onClose={() => removeSugarChoice(choice)}
                      closeIcon={<CloseOutlined />}
                      style={{ fontSize: 13, padding: "4px 10px", borderRadius: 8 }}
                    >
                      {choice}
                    </Tag>
                  ))
                )}
              </Space>
              <Space.Compact style={{ width: "100%" }}>
                <Input
                  value={newSugarChoice}
                  onChange={(e) => setNewSugarChoice(e.target.value)}
                  onPressEnter={addSugarChoice}
                  placeholder={t("menu.categorySugarChoicesPlaceholder", "e.g. 25% Less Sweet")}
                  maxLength={50}
                />
                <Button icon={<PlusOutlined />} onClick={addSugarChoice}>
                  {t("settings.addBtn", "Add")}
                </Button>
              </Space.Compact>
            </Space>
          </Form.Item>

          <Form.Item
            label={t("menu.categoryIceChoices", "Ice Level Choices")}
            tooltip={t("menu.categoryIceChoicesTooltip", "If set, these choices are used for items in this category. Leave empty to use app defaults.")}
          >
            <Space direction="vertical" style={{ width: "100%" }}>
              <Space wrap>
                {iceChoices.length === 0 ? (
                  <Text type="secondary" style={{ fontSize: 12 }}>{t("menu.categoryIceChoicesEmpty", "Using app default")}</Text>
                ) : (
                  iceChoices.map((choice) => (
                    <Tag
                      key={choice}
                      closable
                      onClose={() => removeIceChoice(choice)}
                      closeIcon={<CloseOutlined />}
                      style={{ fontSize: 13, padding: "4px 10px", borderRadius: 8 }}
                    >
                      {choice}
                    </Tag>
                  ))
                )}
              </Space>
              <Space.Compact style={{ width: "100%" }}>
                <Input
                  value={newIceChoice}
                  onChange={(e) => setNewIceChoice(e.target.value)}
                  onPressEnter={addIceChoice}
                  placeholder={t("menu.categoryIceChoicesPlaceholder", "e.g. Less Ice")}
                  maxLength={50}
                />
                <Button icon={<PlusOutlined />} onClick={addIceChoice}>
                  {t("settings.addBtn", "Add")}
                </Button>
              </Space.Compact>
            </Space>
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
